// Preview only. AI self-reviewed; human review is still required.
export const translations = {
  es: {
    "ghf-001": {prompt:"Un equipo de políticas necesita explicar cómo cambió un documento durante varios meses. ¿Qué proporciona el control de versiones?",choices:["Un historial registrado de los cambios","La garantía de que todos los cambios son correctos","Aprobación legal automática","Un reemplazo de la revisión de documentos"],explanations:["El control de versiones registra cambios que se pueden examinar a lo largo del tiempo.","Registrar un cambio no valida que sea correcto.","La aprobación legal requiere un proceso aparte.","La revisión sigue siendo necesaria aunque exista un historial registrado."],concept:"Propósito del control de versiones",hints:["¿Qué evidencia permitiría explicar las ediciones anteriores?","Distingue entre registrar el trabajo y aprobarlo."]},
    "ghf-002": {prompt:"¿Qué afirmación distingue correctamente Git de GitHub?",choices:["Git necesita GitHub para almacenar commits","Git lleva el control de versiones; GitHub aloja repositorios y facilita la colaboración","GitHub es el área de preparación local","Git es solo una interfaz gráfica para GitHub"],explanations:["Git puede administrar repositorios sin GitHub.","Git es software de control de versiones; GitHub añade alojamiento y colaboración.","El área de preparación pertenece a un repositorio Git local.","Git tiene sus propias herramientas de línea de comandos y su propio modelo de datos."],concept:"Git frente a GitHub",hints:["¿Qué componente puede funcionar sin conexión?","Separa el seguimiento de versiones de la colaboración en una plataforma de alojamiento."]},
    "ghf-003": {prompt:"Una persona que desarrolla software quiere tener los archivos del proyecto y su historial de Git en una laptop. ¿Qué operación debe usar?",choices:["Marcar el repositorio con una estrella","Descargar un ZIP del código fuente","Clonar el repositorio","Seguir el repositorio con Watch"],explanations:["Marcar un repositorio con una estrella permite guardarlo como favorito sin copiar su historial.","Un ZIP del código fuente no incluye el historial del repositorio Git.","Clonar crea un repositorio local con el historial de Git.","Watch configura notificaciones en lugar de crear una copia local."],concept:"Clonación",hints:["¿El resultado necesita metadatos de versiones?","Compara un archivo comprimido con un repositorio de trabajo."]},
    "ghf-004": {prompt:"Una persona editó varios archivos con seguimiento, pero quiere que el próximo commit incluya solo dos. ¿Qué debe hacer primero?",choices:["Hacer push directamente del árbol de trabajo","Incluir todas las modificaciones con seguimiento en un commit sin seleccionarlas","Hacer fetch del remoto","Preparar los cambios seleccionados"],explanations:["Push transfiere commits existentes; no selecciona las ediciones del árbol de trabajo.","Incluir todas las modificaciones incorporaría los archivos no deseados.","Fetch actualiza la información de seguimiento del remoto, no el índice.","La preparación selecciona el contenido del próximo commit."],concept:"Área de preparación",hints:["¿Cómo se arma la próxima instantánea?","¿Qué acción ocurre antes de registrar un commit?"]},
    "ghf-005": {prompt:"¿Cuál es la mejor manera de entender un commit de Git?",choices:["Una instantánea registrada con metadatos que la identifican","Una copia en vivo de todas las ediciones actuales sin confirmar","Una solicitud para integrar cambios que aún no los ha registrado","Una conexión de red que mantiene sincronizadas dos carpetas"],explanations:["Un commit registra una instantánea y metadatos, como la autoría y el mensaje.","Las ediciones sin confirmar no se incorporan automáticamente al historial registrado.","Un commit registra trabajo; un pull request propone integrar trabajo ya registrado.","Los commits persisten independientemente de una conexión de red."],concept:"Commits",hints:["¿Qué permanece después de cerrar el editor?","Piensa en un punto identificable del historial."]},
    "ghf-006": {prompt:"Una persona de diseño quiere experimentar sin cambiar la rama predeterminada. ¿Qué concepto de Git lo permite?",choices:["Un hito","Una rama separada","Un tema del repositorio","Un filtro de notificaciones"],explanations:["Los hitos agrupan elementos de trabajo; no aíslan cambios en archivos.","Una rama proporciona una línea de trabajo separada.","Los temas ayudan a descubrir repositorios.","Los filtros de notificaciones seleccionan mensajes, no versiones."],concept:"Aislamiento mediante ramas",hints:["¿Dónde puede existir una línea de trabajo alternativa?","Separa el aislamiento del trabajo del seguimiento de tareas."]},
    "ghf-007": {prompt:"Existe un commit local en una rama de funcionalidad, pero el equipo no puede verlo en GitHub. ¿Qué acción suele compartir ese commit?",choices:["Volver a preparar sus archivos","Hacer fetch de la rama remota","Hacer push de la rama al remoto","Crear otra rama local en ese commit"],explanations:["Preparar archivos no transfiere commits existentes.","Fetch recupera el historial remoto en lugar de publicar el local.","Push envía los commits locales a la rama remota.","Otra referencia local no transmite el commit."],concept:"Push",hints:["¿En qué dirección debe viajar el historial?","¿El commit ya está registrado localmente?"]},
    "ghf-008": {prompt:"Quieres recuperar cambios remotos para examinarlos sin integrarlos en tu rama actual. ¿Qué operación corresponde?",choices:["Commit","Push","Merge","Fetch"],explanations:["Commit registra los cambios locales preparados.","Push publica el historial local.","Merge integra historiales en una rama.","Fetch recupera el historial remoto sin fusionarlo con la rama actual."],concept:"Fetch",hints:["Separa la recuperación de la integración.","¿Qué acción deja intacta tu línea de trabajo actual?"]},
    "ghf-009": {prompt:"¿En qué se diferencia git pull de git fetch en un flujo de trabajo habitual con ramas?",choices:["Pull recupera los cambios y luego los integra","Pull solo sube commits locales","Pull crea una cuenta de GitHub","Pull elimina el historial remoto"],explanations:["Pull hace fetch e integra los cambios mediante merge o rebase, según la configuración.","Subir commits locales es la función de push.","Crear una cuenta no tiene relación con Git pull.","Pull no elimina el historial remoto."],concept:"Pull frente a fetch",hints:["¿Qué operación va más allá de recuperar cambios?","Ten en cuenta que el comportamiento de integración es configurable."]},
    "ghf-010": {prompt:"Dos ramas editan el mismo pasaje de maneras distintas y Git no puede combinarlas automáticamente. ¿Qué se necesita?",choices:["Otro fetch sin cambiar ninguno de los pasajes","Resolver un conflicto de fusión","Solo un nuevo mensaje de commit para el conflicto sin cambios","Cambiar el nombre de la rama de origen"],explanations:["Recuperar otra vez los mismos historiales no concilia sus ediciones.","Una persona debe conciliar los cambios en conflicto antes de que pueda terminar la fusión.","Cambiar solo el mensaje deja sin resolver el contenido incompatible.","Cambiar el nombre de una rama no concilia su contenido."],concept:"Conflictos de fusión",hints:["¿Puede el software deducir la redacción deseada?","Concéntrate en las ediciones incompatibles, no en los metadatos de la rama."]},
    "ghf-011": {prompt:"Un equipo quiere deshacer un cambio publicado y conservar un historial compartido auditable. ¿Qué enfoque es más adecuado?",choices:["Restablecer la rama compartida a un commit anterior y hacer force-push","Eliminar la rama local que contiene el cambio","Crear un commit de reversión","Agregar los archivos modificados a .gitignore"],explanations:["Restablecer la rama y hacer force-push reescribe su historial compartido en lugar de registrar una reversión.","Eliminar una rama local no revierte cambios ya integrados en el remoto.","Revert registra un nuevo commit que revierte cambios anteriores.","Las reglas de exclusión no deshacen cambios con seguimiento que ya se incluyeron en commits."],concept:"Reversión de cambios compartidos",hints:["¿Debe permanecer intacto el historial compartido existente?","Considera registrar la reversión como trabajo nuevo."]},
    "ghf-012": {prompt:"¿Qué mensaje describe mejor un commit acotado que corrige un enlace roto en la documentación?",choices:["Cambios","Actualizar cosas","Versión final","Corregir el enlace de la guía de instalación a las instrucciones de configuración"],explanations:["Cambios no aporta una descripción útil de la intención.","Actualizar cosas no identifica el comportamiento afectado.","Versión final no explica qué cambió.","El mensaje identifica tanto el material afectado como la corrección."],concept:"Mensajes de commit descriptivos",hints:["¿Qué ayudaría a quien mantenga el proyecto en el futuro?","Prefiere un cambio concreto a un estado vago."]},
    "ghf-013": {prompt:"¿Por qué mantener un rediseño de interfaz y una corrección ortográfica no relacionados en ramas separadas?",choices:["Se pueden revisar y entregar de forma independiente","Git prohíbe tener varios archivos en una rama","Cada rama debe tener su propia organización","Las ramas separadas eliminan la necesidad de pruebas"],explanations:["Las ramas independientes reducen el acoplamiento entre trabajos no relacionados.","Las ramas pueden contener cambios en muchos archivos.","Las ramas pertenecen a un repositorio, no a organizaciones separadas.","Las pruebas siguen siendo necesarias en ramas separadas."],concept:"Ramas de alcance específico",hints:["¿Qué pasa si uno de los cambios se retrasa?","Considera el alcance de la revisión."]},
    "ghf-014": {prompt:"En GitHub flow, ¿cuándo debe incorporarse a la rama predeterminada el trabajo de una rama de funcionalidad?",choices:["En cuanto se le da nombre a la rama","Cuando se fusiona su pull request tras las comprobaciones y la revisión requeridas","Cuando su autor marca el repositorio con una estrella","Cada vez que alguien del equipo clona el repositorio"],explanations:["Darle nombre a una rama no integra su contenido.","La fusión integra el trabajo, sujeto a los requisitos del repositorio.","Las estrellas no fusionan cambios.","Clonar copia el historial sin modificar la rama de origen."],concept:"Integración en GitHub flow",hints:["¿Qué acción integra el cambio propuesto?","¿Qué medidas de protección pueden bloquear esa acción?"]},
    "ghf-015": {prompt:"Una persona hace push de otro commit a la misma rama de origen de un pull request abierto. ¿Qué ocurre?",choices:["Hay que recrear el pull request para incluirlo","El nuevo commit se fusiona automáticamente con la rama base","El pull request incluye el nuevo commit","El nuevo commit queda excluido hasta que cambie el título"],explanations:["El pull request existente sigue su rama de origen.","Actualizar la propuesta no la integra automáticamente.","Los nuevos commits en la rama de origen actualizan la propuesta existente.","No hace falta cambiar el título para incluir nuevos commits de la rama de origen."],concept:"Iteración sobre un pull request",hints:["¿La propuesta sigue un ZIP congelado?","Piensa en su relación con la rama."]},
    "ghf-016": {prompt:"Después de fusionar una funcionalidad, ¿por qué podría el equipo eliminar su rama de funcionalidad?",choices:["Para borrar la conversación del pull request","Para eliminar automáticamente todas las copias locales de esa rama","Para quitar los cambios fusionados de la rama predeterminada","Para señalar que el trabajo terminó y reducir las ramas obsoletas"],explanations:["La conversación del pull request sigue disponible.","Eliminar una rama remota no elimina automáticamente la rama local de cada persona.","Los cambios fusionados permanecen en la rama de destino.","Eliminar la rama terminada ayuda a evitar que se reutilice por accidente."],concept:"Limpieza de ramas",hints:["¿Qué preservó ya la fusión?","Distingue una referencia de rama del contenido fusionado."]},
    "ghf-017": {prompt:"Un repositorio tiene un remoto local llamado origin. ¿Qué es origin?",choices:["Un alias convencional de la URL de un repositorio remoto","Una rama protegida que Git exige","Un rol de organización de GitHub","Una licencia aplicada automáticamente al código"],explanations:["Origin es un nombre de remoto habitual, no un tipo de servidor obligatorio.","Los nombres de remotos y de ramas son conceptos distintos.","No es un rol de acceso.","Los alias de remotos no determinan las licencias."],concept:"Nombres de remotos",hints:["¿Qué describe git remote?","¿Este nombre es un alias de una ubicación o una versión?"]},
    "ghf-018": {prompt:"¿Qué propiedad hace de Git un sistema de control de versiones distribuido?",choices:["Cada edición requiere conexión a internet","Los repositorios locales pueden contener historial y permitir commits locales","Solo un servidor central puede registrar cambios","Cada archivo debe tener un propietario diferente"],explanations:["Las operaciones locales de Git pueden funcionar sin conexión.","Los repositorios Git admiten historial y commits sin contactar con GitHub.","Git no reserva la creación de commits a un único servidor central.","La propiedad de archivos no tiene relación con el control de versiones distribuido."],concept:"Control de versiones distribuido",hints:["¿Dónde se puede registrar el historial?","¿Se detendría el trabajo local si no se pudiera acceder a GitHub?"]},
    "ghf-019": {prompt:"¿Qué comando informa qué archivos se modificaron y si los cambios están preparados?",choices:["git push","git clone","git status","git remote add"],explanations:["Push transfiere commits.","Clone crea una copia de un repositorio.","Status resume el estado del árbol de trabajo y del área de preparación.","Remote add configura una URL remota."],concept:"Estado del árbol de trabajo",hints:["¿Qué comando observa en lugar de transferir?","Busca información sobre la preparación de cambios."]},
    "ghf-020": {prompt:"Una persona que mantiene el proyecto quiere examinar los cambios línea por línea antes de hacer un commit. ¿Qué comando está diseñado para esa comparación?",choices:["git init","git remote","git branch","git diff"],explanations:["Init crea los metadatos del repositorio.","Remote administra las ubicaciones de repositorios configuradas.","Branch administra o enumera referencias de ramas.","Diff muestra diferencias entre versiones o estados de archivos."],concept:"Inspección de diferencias",hints:["¿Qué salida mostraría las líneas agregadas y eliminadas?","Distingue una comparación de una lista de ramas."]},
    "ghf-021": {prompt:"¿Qué acción inicia el seguimiento de Git en una carpeta local existente que aún no es un repositorio?",choices:["Ejecutar git init en esa carpeta","Ejecutar git fetch antes de crear metadatos del repositorio","Crear un archivo .gitignore sin inicializar Git","Solo cambiar el nombre de la carpeta para que coincida con un repositorio de GitHub"],explanations:["Git init crea los metadatos del repositorio Git local.","Fetch opera en un repositorio existente; no inicializa esta carpeta.","Un archivo de exclusión por sí solo no crea un repositorio.","El nombre de una carpeta no inicializa el control de versiones."],concept:"Inicialización de repositorios",hints:["¿Esta acción debe contactar con GitHub?","¿Qué acción crea los metadatos locales de control de versiones?"]},
    "ghf-022": {prompt:"¿Qué es el árbol de trabajo en un repositorio Git local?",choices:["Solo los cambios seleccionados en el índice","Los archivos extraídos en los que se está trabajando","Solo las referencias de ramas de seguimiento remoto","Todo el grafo de commits sin archivos extraídos"],explanations:["El índice contiene el contenido seleccionado para el próximo commit, no todo el árbol de trabajo.","El árbol de trabajo contiene los archivos extraídos para editarlos.","Las referencias de seguimiento remoto identifican posiciones remotas recuperadas, no archivos editables.","El historial registrado es distinto de los archivos extraídos actuales."],concept:"Árbol de trabajo",hints:["¿Dónde se hacen las ediciones habituales de archivos?","Separa los archivos editables del índice y del historial registrado."]},
    "ghf-023": {prompt:"Un equipo quiere una referencia reconocible al commit usado para una versión publicada. ¿Qué función de Git corresponde?",choices:["Una persona asignada","Una reacción","Una etiqueta de Git (tag)","Una respuesta guardada"],explanations:["Las personas asignadas indican quién es responsable de los elementos de trabajo.","Las reacciones comunican comentarios.","Una etiqueta de Git marca un punto específico del historial del repositorio.","Las respuestas guardadas reutilizan texto de comentarios."],concept:"Etiquetas de Git",hints:["¿Qué identifica una versión histórica?","Separa los marcadores de versiones de los metadatos de colaboración."]},
    "ghf-024": {prompt:"Una persona tiene un identificador de commit y quiere examinar ese cambio exacto más adelante. ¿Por qué es útil el identificador?",choices:["Siempre apunta al estado más reciente de la rama predeterminada","Se refiere a todos los commits de la misma persona","Cambia cada vez que avanza otra rama","Identifica un commit específico"],explanations:["Un identificador de commit específico no se mueve con la rama predeterminada.","Los distintos commits de una misma persona tienen identidades diferentes.","El avance de otra rama no cambia el identificador de un commit existente.","El identificador permite hacer referencia a una revisión registrada específica."],concept:"Identificadores de commits",hints:["¿Es una revisión fija o una rama que se mueve?","Piensa en localizar un punto preciso del historial."]},
    "ghf-025": {prompt:"¿Para qué se usa principalmente la rama predeterminada de un repositorio?",choices:["Como base habitual de nuevos pull requests y de la navegación del repositorio","Como referencia fija a la última versión publicada","Como rama personal de experimentación exclusiva de cada visitante","Como rama que siempre rechaza commits, sin importar la configuración"],explanations:["La rama predeterminada es la vista inicial y la base habitual de los pull requests.","La rama predeterminada puede avanzar independientemente de las versiones publicadas.","La rama predeterminada es una configuración del repositorio, no una rama de experimentación por visitante.","Ser la rama predeterminada no impone por sí mismo una prohibición de commits."],concept:"Rama predeterminada",hints:["¿Qué versión suelen ver primero los visitantes?","Considera el destino inicial de un cambio propuesto."]}
    ,"ghf-026": {prompt:"Una persona que empieza a contribuir confunde clonar con crear un fork. ¿Qué distinción es correcta?",choices:["Clonar concede acceso de escritura al repositorio original; crear un fork solo concede lectura","Crear un fork genera un repositorio relacionado en GitHub; clonar crea una copia local","Crear un fork elimina el historial; clonar conserva solo los archivos más recientes","Clonar crea automáticamente un fork en la cuenta de la persona"],explanations:["Ninguna operación concede acceso de escritura directo al repositorio original.","Un fork es un repositorio alojado separado y relacionado; un clon es local.","Los forks conservan el historial original y los clones habituales incluyen el historial de Git.","Un clon no crea automáticamente un fork alojado."],concept:"Clon frente a fork",hints:["¿Dónde queda cada copia resultante?","¿Importa tener un espacio de nombres alojado separado?"]},
    "ghf-027": {prompt:"Una laptop no tiene conexión. ¿Qué actividad suele poder hacerse aún en un repositorio Git local existente?",choices:["Hacer fetch de nuevos commits de GitHub","Leer issues recién publicados en GitHub","Crear un commit local","Hacer push de una rama a GitHub"],explanations:["Hacer fetch desde GitHub requiere acceso a la red.","No se pueden recuperar nuevos issues alojados sin conexión.","Los commits locales no requieren contactar con GitHub.","Hacer push a GitHub requiere una conexión de red."],concept:"Git sin conexión",hints:["¿Qué operación usa únicamente datos locales?","Separa las operaciones de Git de la comunicación con el servidor."]},
    "ghf-028": {prompt:"¿Cuál es el efecto principal de fusionar una rama con otra?",choices:["Solo descarga cambios sin integrarlos","Cambia la rama extraída sin combinar ningún trabajo","Siempre descarta todos los cambios exclusivos del destino","Integra los cambios de la rama de origen"],explanations:["Recuperar sin integrar describe fetch.","Cambiar de rama selecciona trabajo, no lo fusiona.","Merge combina historiales y no descarta por naturaleza todo el trabajo exclusivo del destino.","Merge combina las líneas de desarrollo pertinentes."],concept:"Fusión",hints:["¿Qué parte del proyecto se combina?","Separa la recuperación y la extracción de la integración."]},
    "ghf-029": {prompt:"¿Qué tipo de cuenta de GitHub está diseñado para representar la identidad de una sola persona?",choices:["Una cuenta personal","Una cuenta de organización usada como inicio de sesión compartido","Una rama de repositorio","Una política empresarial"],explanations:["Una cuenta personal representa a una persona usuaria.","Las organizaciones se administran mediante las identidades personales de sus miembros, no mediante un inicio de sesión compartido de la organización.","Una rama es una referencia de control de versiones.","Las políticas son configuraciones, no identidades individuales."],concept:"Cuentas personales",hints:["¿Cómo se atribuye la actividad individual?","Separa a una persona de un contenedor de propiedad compartida."]},
    "ghf-030": {prompt:"Una empresa quiere compartir la propiedad de repositorios y usar equipos y permisos de miembros. ¿Qué estructura es adecuada?",choices:["Un gist de un solo empleado","Una organización de GitHub","Una etiqueta de commit","Una lista de tareas de Markdown"],explanations:["Un gist personal no es una estructura organizativa de propiedad y equipos.","Las organizaciones permiten compartir la propiedad y administrar la colaboración.","Una etiqueta identifica una versión.","Una lista de tareas no puede administrar el acceso a repositorios."],concept:"Organizaciones",hints:["¿Quién debe ser propietario de los repositorios más allá de una sola persona empleada?","¿Qué estructura permite usar equipos?"]},
    "ghf-031": {prompt:"¿Qué ayuda a administrar una cuenta empresarial en varias organizaciones de GitHub?",choices:["Un único historial de Git combinado para todos los repositorios","Un inicio de sesión compartido por todos los empleados","Políticas compartidas y administración centralizada","La fusión automática de las ramas predeterminadas de todas las organizaciones"],explanations:["Los repositorios conservan sus propios historiales en lugar de convertirse en un solo repositorio Git.","Una cuenta empresarial no reemplaza las identidades individuales a las que se atribuye la actividad.","Las cuentas empresariales proporcionan una capa administrativa para varias organizaciones.","Agrupar organizaciones en una empresa no combina automáticamente las ramas de sus repositorios."],concept:"Cuentas empresariales",hints:["¿Qué nivel se sitúa por encima de las organizaciones individuales?","Piensa en la gobernanza entre organizaciones."]},
    "ghf-032": {prompt:"¿Qué modelo de implementación usa GitHub Enterprise Server?",choices:["Solo una cuenta personal de GitHub.com con una cuota mayor","Solo una organización operada por GitHub en GitHub.com","Un cliente Git local sin servidor de colaboración","Una instancia de GitHub operada en infraestructura que tú controlas"],explanations:["Enterprise Server es una implementación separada, no una cuota personal mayor.","Eso describe una organización alojada, no el modelo de implementación de Server.","Enterprise Server ofrece un servicio de colaboración, no solo un cliente local.","Enterprise Server se autohospeda en infraestructura controlada por el cliente."],concept:"Cloud frente a Server",hints:["¿Quién opera la infraestructura de alojamiento?","Separa el modelo de implementación de la identidad de la cuenta."]},
    "ghf-033": {prompt:"Una persona que contribuye prefiere operaciones locales de Git visuales en lugar de escribir comandos. ¿Qué herramienta de GitHub es la más adecuada?",choices:["GitHub Desktop","GitHub Pages","GitHub Sponsors","GitHub Discussions"],explanations:["Desktop ofrece una interfaz gráfica para flujos de trabajo con repositorios locales.","Pages publica sitios web.","Sponsors facilita el apoyo económico.","Discussions aloja conversaciones."],concept:"GitHub Desktop",hints:["¿La herramienta administra archivos en la computadora?","Busca un flujo de trabajo gráfico de Git."]},
    "ghf-034": {prompt:"Durante un traslado, una persona que mantiene el proyecto quiere una aplicación diseñada para clasificar notificaciones de GitHub y responder issues desde el teléfono. ¿Qué herramienta corresponde?",choices:["GitHub Desktop","GitHub Mobile","GitHub CLI","El editor de código fuente github.dev"],explanations:["Desktop está diseñado para flujos de trabajo gráficos con repositorios en una computadora.","Mobile permite colaborar en GitHub desde un teléfono.","CLI está orientado a flujos de trabajo en terminal, no a una aplicación de colaboración para teléfonos.","Github.dev es un editor de código fuente, no la aplicación móvil de notificaciones buscada."],concept:"GitHub Mobile",hints:["¿Qué dispositivo y actividades intervienen?","¿Qué interfaz está diseñada para ese formato de dispositivo?"]},
    "ghf-035": {prompt:"Un script de shell necesita crear issues de GitHub mediante un cliente de línea de comandos compatible. ¿Qué herramienta es adecuada?",choices:["GitHub Pages","Solo GitHub Desktop","GitHub CLI","Un renderizador de Markdown"],explanations:["Pages sirve contenido de sitios web estáticos.","Desktop es gráfico, no un cliente de GitHub orientado al shell.","GitHub CLI ofrece flujos de trabajo de GitHub mediante comandos como gh issue.","Renderizar Markdown no crea issues alojados."],concept:"GitHub CLI",hints:["¿El flujo de trabajo requiere comandos en un shell?","¿Es una acción del servicio de GitHub o solo control de versiones local?"]},
    "ghf-036": {prompt:"¿Qué tarea es una función de colaboración de GitHub y no una responsabilidad de un comando básico de Git?",choices:["Registrar un commit local","Crear una rama","Comparar versiones de archivos","Solicitar una revisión en un pull request alojado"],explanations:["Git registra commits directamente.","Git administra ramas directamente.","Git puede comparar versiones directamente.","Las solicitudes de revisión alojadas forman parte de la capa de colaboración de GitHub."],concept:"Capa de colaboración de GitHub",hints:["¿Qué actividad involucra a participantes de una revisión alojada?","Separa la mecánica del repositorio del flujo de trabajo de la plataforma."]},
    "ghf-037": {prompt:"Un issue necesita un encabezado Markdown de primer nivel. ¿Qué texto usa la sintaxis adecuada?",choices:["# Deployment notes","[Deployment notes]","@Deployment notes","`Deployment notes`"],explanations:["Un signo de numeral inicial seguido de un espacio crea un encabezado.","Los corchetes por sí solos no crean un encabezado.","El signo arroba se usa para menciones en contextos adecuados.","Las comillas invertidas dan formato de código en línea."],concept:"Encabezados de Markdown",hints:["¿Qué sintaxis indica la jerarquía del documento?","Distingue un encabezado de un énfasis dentro de una línea."]},
    "ghf-038": {prompt:"¿Qué fragmento Markdown muestra setup como código en línea dentro de una oración?",choices:["**setup**","`setup`","[setup](https://example.com)","## setup"],explanations:["Los asteriscos dobles producen texto en negrita.","Las comillas invertidas marcan código en línea.","Esta sintaxis crea un hipervínculo.","Los signos de numeral crean un encabezado."],concept:"Formato de código en línea",hints:["¿Qué formato corresponde a identificadores y comandos?","El texto debe permanecer dentro de la oración."]},
    "ghf-039": {prompt:"¿Qué Markdown crea un enlace con la etiqueta visible Guide?",choices:["(Guide)[https://docs.github.com]","<Guide>https://docs.github.com","[Guide](https://docs.github.com)","# Guide https://docs.github.com"],explanations:["Los delimitadores de la etiqueta y la URL están invertidos.","Esto no usa la sintaxis de enlaces con etiqueta.","Los corchetes contienen la etiqueta y los paréntesis, el destino.","Esto crea un encabezado, no el enlace con etiqueta solicitado."],concept:"Enlaces de Markdown",hints:["¿Dónde van la etiqueta y el destino?","Busca delimitadores emparejados alrededor de cada parte."]},
    "ghf-040": {prompt:"Un informe de error incluye una traza de pila de varias líneas. ¿Qué formato conserva mejor su disposición de código?",choices:["Un párrafo común","Un párrafo en negrita","Un único segmento de código en línea para toda la traza","Un bloque de código delimitado"],explanations:["El renderizado de párrafos comunes no conserva la disposición del código como bloque.","La negrita no proporciona formato de código de varias líneas.","El código en línea está pensado para texto breve dentro de una línea, no para una traza de varias líneas.","Un bloque de código delimitado conserva la presentación de código de varias líneas."],concept:"Bloques de código",hints:["¿Qué conserva los saltos de línea y la sangría?","Elige formato de bloque en lugar de formato en línea."]},
    "ghf-041": {prompt:"Una lista de verificación de una versión necesita una tarea sin marcar en Markdown. ¿Qué sintaxis es adecuada?",choices:["- [ ] Verify migration","[Verify migration](pending)","@Verify migration","# [Verify migration]"],explanations:["Un marcador de lista seguido de una casilla vacía crea una tarea sin marcar.","Es sintaxis de enlace, no una casilla.","La arroba no crea una tarea.","Un encabezado no crea una casilla de tarea interactiva."],concept:"Listas de tareas de Markdown",hints:["¿Qué combina un elemento de lista con una casilla?","¿La casilla debe contener ya una marca de finalización?"]},
    "ghf-042": {prompt:"Un comentario debe notificar a una persona del equipo llamada river sobre una pregunta. ¿Qué texto usa la sintaxis de menciones de GitHub?",choices:["#river","@river","!river","`river`"],explanations:["El numeral no es el prefijo de las menciones de usuarios.","La arroba seguida de un nombre de usuario crea una mención.","El signo de exclamación no es sintaxis de mención de usuarios.","El formato de código en línea no menciona a un usuario."],concept:"Menciones",hints:["¿Qué prefijo identifica a una persona en una conversación?","Dar formato a un nombre no es lo mismo que dirigirse a alguien."]},
    "ghf-043": {prompt:"En un issue de un repositorio, una persona escribe #84 para hacer referencia a otro issue del mismo repositorio. ¿Qué proporciona normalmente GitHub?",choices:["El cierre automático del issue 84 solo por la referencia","Un duplicado del issue 84","Una referencia enlazada a ese issue","Una referencia al commit 84 en lugar del issue"],explanations:["Una referencia por sí sola no es un flujo de cierre de issues mediante palabras clave.","Hacer referencia a un issue no lo duplica.","GitHub convierte automáticamente las referencias por número de issue en enlaces en contextos de conversación compatibles.","En este contexto, el formato numeral-número identifica un issue o pull request."],concept:"Referencias a issues",hints:["¿Esto permite navegar o modifica algo?","¿Qué contexto proporciona el nombre del repositorio?"]},
    "ghf-044": {prompt:"Una persona que revisa quiere citar una oración anterior antes de responder. ¿Qué prefijo Markdown crea una cita en bloque?",choices:["@","!","- [ ]",">"],explanations:["La arroba se usa para menciones.","El signo de exclamación participa en la sintaxis de imágenes, no de citas en bloque.","Esto crea una tarea sin marcar.","Un prefijo de mayor que crea texto citado."],concept:"Citas en bloque",hints:["¿Cómo se puede separar visualmente el material citado?","Elige sintaxis para citar, no para seguir tareas."]},
    "ghf-045": {prompt:"Un README en la raíz necesita un enlace a docs/setup.md que siga la rama que se está explorando. ¿Cuál es la mejor opción?",choices:["Un enlace relativo a docs/setup.md","Un enlace absoluto fijado al setup.md de un commit","Un enlace absoluto que siempre apunte al setup.md de main","Un enlace a la página principal del repositorio en lugar del archivo"],explanations:["GitHub resuelve este enlace relativo usando la rama que se está explorando.","Un enlace fijado a un commit permanece intencionalmente en una revisión fija.","Un enlace fijado a main no sigue otras ramas que se estén explorando.","La página principal no apunta directamente al documento de configuración."],concept:"Enlaces relativos de documentación",hints:["¿El destino debe seguir la rama actual?","Considera cómo la ubicación del repositorio proporciona contexto."]},
    "ghf-046": {prompt:"¿Qué fragmento Markdown muestra la palabra urgent en negrita?",choices:["`urgent`","**urgent**","> urgent","[urgent]"],explanations:["Las comillas invertidas muestran código en línea.","Los asteriscos dobles aplican negrita.","Un prefijo de mayor que crea una cita en bloque.","Los corchetes por sí solos no aplican negrita."],concept:"Énfasis de texto",hints:["¿Qué delimitador rodea el texto enfatizado?","Descarta el formato de código y de cita."]},
    "ghf-047": {prompt:"Una persona que escribe quiere una lista con viñetas de requisitos previos sin implicar un orden de ejecución. ¿Qué estructura Markdown corresponde?",choices:["Una lista numerada","Un bloque de código delimitado","Una lista sin ordenar","Un encabezado para cada palabra"],explanations:["Las listas numeradas comunican un orden.","Los bloques de código presentan contenido literal con formato de código.","Las listas sin ordenar presentan elementos sin una secuencia numerada.","Los encabezados establecen secciones, no una lista compacta."],concept:"Listas sin ordenar",hints:["¿La secuencia tiene importancia aquí?","Elige una estructura de lista, no formato de código."]},
    "ghf-048": {prompt:"Una persona que contribuye a la documentación agrega texto alternativo a una imagen Markdown. ¿Cuál es su propósito principal?",choices:["Especificar la ruta de almacenamiento del archivo de imagen","Proporcionar solo un título al pasar el cursor","Definir las dimensiones de visualización de la imagen","Proporcionar una descripción textual para la accesibilidad"],explanations:["La URL o ruta de la imagen es otra parte de la sintaxis de imágenes de Markdown.","El texto alternativo no es simplemente un campo de título al pasar el cursor.","El texto alternativo describe el contenido; no especifica el ancho y la altura.","El texto alternativo ayuda a transmitir el significado de la imagen cuando no se puede percibir el contenido visual."],concept:"Descripciones accesibles de imágenes",hints:["¿Quién podría no poder ver la imagen?","Separa el contenido descriptivo de la ubicación de la imagen."]},
    "ghf-049": {prompt:"Un equipo elige GitHub flow para un manual sin código. ¿Es un uso adecuado?",choices:["Sí; la revisión basada en ramas también se puede aplicar a la documentación","No; solo los programas compilados pueden usar ramas","No; Markdown no se puede incluir en commits","Solo si cada documento se convierte en un issue"],explanations:["GitHub flow permite cambios colaborativos más allá del código de aplicaciones.","Las ramas no se limitan a lenguajes compilados.","Los archivos Markdown pueden tener control de versiones normalmente.","Los documentos pueden seguir siendo archivos mientras los issues siguen el trabajo relacionado."],concept:"GitHub flow más allá del código",hints:["¿El control de versiones depende de la compilación?","¿Qué tipos de archivos se benefician de una revisión?"]},
    "ghf-050": {prompt:"Antes de abrir un pull request para una rama, ¿qué debe incluir su autor para ayudar a entender la propuesta a quienes revisan?",choices:["Solo el nombre de la rama, sin más contexto","Un resumen de los cambios y del problema que resuelven","Solo la palabra actualizado como descripción completa","Solo una afirmación de que no hace falta revisión"],explanations:["El nombre de una rama por sí solo puede no explicar el motivo ni el alcance.","Un resumen conciso y su justificación aportan contexto para la revisión.","Una palabra de estado genérica no describe el trabajo.","Afirmar que la revisión no hace falta no aporta evidencia para revisarla."],concept:"Comunicación de cambios",hints:["¿Qué necesitaría quien revisa antes de leer las diferencias?","Explica tanto la intención como el contenido."]}
    ,"ghf-051": {prompt:"¿Por qué suele ser más fácil mantener un commit con un cambio coherente que uno que mezcla cambios no relacionados?",choices:["Nunca necesita revisión","No puede introducir errores","Se puede entender y revertir de forma más selectiva","Hace innecesaria la protección de ramas"],explanations:["Los commits de alcance específico también necesitan revisión.","La coherencia no garantiza que sean correctos.","Un cambio aislado es más fácil de examinar o revertir sin afectar trabajo no relacionado.","Las protecciones de ramas tienen un propósito de gobernanza aparte."],concept:"Cambios atómicos",hints:["¿Qué ocurre si hay que deshacer solo una parte?","Piensa en diagnósticos futuros."]},
    "ghf-052": {prompt:"Para una tarea activa se prefiere una rama llamada fix-search-timeout a una llamada work. ¿Por qué?",choices:["Su nombre obliga a superar las pruebas","Su nombre concede acceso al repositorio","Su nombre cierra todos los issues relacionados","Su nombre comunica el propósito del trabajo en curso"],explanations:["Los nombres de ramas no hacen cumplir pruebas.","El acceso proviene de permisos, no de nombres.","Cerrar issues requiere vínculos y eventos pertinentes aparte.","Un nombre de rama descriptivo ayuda al equipo a reconocer el trabajo."],concept:"Nombres de ramas",hints:["¿Qué puede deducir alguien del equipo de la lista de ramas?","Los nombres comunican, pero no imponen comportamientos."]},
    "ghf-053": {prompt:"Una persona ejecuta git add sobre un archivo. ¿Qué ha ocurrido en ese momento?",choices:["El contenido seleccionado del archivo está preparado para un commit futuro","El archivo necesariamente se subió a GitHub","Necesariamente se registró un nuevo commit","Todas las ediciones posteriores de ese archivo entrarán automáticamente en el próximo commit"],explanations:["Git add coloca contenido en el índice para el próximo commit.","La preparación por sí sola no contacta con GitHub.","Registrar la instantánea aún requiere una operación de commit.","Las ediciones posteriores a la preparación deben prepararse de nuevo para actualizar el contenido seleccionado."],concept:"Preparación frente a publicación",hints:["¿Qué estado local cambió?","¿Ya se registró o transmitió el historial?"]},
    "ghf-054": {prompt:"Un equipo entiende un pull request como una solicitud para descargar archivos. ¿Cuál es una mejor descripción?",choices:["Una copia de respaldo sin conversación","Una propuesta para fusionar cambios entre ramas","Un reemplazo de un commit de Git","Una solicitud de permisos de cuenta"],explanations:["Los pull requests incluyen revisión y conversación, no solo contenido de respaldo.","Un pull request propone cambios entre ramas para revisión e integración.","Los commits siguen siendo los cambios registrados subyacentes.","El acceso al repositorio se administra aparte."],concept:"Fundamentos de pull requests",hints:["¿Qué se propone a la rama receptora?","Considera la revisión antes de la integración."]},
    "ghf-055": {prompt:"Una persona cambia la URL asociada a un remoto local. ¿Qué cambia principalmente?",choices:["El contenido de todos los commits anteriores","La rama extraída actualmente","El destino al que se conectan las operaciones remotas posteriores","Los cambios de archivos que están preparados"],explanations:["La configuración del remoto no reescribe el contenido de los commits.","Cambiar la URL no cambia la rama activa.","La URL remota configurada determina el destino remoto.","El índice es independiente de la configuración de conexión remota."],concept:"URL de remotos",hints:["¿Se está editando el historial o configurando una conexión?","¿Qué destino usará un fetch posterior?"]},
    "ghf-056": {prompt:"Dos personas usan interfaces compatibles distintas: una usa GitHub Desktop y otra comandos de Git. ¿Pueden colaborar en el mismo repositorio de GitHub?",choices:["No; cada interfaz requiere un formato de historial diferente","No; los repositorios de Desktop no pueden tener ramas","Solo si el repositorio no contiene código fuente","Sí; ambas interfaces trabajan con repositorios Git"],explanations:["Estas interfaces usan un historial de repositorio Git compatible.","Desktop admite flujos de trabajo con ramas.","El tipo de contenido del repositorio no impone esa limitación.","Quienes colaboran pueden usar diferentes interfaces compatibles con Git."],concept:"Interoperabilidad de herramientas",hints:["¿La interfaz cambia el sistema de control de versiones subyacente?","Separa la elección personal de herramienta del historial compartido del repositorio."]},
    "ghf-057": {prompt:"¿Qué afirmación sobre la pertenencia a organizaciones de GitHub es correcta?",choices:["Las personas acceden a las organizaciones mediante sus propias cuentas","Todos los miembros deben usar una contraseña compartida de la organización","Unirse a una organización elimina los repositorios personales","La pertenencia a una organización crea una rama Git local"],explanations:["Las cuentas individuales reciben membresía y roles.","Compartir credenciales perjudica la identidad individual y no es así como funcionan las organizaciones.","La membresía no elimina repositorios personales.","La membresía es administración de cuentas, no creación de ramas."],concept:"Identidad individual en organizaciones",hints:["¿Cómo debe mantenerse la atribución de acciones?","Separa la membresía del uso de credenciales compartidas."]},
    "ghf-058": {prompt:"¿Por qué podría una empresa elegir GitHub Enterprise Cloud en lugar de GitHub Enterprise Server?",choices:["Cloud elimina la necesidad de administrar permisos de repositorios","GitHub opera el servicio alojado en lugar de que la empresa opere una instancia de servidor","Cloud evita todos los conflictos de fusión","Cloud convierte todos los repositorios en código abierto"],explanations:["Los permisos siguen siendo importantes en ambos modelos.","Cloud transfiere el alojamiento del servicio a GitHub en lugar de usar infraestructura de Server operada por el cliente.","Los conflictos surgen de los cambios, no del modelo de implementación.","Los repositorios de Cloud pueden tener visibilidad restringida."],concept:"Responsabilidad de implementación empresarial",hints:["¿Quién mantiene la infraestructura del servicio?","No confundas el alojamiento con garantías del flujo de trabajo."]},
    "ghf-059": {prompt:"Una persona quiere pasar de la rama actual a otra rama local existente. ¿Qué comando expresa esa acción?",choices:["git fetch","git add","git switch target-branch","git push"],explanations:["Fetch recupera información remota.","Add prepara contenido.","Switch cambia la rama extraída al destino indicado.","Push transfiere commits a un remoto."],concept:"Cambio de ramas",hints:["¿El objetivo es transferir historial o cambiar la rama extraída?","¿Qué acción selecciona otra línea de trabajo?"]},
    "ghf-060": {prompt:"Una persona quiere que quienes revisan distingan las líneas eliminadas de las agregadas en una edición propuesta. ¿Qué deben examinar?",choices:["Solo la lista de mensajes de commit","Solo el archivo actual sin formato","Solo la vista de atribución por línea del archivo","Las diferencias del cambio"],explanations:["Los mensajes describen la intención, pero no necesariamente muestran las ediciones por línea.","El contenido sin formato no tiene la comparación del antes y el después.","La atribución por línea identifica cambios anteriores, pero no es la comparación de la edición propuesta.","Un diff presenta diferencias, como adiciones y eliminaciones."],concept:"Lectura de diferencias",hints:["¿Qué vista compara el antes y el después?","Concéntrate en el contenido modificado."]},
    "ghf-061": {prompt:"Un documento Markdown incluye el nombre de un lenguaje compatible después del delimitador inicial de un bloque de código. ¿Qué beneficio ofrece?",choices:["Permite resaltar la sintaxis según el lenguaje","Ejecuta el código en GitHub","Valida que el código funcione correctamente","Instala ese lenguaje en el entorno de quien lee"],explanations:["Un identificador de lenguaje compatible ayuda al renderizador a resaltar el código.","Los bloques delimitados muestran texto; no lo ejecutan.","El resaltado es presentación, no validación funcional.","El resaltado de sintaxis no instala entornos de ejecución."],concept:"Resaltado de sintaxis",hints:["¿El delimitador sirve para presentar o ejecutar?","¿Qué podría hacer un renderizador con la información del lenguaje?"]},
    "ghf-062": {prompt:"Una lista Markdown muestra - [x] Run tests. ¿Qué significa la x en la lista de tareas renderizada?",choices:["El elemento sigue sin marcar","La tarea está marcada como completada","El texto está tachado en lugar de ser una tarea","La tarea tiene una comprobación de estado automatizada fallida"],explanations:["Una tarea sin marcar usa un espacio entre corchetes.","Una x en la casilla marca la tarea como completada.","El tachado usa otros delimitadores Markdown.","Una casilla no es un resultado automatizado de pruebas."],concept:"Tareas Markdown completadas",hints:["¿En qué se diferencia de una casilla vacía?","Separa el estado manual de tareas de las comprobaciones automatizadas."]},
    "ghf-063": {prompt:"Un repositorio contiene código de programa, notas de diseño y archivos de configuración. ¿A cuáles puede Git aplicar control de versiones?",choices:["Solo al código de programa","Solo a archivos ya publicados en GitHub","A todos estos tipos de archivos","Solo a documentos Markdown"],explanations:["Git no se limita al código de programa.","Los archivos locales pueden tener control de versiones antes de publicarse.","Git puede seguir muchos tipos de archivos en un repositorio.","Markdown es compatible, pero no exclusivo."],concept:"Contenido de repositorios",hints:["¿Git está ligado a un solo formato de documento?","Piensa en todo el proyecto, no solo en el código ejecutable."]},
    "ghf-064": {prompt:"¿Qué afirmación explica mejor por qué commit local y push son acciones separadas?",choices:["Commit solo selecciona archivos; push registra la primera instantánea local","Commit descarga el historial remoto; push lo integra localmente","Commit siempre necesita red; push a GitHub nunca la necesita","Commit registra el historial local; push lo comparte con un remoto"],explanations:["La preparación selecciona contenido; commit registra una instantánea antes de push.","Fetch recupera el historial y pull integra el trabajo recuperado.","Los commits locales pueden hacerse sin conexión; push a GitHub necesita conectividad.","Registrar y transmitir el historial son operaciones distintas."],concept:"Historial local y remoto",hints:["¿Dónde se registra primero el cambio?","¿Cuándo pueden verlo quienes colaboran en el remoto?"]},
    "ghf-065": {prompt:"Una persona que visita el proyecto por primera vez necesita conocer su propósito y las instrucciones básicas de configuración. ¿Qué archivo suele presentarlos?",choices:["README.md","CODEOWNERS","LICENSE","Un archivo de bloqueo de paquetes"],explanations:["Un README presenta el proyecto y cómo empezar.","CODEOWNERS asigna rutas a responsables de revisión.","LICENSE establece permisos y condiciones legales.","Un archivo de bloqueo registra la resolución de dependencias, no presenta el proyecto."],concept:"Propósito de README",hints:["¿Qué debería leer primero quien visita el proyecto?","Separa la orientación de los metadatos legales y de dependencias."]},
    "ghf-066": {prompt:"Una persona que mantiene el proyecto quiere indicar los términos legales de reutilización del código. ¿Qué archivo es el más adecuado?",choices:["CONTRIBUTING.md","LICENSE","CODEOWNERS","Una plantilla de pull request"],explanations:["Las pautas de contribución describen cómo participar.","Una licencia especifica permisos y condiciones de reutilización.","CODEOWNERS asigna responsabilidades según las rutas.","Una plantilla de pull request estructura las descripciones de cambios propuestos."],concept:"Licencias de repositorios",hints:["¿Es un permiso legal o una instrucción de flujo de trabajo?","¿Qué documento regula la reutilización?"]},
    "ghf-067": {prompt:"Una persona que contribuye necesita conocer los comandos de prueba obligatorios y el proceso para enviar parches. ¿Qué archivo es el mejor lugar dedicado a esa guía?",choices:["LICENSE","SECURITY.md","CONTRIBUTING.md","CODEOWNERS"],explanations:["Una licencia define las condiciones de reutilización.","Una política de seguridad explica cómo reportar vulnerabilidades y qué versiones tienen soporte.","Las pautas de contribución explican el flujo de participación del proyecto.","CODEOWNERS identifica responsables de revisión, no pasos de envío."],concept:"Pautas de contribución",hints:["¿Quién es el público destinatario?","Distingue la participación habitual del reporte de vulnerabilidades."]},
    "ghf-068": {prompt:"Un proyecto quiere que quienes investigan sepan dónde reportar vulnerabilidades de forma privada. ¿Qué archivo dedicado debe contener esa política?",choices:["Una plantilla de pull request","CODE_OF_CONDUCT.md","CODEOWNERS","SECURITY.md"],explanations:["Una plantilla de pull request estructura cambios propuestos; no define la política dedicada de divulgación.","Un código de conducta trata del comportamiento de la comunidad y los reportes de conducta.","CODEOWNERS define la responsabilidad de revisión, no pautas de divulgación.","SECURITY.md documenta instrucciones de reporte de seguridad e información de soporte."],concept:"Archivo de política de seguridad",hints:["¿Se trata de una contribución habitual o de una divulgación sensible?","Busca una política dedicada al manejo de vulnerabilidades."]},
    "ghf-069": {prompt:"Un equipo quiere que los pull requests listos para revisión que modifican /payments/ soliciten revisión a quienes mantienen pagos. ¿Qué mecanismo corresponde?",choices:["Una regla de rutas de CODEOWNERS","Una estrella de repositorio","Una descripción del repositorio","Un recurso de una versión publicada"],explanations:["CODEOWNERS asigna las rutas coincidentes a usuarios o equipos para solicitar revisiones.","Marcar con una estrella no asigna revisores.","Las descripciones resumen el repositorio.","Los recursos de versiones distribuyen archivos; no dirigen revisiones."],concept:"Propiedad del código",hints:["¿Qué asigna rutas de archivos a personas responsables?","Separa la asignación por propiedad del descubrimiento de repositorios."]},
    "ghf-070": {prompt:"¿Agregar solo un archivo CODEOWNERS exige la aprobación de un propietario antes de fusionar?",choices:["Sí, todo cambio coincidente queda bloqueado sin ella","No; un requisito adecuado de protección de ramas o conjunto de reglas también debe exigir la aprobación","Sí, pero solo para archivos Markdown","No, porque los propietarios de código nunca pueden revisar pull requests"],explanations:["Las solicitudes automáticas de revisión no son por sí solas una condición obligatoria de fusión.","La propiedad y la aprobación obligatoria de propietarios son configuraciones separadas.","El tipo de archivo no crea un requisito automático de aprobación.","Los propietarios pueden revisar; falta exigir esa aprobación."],concept:"Propiedad frente a aplicación obligatoria",hints:["¿Solicitar una revisión equivale a exigir aprobación?","¿Qué configuraciones controlan si se bloquea la fusión?"]},
    "ghf-071": {prompt:"Un pull request apunta a main, pero modifica CODEOWNERS en su rama de funcionalidad. ¿Qué versión determina las solicitudes automáticas de revisión a propietarios de código?",choices:["El CODEOWNERS más reciente de cualquier fork","El CODEOWNERS local sin confirmar de su autor","El CODEOWNERS de main, la rama base","Todos los archivos CODEOWNERS de la organización combinados"],explanations:["Otros forks no proporcionan las reglas de propiedad de la rama receptora.","Los archivos locales sin confirmar no configuran la asignación de revisiones alojadas.","Los pull requests usan la propiedad de código de su rama base.","GitHub no combina todos los archivos de propiedad de la organización."],concept:"Rama base de propiedad del código",hints:["¿Qué rama recibirá el cambio?","¿Debería una propuesta definir su propia autoridad de revisión existente?"]},
    "ghf-072": {prompt:"Un repositorio tiene archivos CODEOWNERS en .github/, en la raíz y en docs/. ¿Qué ubicación tiene prioridad?",choices:["docs/","La raíz","Se combinan los tres",".github/"],explanations:["Docs se busca después de las otras ubicaciones compatibles.","La raíz se busca después de .github/.","GitHub usa la primera ubicación encontrada; no combina los archivos.","GitHub busca en .github/ antes que en la raíz y en docs/."],concept:"Prioridad de ubicaciones de CODEOWNERS",hints:["¿GitHub combina todos los archivos de propiedad?","Piensa en el orden de búsqueda documentado."]},
    "ghf-073": {prompt:"Una empresa quiere que los servicios independientes nuevos empiecen con carpetas y archivos iniciales estándar, sin heredar el historial de commits del repositorio inicial. ¿Qué debe usar?",choices:["Una plantilla de repositorio","Un fork de cada servicio","Una suscripción Watch al repositorio","Una revisión de pull request"],explanations:["Una plantilla incorpora archivos a un proyecto nuevo con su propio historial inicial.","Un fork conserva un historial relacionado y una relación con el repositorio original.","Watch configura notificaciones.","La revisión evalúa cambios propuestos; no genera un repositorio nuevo."],concept:"Plantillas de repositorio",hints:["¿Se busca un proyecto nuevo o contribuir al repositorio original?","¿Deben transferirse los commits históricos del repositorio inicial?"]},
    "ghf-074": {prompt:"Después de generar un repositorio desde una plantilla, ¿qué ocurre cuando el autor de la plantilla edita un archivo inicial?",choices:["El repositorio generado recibe la edición automáticamente","El repositorio generado no se sincroniza automáticamente","GitHub abre automáticamente un pull request de actualización en cada repositorio generado","La edición aparece en el repositorio generado la próxima vez que alguien lo clona"],explanations:["Las plantillas no proporcionan sincronización automática continua.","El nuevo proyecto es independiente; los cambios posteriores deben adoptarse por separado.","Editar la plantilla por sí solo no crea pull requests de actualización en los proyectos generados.","Clonar recupera el historial propio del proyecto generado, no cambios posteriores de la plantilla."],concept:"Independencia de plantillas",hints:["¿Se creó una relación de sincronización activa?","Separa la generación inicial del mantenimiento posterior."]},
    "ghf-075": {prompt:"Una plantilla incluye varias ramas y el repositorio generado las incluye todas. ¿Por qué no se debe asumir que se pueden usar pull requests y fusiones normales de GitHub entre esas ramas generadas?",choices:["Todas las ramas generadas son alias de la misma referencia","Todas las ramas generadas son permanentemente de solo lectura","Sus historiales generados no están relacionados","Cada rama mantiene una conexión activa con los commits originales de la plantilla"],explanations:["Las ramas generadas son distintas; no son alias.","Generar desde una plantilla no hace que las ramas sean intrínsecamente de solo lectura.","Las ramas generadas desde una plantilla tienen historiales no relacionados, a diferencia de las ramas habituales con historial compartido.","Los proyectos generados no conservan una conexión de sincronización activa con la plantilla."],concept:"Historiales de ramas de plantillas",hints:["¿Estas ramas comparten una ascendencia habitual?","Consulta la diferencia entre generar desde una plantilla y crear un fork."]}
    ,"ghf-076": {prompt:"Una persona que mantiene el proyecto quiere cambiar un archivo desde la interfaz web de GitHub conservando la revisión antes de integrar. ¿Qué flujo corresponde?",choices:["Editar la descripción del repositorio","Subirlo solo como adjunto de un issue","Cambiar la visibilidad del repositorio","Registrar la edición en una rama nueva y abrir un pull request"],explanations:["La descripción no modifica el archivo con control de versiones.","Un adjunto de issue no es una edición versionada del repositorio.","La visibilidad no edita el contenido de archivos.","Una rama y un pull request conservan el flujo de revisión para ediciones web."],concept:"Edición web de archivos",hints:["¿Dónde debe estar el cambio versionado?","¿Cómo puede revisarse antes de cambiar la rama predeterminada?"]},
    "ghf-077": {prompt:"¿Qué debe esperar alguien cuando se elimina un archivo con seguimiento en un nuevo commit?",choices:["Desaparece de esa revisión, pero puede permanecer en el historial anterior","Se borran automáticamente todas las copias históricas","El mismo archivo se elimina automáticamente de todas las demás ramas","Todos los clones existentes eliminan inmediatamente su copia de trabajo sin hacer fetch"],explanations:["El historial de Git puede conservar versiones anteriores a la eliminación.","Una eliminación habitual no purga el contenido histórico.","Un commit cambia su línea de historial, no todas las ramas a la vez.","Los repositorios locales ajenos no actualizan archivos de trabajo sin recibir y aplicar los cambios."],concept:"Eliminación de archivos e historial",hints:["¿Una nueva instantánea reescribe todas las anteriores?","Separa el contenido actual del historial conservado."]},
    "ghf-078": {prompt:"Se agrega build/ a .gitignore después de que build/output.log ya se incluyó en un commit. ¿Qué se debe esperar?",choices:["El archivo de registro con seguimiento se borra de todo el historial","La regla de exclusión por sí sola no deja de seguir el archivo ya seguido","El registro se elimina automáticamente del índice","El registro se elimina automáticamente del disco local"],explanations:["Las reglas de exclusión no reescriben el historial.",".gitignore se aplica a archivos que se dejan intencionalmente sin seguimiento; los ya seguidos necesitan un paso aparte para dejar de seguirlos.","Agregar una regla no quita el seguimiento de archivos ya indexados.","Un patrón de exclusión no es un comando de eliminación."],concept:"Exclusión de archivos con seguimiento",hints:["¿El archivo ya estaba bajo control de versiones?","Separa ignorar archivos nuevos de quitar contenido con seguimiento."]},
    "ghf-079": {prompt:"Una persona quiere guardar varios repositorios como favoritos sin suscribirse a todas sus conversaciones. ¿Qué función está pensada para eso?",choices:["Revisores obligatorios","Protección de ramas","Estrellas","Propiedad de la organización"],explanations:["Los revisores obligatorios regulan la aprobación de cambios.","La protección de ramas hace cumplir reglas de ramas.","Las estrellas ayudan a guardar y descubrir repositorios sin ser una suscripción Watch.","La propiedad otorga responsabilidades, no favoritos."],concept:"Estrellas de repositorios",hints:["¿Se busca guardar un proyecto o recibir actualizaciones?","Separa los favoritos de las suscripciones a notificaciones."]},
    "ghf-080": {prompt:"Una persona quiere organizar sus repositorios marcados con estrella en categorías personales. ¿Qué función debe considerar?",choices:["Hitos del repositorio","Ramas protegidas","Etiquetas de commits","Listas de repositorios con estrella"],explanations:["Los hitos agrupan issues y pull requests dentro de un repositorio.","La protección de ramas regula los cambios.","Las etiquetas identifican revisiones del repositorio.","Las listas organizan en colecciones los repositorios que una persona marcó con estrella."],concept:"Listas de estrellas",hints:["¿De quién es la colección que se organiza?","Distingue las herramientas personales de descubrimiento del seguimiento de trabajo del proyecto."]},
    "ghf-081": {prompt:"Un proyecto quiere ser más fácil de descubrir por quienes buscan rust y herramientas de línea de comandos. ¿Qué metadatos debe agregar?",choices:["Temas pertinentes","Solo etiquetas de issues","Patrones de propietarios de código","Un hito por lenguaje de programación"],explanations:["Los temas clasifican repositorios por propósito o tecnología para facilitar su descubrimiento.","Las etiquetas de issues clasifican elementos de trabajo, no aportan temas al repositorio.","Los patrones de propiedad identifican responsables de revisión.","Los hitos siguen entregas, no clasificaciones públicas de tecnología."],concept:"Temas de repositorios",hints:["¿Qué metadatos describen el tema del proyecto?","Piensa en descubrimiento, no en aplicación de reglas."]},
    "ghf-082": {prompt:"Una biblioteca llega a una versión lista para distribuir con notas de versión y binarios descargables. ¿Qué función de GitHub está diseñada para esto?",choices:["Una etiqueta de issue","Una versión publicada (release)","Una regla de CODEOWNERS","Un filtro de Watch"],explanations:["Las etiquetas clasifican elementos de trabajo, no distribuciones versionadas.","Las versiones publicadas empaquetan versiones etiquetadas con notas y recursos opcionales.","Las reglas de propiedad dirigen solicitudes de revisión.","Los filtros de Watch configuran notificaciones."],concept:"Versiones publicadas de repositorios",hints:["¿Qué combina una versión con información de distribución?","Separa la entrega del proyecto de la clasificación de tareas."]},
    "ghf-083": {prompt:"Un proyecto ya no se mantiene, pero su código y sus conversaciones deben quedar disponibles como referencia de solo lectura. ¿Qué debe considerar su administrador?",choices:["Eliminar cada archivo por separado","Hacer propietarios a todos los miembros","Archivar el repositorio","Crear un pull request por cada visitante"],explanations:["Eliminar archivos quitaría contenido actual útil sin indicar un estado archivado.","Otorgar propiedad aumenta el acceso, no conserva un estado de solo lectura.","Archivar marca el repositorio como inactivo y lo vuelve de solo lectura.","Los pull requests de visitantes no implementan el archivado de todo el repositorio."],concept:"Archivado de repositorios",hints:["¿El material debe seguir disponible?","¿Qué acción comunica inactividad sin eliminar?"]},
    "ghf-084": {prompt:"¿Qué acción restablece la actividad normal de escritura en un repositorio archivado?",choices:["Agregar una estrella","Descargar su ZIP de código fuente","Seguir a su propietario","Desarchivar el repositorio"],explanations:["Una estrella no cambia el estado de archivado.","Descargar solo copia contenido.","Seguir a un propietario no modifica la configuración del repositorio.","Un administrador autorizado puede desarchivarlo para reanudar las actualizaciones."],concept:"Restauración de trabajo archivado",hints:["¿Qué configuración lo volvió de solo lectura?","Distingue la configuración del ciclo de vida de una acción de visitante."]},
    "ghf-085": {prompt:"Se quiere ver qué paquetes usa el proyecto y cuáles de las dependencias compatibles tienen vulnerabilidades conocidas. ¿Qué capacidad del repositorio es pertinente?",choices:["Grafo de dependencias","Logros del perfil","Listas de estrellas","El título de un pull request"],explanations:["El grafo de dependencias resume las dependencias reconocidas y los metadatos relacionados.","Los logros describen actividad de la cuenta.","Las listas de estrellas organizan repositorios guardados como favoritos.","Un título no puede inventariar el árbol de dependencias."],concept:"Grafo de dependencias",hints:["¿Dónde se resumirían los datos de manifiestos y archivos de bloqueo?","Distingue las relaciones de software de los metadatos sociales."]},
    "ghf-086": {prompt:"¿Cómo obtiene información de dependencias el grafo de dependencias de GitHub?",choices:["Solo de nombres de repositorios","De manifiestos y archivos de bloqueo compatibles, más datos de dependencias enviados","Solo de capturas del README","De la lista de observadores del repositorio"],explanations:["El nombre de un repositorio no describe los paquetes resueltos.","Los archivos de dependencias reconocidos y la API de envío proporcionan los datos del grafo.","Las capturas no son manifiestos de dependencias.","Los observadores son personas interesadas en la actividad, no dependencias de paquetes."],concept:"Entradas del grafo de dependencias",hints:["¿Qué archivos estructurados declaran relaciones entre paquetes?","¿También se pueden enviar dependencias calculadas externamente?"]},
    "ghf-087": {prompt:"Una vista Insights del repositorio resume las contribuciones y la actividad. ¿Cuál es una interpretación responsable?",choices:["Demuestra el valor empresarial de cada contribuyente","Reemplaza la revisión del trabajo real","Aporta evidencia de actividad que necesita contexto","Garantiza que el código activo no tenga defectos"],explanations:["Las mediciones de actividad no demuestran directamente el valor empresarial.","La revisión cualitativa sigue siendo necesaria.","Insights ayuda a investigar la actividad, pero requiere interpretación contextual.","La actividad no garantiza que algo sea correcto."],concept:"Interpretación de Insights del repositorio",hints:["¿Contar actividad mide todos los resultados?","¿Qué contexto podría omitir una gráfica?"]},
    "ghf-088": {prompt:"Se quiere evaluar la actividad reciente de pull requests e issues, no inspeccionar los cambios de un solo archivo. ¿Qué área del repositorio es más pertinente?",choices:["La configuración personal de claves SSH","El archivo LICENSE","El área de preparación local","Insights del repositorio, incluido Pulse"],explanations:["La configuración SSH trata de autenticación.","Las licencias tratan de condiciones de reutilización.","La preparación describe contenido local sin confirmar.","Insights y Pulse resumen la actividad del repositorio entre elementos de trabajo."],concept:"Resumen de actividad",hints:["¿La pregunta trata de un diff o de trabajo agregado?","Busca una visión general de la actividad del repositorio."]},
    "ghf-089": {prompt:"Una persona quiere probar una función de interfaz en versión preliminar pública disponible para su cuenta. ¿Dónde debe buscar?",choices:["Feature preview en el menú del perfil","El área de preparación de commits de Git","El archivo LICENSE del repositorio","Las facturas de la organización"],explanations:["Feature preview enumera las funciones preliminares elegibles y sus controles disponibles.","La preparación no tiene controles de funciones de la cuenta.","Las licencias no configuran vistas preliminares de la interfaz de GitHub.","Las facturas no son la interfaz de funciones preliminares."],concept:"Feature preview",hints:["¿Es un archivo del repositorio o una experiencia de la cuenta?","Busca acceso opcional a funciones experimentales."]},
    "ghf-090": {prompt:"¿Por qué un equipo no debe tratar una función de GitHub en versión preliminar pública como si tuviera los mismos compromisos que una de disponibilidad general?",choices:["Las funciones preliminares no pueden tener documentación","La versión preliminar pública tiene distintos compromisos de soporte y servicio","Versión preliminar significa que la función tiene licencia de código abierto","Las funciones preliminares no pueden recibir comentarios"],explanations:["Las versiones preliminares públicas pueden estar documentadas.","La fase de lanzamiento afecta los compromisos de soporte y nivel de servicio.","La fase no determina las licencias del código fuente.","Los programas preliminares suelen solicitar comentarios expresamente."],concept:"Madurez de versiones preliminares",hints:["¿Qué comunica la fase de lanzamiento?","Distingue la disponibilidad para pruebas de los compromisos de producción."]},
    "ghf-091": {prompt:"Una persona quiere compartir un enlace a un archivo tal como existe hoy, sin que lo afecten ediciones posteriores de la rama. ¿Qué debe usar?",choices:["Un enlace solo a la página principal del repositorio","Un enlace al archivo con el nombre mutable de la rama","Un enlace permanente ligado al commit del archivo","Un enlace relativo que siga la rama explorada"],explanations:["La página principal no identifica la revisión del archivo.","Una rama puede avanzar a commits más recientes.","Un enlace permanente basado en un commit identifica una revisión inmutable del archivo.","Un enlace relativo que sigue una rama no fija una revisión histórica."],concept:"Enlaces permanentes a archivos",hints:["¿Qué cambia cuando avanza una rama?","¿Cómo puede la URL indicar una revisión fija?"]},
    "ghf-092": {prompt:"Una persona necesita entender por qué cambió un archivo específico el mes pasado. ¿Qué función debe examinar primero?",choices:["Solo el contenido actual sin formato del archivo","Solo la lista actual de ramas","Solo el resumen de lenguajes del repositorio","El historial de commits del archivo"],explanations:["El contenido actual omite la secuencia registrada y los mensajes.","Los nombres de ramas por sí solos no explican una edición histórica específica.","La composición por lenguajes no establece la intención del cambio.","El historial del archivo muestra los commits, mensajes y cambios pertinentes."],concept:"Historial de archivos",hints:["¿Qué registros conectan ediciones con mensajes y autores?","Concéntrate en la evidencia versionada de ese archivo."]},
    "ghf-093": {prompt:"Antes de eliminar un repositorio, ¿qué debe entender su propietario sobre la acción?",choices:["Elimina el repositorio y los datos asociados en lugar de simplemente marcarlo como inactivo","Equivale a cerrar un issue","Solo elimina un clon local","Solo cancela la suscripción del propietario a notificaciones"],explanations:["Eliminar es sustancialmente distinto de archivar y puede quitar datos asociados al repositorio.","Cerrar un issue deja el repositorio intacto.","Eliminar el repositorio alojado no es limpiar un clon local.","Las preferencias de notificación no determinan la existencia del repositorio."],concept:"Eliminación frente a archivado",hints:["¿Las personas deben poder seguir consultando el proyecto?","Distingue los cambios destructivos del ciclo de vida de las preferencias personales."]},
    "ghf-094": {prompt:"Un repositorio independiente nuevo necesita archivos iniciales sin historial heredado, mientras uno existente necesita una línea aislada para cambios continuos. ¿Qué combinación corresponde?",choices:["Un fork para el inicio y una versión publicada para las ediciones","Una plantilla para el inicio y una rama para los cambios continuos","Una rama como repositorio independiente y una etiqueta como línea editable","Un ZIP de código fuente como nuevo repositorio alojado y un recurso de versión como línea editable"],explanations:["Un fork hereda historial y una versión publicada no es una línea editable.","Las plantillas generan proyectos nuevos; las ramas aíslan cambios dentro de un proyecto.","Una rama no es un repositorio separado y una etiqueta es un marcador de versión.","Descargar un archivo comprimido no crea un repositorio alojado y los recursos no actúan como ramas."],concept:"Plantillas frente a ramas",hints:["¿Estas tareas crean un proyecto o cambian uno?","Asocia cada alcance al mecanismo de versiones adecuado."]},
    "ghf-095": {prompt:"Una persona reporta un cierre inesperado reproducible que necesita responsables y seguimiento hasta su resolución. ¿Qué objeto de colaboración es el mejor punto de partida?",choices:["Una versión publicada","Un gist","Un issue","Un tema de repositorio"],explanations:["Las versiones publicadas distribuyen versiones, no siguen defectos pendientes.","Un gist comparte contenido sin el flujo de issues del repositorio.","Un issue sigue errores concretos mediante conversación y asignación.","Los temas clasifican el repositorio, no registran defectos."],concept:"Issues para trabajo concreto",hints:["¿Hay un problema concreto que resolver?","¿Qué objeto permite seguir su ciclo de vida?"]},
    "ghf-096": {prompt:"Una comunidad quiere una conversación abierta sobre posibles rumbos a largo plazo, sin una tarea de implementación acordada todavía. ¿Qué función encaja mejor?",choices:["Una comprobación de estado obligatoria","Una etiqueta de versión","Un commit de fusión","GitHub Discussions"],explanations:["Las comprobaciones evalúan resultados automatizados, no alojan planificación abierta.","Las etiquetas identifican versiones históricas.","Los commits de fusión integran cambios.","Discussions permite conversaciones e ideas abiertas de la comunidad."],concept:"Discussions frente a issues",hints:["¿El grupo ya definió trabajo concreto?","¿Dónde pueden evolucionar las ideas antes de comprometerse con una tarea?"]},
    "ghf-097": {prompt:"Se abre un pull request en borrador para una refactorización incompleta. ¿Qué comunica el estado de borrador?",choices:["La propuesta aún no está lista para revisión normal y no se puede fusionar mientras sea borrador","La propuesta es invisible para los demás","La rama no contiene commits","La propuesta ya superó la revisión"],explanations:["Los borradores permiten colaboración temprana, pero deben marcarse como listos antes de fusionar.","El estado de borrador no controla la privacidad.","Los pull requests en borrador pueden contener commits y cambios.","El borrador no significa aprobación."],concept:"Pull requests en borrador",hints:["¿Incompleto significa privado?","¿Qué transición se necesita antes de poder fusionar?"]},
    "ghf-098": {prompt:"Un pull request de fix-export apunta a main. ¿Cuál es la rama base?",choices:["fix-export","main","Ambas por igual","La rama de respaldo local del autor"],explanations:["Fix-export es la rama de origen que aporta cambios.","La base es la rama de destino que recibiría la fusión.","Origen y base tienen funciones distintas.","Una rama local no relacionada no es el destino del pull request."],concept:"Ramas de origen y base",hints:["¿Qué rama recibe la propuesta?","Separa el origen de los cambios de su destino."]},
    "ghf-099": {prompt:"Una persona que revisa quiere comentar una línea modificada de un pull request. ¿Qué vista está pensada para eso?",choices:["Solo la pestaña general Conversation del pull request","Solo el archivo sin formato de la rama predeterminada","Files changed","Los resultados de búsqueda de issues del repositorio"],explanations:["La conversación general permite comentarios amplios, no seleccionar una línea modificada del diff.","El archivo base actual sin formato no ofrece el contexto de revisión en línea de la propuesta.","Files changed muestra el diff y permite comentarios de revisión en línea.","La búsqueda de issues no muestra los controles de diff en línea del pull request."],concept:"Revisión en línea",hints:["¿Dónde se muestra el diff propuesto?","¿El comentario trata de toda la propuesta o de una línea específica?"]},
    "ghf-100": {prompt:"Una persona que revisa encuentra un problema bloqueante y quiere que el resultado indique explícitamente que se necesitan cambios. ¿Qué acción corresponde?",choices:["Enviar una revisión aprobatoria con una nota","Enviar una revisión de solo comentarios","Marcar el archivo afectado como visto","Request changes"],explanations:["La aprobación comunica aceptación, no el resultado de solicitud de cambios buscado.","Una revisión de solo comentarios aporta observaciones sin el resultado de cambios solicitados.","El estado visto sigue la inspección, no una decisión de revisión.","Request changes registra un resultado de revisión que indica problemas por resolver."],concept:"Resultados de revisión",hints:["¿Qué acción comunica formalmente una solicitud de modificación?","Separa la decisión de revisión del avance de inspección."]}
    ,"ghf-101": {prompt:"Una persona que revisa propone reemplazar exactamente un pequeño fragmento de código. ¿Qué función permite al autor aplicar ese texto desde el flujo de revisión?",choices:["Un cambio sugerido en un comentario de revisión","Un comentario de texto sin bloque de cambio sugerido","Solo marcar el archivo como visto","Solo resolver el hilo de conversación"],explanations:["Los cambios sugeridos ofrecen un reemplazo aplicable directamente en el contexto de revisión.","El texto común puede describir un cambio, pero no tiene el control de sugerencia aplicable directamente.","El estado visto no codifica texto de reemplazo.","Resolver un hilo registra el estado de la conversación; no aplica código."],concept:"Cambios sugeridos",hints:["¿El comentario es un reemplazo textual específico?","¿Qué herramienta de revisión puede convertir observaciones en un commit?"]},
    "ghf-102": {prompt:"Un pull request dirigido a la rama predeterminada incluye Fixes #37 en su descripción. ¿Cuándo suele cerrarse automáticamente el issue referenciado?",choices:["Al abrir el pull request","Al fusionar el pull request con la rama predeterminada","Cuando alguien agrega una reacción","Cuando alguien lee la descripción durante la revisión"],explanations:["Abrir la propuesta crea una relación, pero no completa la corrección.","La fusión que cumple las condiciones cierra el issue vinculado.","Las reacciones no activan el cierre por palabras clave.","Leer la descripción no cambia el estado del issue."],concept:"Palabras clave de cierre",hints:["¿Qué evento indica que el cambio ya se integró?","Presta atención a la rama de destino."]},
    "ghf-103": {prompt:"Un pull request apunta a una rama de lanzamiento que no es la predeterminada y su descripción dice Closes #51. ¿Qué debe esperar el autor de esa palabra clave por sí sola?",choices:["Cierra el issue al guardar la descripción","Crea una relación de cierre que se completa al fusionar con cualquier rama","En este caso se ignora para la vinculación y el cierre automáticos de issues","Cierra el issue al llegar la primera revisión aprobatoria"],explanations:["Guardar una descripción no completa un flujo de cierre de issues.","Las palabras clave de cierre en descripciones no se aplican a todas las ramas de destino.","Se interpretan en pull requests dirigidos a la rama predeterminada.","Una aprobación no es el evento que cumple las condiciones de cierre."],concept:"Alcance de palabras clave en la rama predeterminada",hints:["¿La palabra clave especial se aplica a cualquier rama de destino?","Comprueba el requisito previo de la vinculación automática."]},
    "ghf-104": {prompt:"La descripción de un pull request debe cerrar el issue 19 de otro repositorio, tools/parser, cuando se fusione en las condiciones adecuadas. ¿Qué sintaxis lo expresa?",choices:["Fixes @tools/parser/19","Fixes #tools/parser/19","Fixes tools/parser:19","Fixes tools/parser#19"],explanations:["La arroba denota menciones, no esta referencia a issues.","El nombre del repositorio debe preceder al numeral.","Los dos puntos no son el separador documentado para issues de otro repositorio.","La forma propietario/repositorio#número califica la referencia al issue."],concept:"Enlaces a issues de otros repositorios",hints:["¿Cómo se proporciona el contexto del repositorio?","¿Dónde va el delimitador del número de issue?"]},
    "ghf-105": {prompt:"Un proyecto recibe reportes de errores sin pasos para reproducirlos. ¿Qué puede agregar para guiar de forma consistente a quienes reportan?",choices:["Una plantilla o formulario de issues","Un recurso de una versión publicada","Una etiqueta de Git","Un patrón de propietarios de código"],explanations:["Las plantillas y formularios guían la información recopilada en issues nuevos.","Los recursos distribuyen descargas versionadas.","Las etiquetas identifican revisiones.","Los patrones de propiedad dirigen revisiones; no estructuran reportes."],concept:"Plantillas de issues",hints:["¿Dónde se recopila la información de quien reporta?","Considera una estructura repetible de recepción."]},
    "ghf-106": {prompt:"Un equipo quiere que cada descripción nueva de pull request solicite un resumen, evidencia de pruebas e issues relacionados. ¿Qué debe configurar?",choices:["Un hito de issues","Una plantilla de pull request","Un slug de equipo de la organización","Una etiqueta de commit"],explanations:["Los hitos agrupan trabajo; no completan descripciones.","Una plantilla de pull request proporciona indicaciones estándar a los autores.","Un slug de equipo identifica un grupo.","Una etiqueta marca un commit, no un formato de envío."],concept:"Plantillas de pull request",hints:["¿Qué elemento se crea al presentar la propuesta?","Distingue las indicaciones de recepción de la clasificación del trabajo."]},
    "ghf-107": {prompt:"¿Qué búsqueda encuentra más directamente los issues abiertos asignados a la persona actual?",choices:["is:pr is:closed author:@me","is:issue is:open mentions:@me","is:issue is:open assignee:@me","is:issue is:closed assignee:@me"],explanations:["Selecciona pull requests cerrados creados por la persona.","Una mención no equivale a una asignación.","Los calificadores especifican issues abiertos asignados a la persona actual.","Selecciona issues cerrados, no abiertos."],concept:"Filtros de issues",hints:["¿Ser responsable equivale a recibir una mención?","Comprueba el tipo de objeto y el estado de su ciclo de vida."]},
    "ghf-108": {prompt:"Se necesitan pull requests abiertos que esperan la revisión de la persona actual, no solo los que creó. ¿Qué calificador identifica esa relación?",choices:["author:@me","assignee:@me","mentions:@me","review-requested:@me"],explanations:["Author identifica a quien creó el elemento.","Assignee identifica responsabilidad asignada, no específicamente una revisión solicitada.","Mentions incluye referencias textuales, no solicitudes explícitas de revisión.","Review-requested selecciona pull requests que solicitan la revisión de esa persona."],concept:"Filtros de solicitudes de revisión",hints:["¿Qué rol desempeña la persona?","Elige una solicitud explícita, no una relación general."]},
    "ghf-109": {prompt:"Una persona quiere actualizaciones solo de versiones publicadas de un repositorio al que tiene acceso. ¿Qué enfoque de notificaciones es el más adecuado?",choices:["Personalizar la suscripción Watch para versiones publicadas","Marcar el repositorio con estrella y asumir que se notificará cada versión","Seguir toda la actividad sin limitar los tipos","Suscribirse a un issue existente"],explanations:["Watch personalizado permite suscribirse a tipos seleccionados, como versiones publicadas.","Las estrellas no son una suscripción de notificaciones de versiones.","Seguir toda la actividad incluye más que las actualizaciones de versiones solicitadas.","Suscribirse a un issue no suscribe a futuras versiones del repositorio."],concept:"Suscripciones Watch personalizadas",hints:["¿Qué función controla la entrega de actividad?","¿Puede una suscripción ser más acotada que toda la actividad?"]},
    "ghf-110": {prompt:"Una persona quiere actualizaciones de un solo issue sin seguir todos los del repositorio. ¿Qué debe hacer?",choices:["Seguir toda la actividad de issues del repositorio","Suscribirse a la conversación de ese issue","Usar una estrella como sustituto de la suscripción","Solo marcar como no leída la notificación existente"],explanations:["Las actualizaciones de todos los issues son más amplias de lo solicitado.","Una suscripción a la conversación limita las actualizaciones a ese issue.","Una estrella no es una suscripción a esa conversación.","El estado no leído no establece por sí solo la suscripción continua deseada."],concept:"Suscripciones a conversaciones",hints:["¿Qué tan acotado debe ser el alcance de las actualizaciones?","Separa los controles personales de entrega del estado de la bandeja."]},
    "ghf-111": {prompt:"Una persona marca una notificación como leída sin cambiar su suscripción. ¿Qué debe esperar en general?",choices:["Todas las actualizaciones futuras del hilo quedan silenciadas para siempre","Se deja de seguir automáticamente el repositorio","La actividad futura suscrita aún puede generar notificaciones","Solo una nueva suscripción manual puede restablecer las actualizaciones"],explanations:["Marcar como leído no silencia permanentemente las actualizaciones futuras.","El estado leído no cambia la configuración Watch del repositorio.","El estado leído y la entrega futura de la suscripción son asuntos separados.","Marcar una actualización como leída no eliminó la suscripción existente."],concept:"Estado leído frente a suscripción",hints:["¿La persona cambió la configuración de entrega?","Distingue procesar una actualización de detener las futuras."]},
    "ghf-112": {prompt:"Una persona ya no necesita actualizaciones continuas de un hilo específico. ¿Qué acción cambia esa suscripción?",choices:["Marcar solo la última notificación como leída","Quitar el hilo de un filtro de la bandeja","Ocultarlo cambiando la búsqueda de issues","Cancelar la suscripción al hilo"],explanations:["El estado leído no cancela una suscripción continua.","Un filtro cambia el subconjunto mostrado, no la suscripción.","La presentación de búsquedas no cambia la entrega futura de notificaciones.","Cancelar la suscripción detiene la suscripción existente a la actividad continua del hilo."],concept:"Cancelación de suscripciones",hints:["¿Se quiere cambiar la presentación o la entrega futura?","¿Qué control regula la relación continua?"]},
    "ghf-113": {prompt:"Una persona quiere compartir un pequeño script de ejemplo con control de versiones sin crear toda la interfaz de un repositorio de proyecto. ¿Qué función corresponde?",choices:["Un gist","Un hito","Un equipo","Una regla de rama"],explanations:["Los gists están diseñados para compartir fragmentos y conservan el historial de Git.","Los hitos agrupan elementos de trabajo.","Los equipos agrupan miembros de organizaciones.","Las reglas de ramas imponen requisitos de cambios."],concept:"Gists",hints:["¿Cuánta estructura de proyecto se necesita?","¿Qué herramienta de intercambio se basa en Git?"]},
    "ghf-114": {prompt:"Alguien propone guardar una credencial confidencial en un gist secreto porque no aparece en listas públicas. ¿Cuál es la respuesta correcta?",choices:["Es seguro porque solo las cuentas invitadas pueden abrir gists secretos","No es seguro porque cualquiera que obtenga la URL puede verlo","Es seguro porque los gists secretos no tienen URL","Es seguro si la credencial se pone en un comentario"],explanations:["Los gists secretos no están listados; no son almacenamiento privado restringido a invitaciones.","Tener la URL puede exponer el contenido, por lo que no se deben almacenar credenciales allí.","Los gists secretos se pueden compartir por URL.","Los comentarios no establecen un límite seguro para credenciales."],concept:"Privacidad de gists secretos",hints:["¿No estar listado significa tener control de acceso?","¿Qué ocurre si se reenvía la URL?"]},
    "ghf-115": {prompt:"¿Qué afirmación sobre el control de versiones de gists es correcta?",choices:["Los gists permiten comentarios, pero nunca historial de revisiones","Solo los gists públicos pueden contener código","Los gists son repositorios Git que se pueden clonar y bifurcar mediante forks","Editar un gist requiere convertirlo en issue"],explanations:["Los gists conservan el historial de revisiones de Git.","Tanto los gists públicos como los secretos pueden contener código.","Git sustenta los gists y permite historial, clonación y forks.","Un gist se puede editar sin convertirlo en issue."],concept:"Historial de gists",hints:["¿Un gist es solo un mensaje estático pegado?","¿Qué se deriva de usar Git como base?"]},
    "ghf-116": {prompt:"Un repositorio necesita una colección navegable de páginas de documentación mantenidas por separado de los archivos principales de código. ¿Qué función está diseñada para eso?",choices:["Una aprobación de pull request","Una lista de recursos de versiones","Un estado de commit","Una wiki del repositorio"],explanations:["Una aprobación es un resultado de revisión, no una estructura de documentación.","Los recursos de versiones distribuyen descargas versionadas.","Un estado de commit informa el estado de una comprobación externa.","Las wikis permiten documentación de repositorio de varias páginas."],concept:"Wikis de repositorios",hints:["¿Basta un único archivo introductorio?","¿Qué función permite una colección de documentación?"]},
    "ghf-117": {prompt:"Un equipo quiere publicar un sitio web estático de documentación desde archivos del repositorio. ¿Qué función encaja mejor?",choices:["GitHub Pages","GitHub Issues","GitHub Sponsors","GitHub Mobile"],explanations:["Pages publica contenido de sitios estáticos desde repositorios.","Issues sigue trabajo y conversaciones.","Sponsors permite contribuciones económicas.","Mobile es un cliente de colaboración, no alojamiento estático."],concept:"GitHub Pages",hints:["¿El equipo necesita un sitio web publicado?","Separa el alojamiento de contenido de las conversaciones del proyecto."]},
    "ghf-118": {prompt:"Un sitio necesita un proceso Python del lado del servidor que se ejecute continuamente para atender solicitudes. ¿GitHub Pages puede proporcionar ese entorno de ejecución?",choices:["Sí; usar Python en la compilación también proporciona un controlador persistente de solicitudes","No; Pages ofrece alojamiento estático, no un entorno de servidor arbitrario","Sí; subir código Python inicia automáticamente un servicio web","Sí; un dominio personalizado convierte Pages en alojamiento del lado del servidor"],explanations:["Ejecutar durante la compilación no crea un backend continuamente activo.","Pages publica recursos generados, pero no aloja procesos de servidor persistentes arbitrarios.","Publicar código no aprovisiona un controlador Python de solicitudes.","Un dominio personalizado cambia la dirección, no el modelo de ejecución del alojamiento."],concept:"Límites del alojamiento de Pages",hints:["Distingue la generación al compilar de la ejecución al recibir solicitudes.","¿Qué implica el alojamiento estático para un backend?"]},
    "ghf-119": {prompt:"Una discusión de soporte tiene una solución útil que futuros lectores deben encontrar rápido. En una categoría que permite respuestas aceptadas, ¿qué acción la designa explícitamente?",choices:["Suscribirse a la discusión","Solo agregar una reacción de pulgar arriba","Marcar la respuesta útil como la respuesta aceptada","Bloquear la discusión sin seleccionar una respuesta"],explanations:["Suscribirse controla actualizaciones; no identifica una solución.","Una reacción expresa agradecimiento sin designar la respuesta.","Marcar una respuesta la destaca como solución en categorías compatibles.","Bloquear impide más interacción, pero no designa una respuesta."],concept:"Respuestas en Discussions",hints:["¿Qué diferencia hay entre agradecer e identificar formalmente una solución?","¿Qué acción registra el resultado de la pregunta resuelta?"]},
    "ghf-120": {prompt:"Un issue se convirtió en una conversación amplia de diseño sin tarea concreta. ¿Cómo conservarla en un formato más adecuado?",choices:["Eliminar el issue y su historial de conversación","Cerrarlo y bloquearlo sin indicar dónde conversar","Abrir un pull request sin cambios propuestos para usarlo de foro","Convertir el issue en una discusión donde sea compatible"],explanations:["Eliminar sacrifica la conversación en lugar de conservarla.","Bloquear termina la participación sin moverla a un formato mejor.","Los pull requests están pensados para revisar cambios propuestos.","La conversión de issue a discusión traslada la conversación abierta a la herramienta prevista."],concept:"Cambio de tipos de conversación",hints:["¿Cambió la naturaleza del trabajo?","¿Qué herramienta permite mejor el diálogo exploratorio?"]},
    "ghf-121": {prompt:"Un hilo de revisión se marca como resuelto. ¿Qué indica eso por sí solo?",choices:["Ese hilo se considera atendido, no que todo el pull request esté aprobado","Todas las comprobaciones de estado obligatorias pasaron","El pull request ya se fusionó","Todos los demás hilos de revisión están resueltos"],explanations:["Resolver un hilo se limita a la conversación; aprobar es otro resultado de revisión.","El estado del hilo no informa la ejecución de pruebas.","Resolver un hilo no fusiona cambios.","Los otros hilos conservan sus propios estados."],concept:"Alcance de la resolución de hilos",hints:["¿Cuál es el alcance de la acción?","Separa el avance de la conversación de la autorización para fusionar."]},
    "ghf-122": {prompt:"Una persona quiere abandonar un cambio propuesto sin aplicar sus commits a la rama base. ¿Qué debe hacer?",choices:["Combinar los commits y fusionar la propuesta","Cerrar el pull request sin fusionarlo","Marcar todos los archivos como vistos","Convertir la propuesta en borrador y dejarla abierta"],explanations:["Squash and merge también integra los cambios propuestos.","Cerrar sin fusionar termina la propuesta sin aplicarla a la base.","El estado visto solo sigue el avance de revisión.","Un borrador sigue siendo una propuesta abierta, no expresa abandono."],concept:"Cerrar frente a fusionar",hints:["¿Debe cambiar la rama de destino?","Distingue terminar una propuesta de aceptarla."]},
    "ghf-123": {prompt:"Se solicita la revisión de alguien del equipo en un pull request. ¿En qué se diferencia de asignárselo?",choices:["Las solicitudes de revisión conceden escritura; las asignaciones no","Las asignaciones cuentan como aprobaciones; las solicitudes son comentarios opcionales","Solicitar revisión pide evaluar explícitamente; asignar identifica responsabilidad","Ambos controles siempre registran la misma relación"],explanations:["Una solicitud de revisión no concede permiso de escritura.","Una asignación no es un resultado de revisión enviado.","La revisión y la asignación expresan relaciones de colaboración diferentes.","GitHub ofrece controles separados porque los roles son distintos."],concept:"Revisor frente a persona asignada",hints:["¿La responsabilidad siempre implica evaluar el diff?","¿Qué relación pide una revisión formal?"]},
    "ghf-124": {prompt:"Una persona aprueba un pull request, pero falla una comprobación automatizada obligatoria. ¿Qué debe deducir el autor?",choices:["La aprobación anula automáticamente toda comprobación","El fallo es solo una preferencia de notificación","La rama ya está fusionada","La aprobación y las comprobaciones obligatorias son condiciones de fusión separadas"],explanations:["Una aprobación no omite automáticamente comprobaciones obligatorias.","Un resultado de comprobación no es solo una configuración de suscripción.","La aprobación por sí sola no fusiona la rama.","Un repositorio puede exigir tanto revisión satisfactoria como comprobaciones aprobadas."],concept:"Condiciones de revisión y comprobación",hints:["¿Puede haber más de una condición para fusionar?","Separa el juicio humano de los resultados automatizados."]},
    "ghf-125": {prompt:"Una persona de ingeniería necesita una vista cronológica de commits con sus mensajes para investigar cuándo cambió un comportamiento. ¿Qué comando de Git corresponde?",choices:["git log","git status","git remote -v","git add"],explanations:["Log muestra el historial de commits registrado.","Status resume el árbol de trabajo y el índice actuales.","Remote -v enumera las URL remotas.","Add prepara contenido; no muestra historial registrado."],concept:"Inspección del historial de commits",hints:["¿Se trata de ediciones actuales o instantáneas pasadas?","¿Qué salida incluiría mensajes históricos?"]}
    ,"ghf-126": {prompt:"En Git, ¿qué identifica normalmente HEAD al trabajar con ramas?",choices:["El commit más antiguo del repositorio","La posición extraída actualmente, normalmente a través de la rama actual","La URL remota del próximo push","Todos los cambios del área de preparación"],explanations:["HEAD no es una referencia fija al commit más antiguo.","HEAD identifica la posición actual de la extracción y suele apuntar a la rama activa.","Las URL remotas se configuran aparte de HEAD.","El índice contiene contenido preparado; HEAD identifica una posición del historial."],concept:"HEAD",hints:["¿Qué identifica dónde estás trabajando ahora?","¿Podría moverse esta referencia al crear nuevos commits?"]},
    "ghf-127": {prompt:"Una rama de funcionalidad tiene nuevos commits después de crear una etiqueta en un commit anterior. ¿Qué sigue identificando esa etiqueta sin modificar?",choices:["El commit más reciente de cualquier rama","El pull request abierto más reciente","El commit anterior etiquetado","El árbol de trabajo actual con archivos sin confirmar"],explanations:["Las etiquetas no avanzan automáticamente al commit globalmente más reciente.","Las etiquetas se refieren a objetos Git, no a listas de pull requests.","Una etiqueta sin modificar sigue marcando su destino original.","Los archivos de trabajo sin confirmar no forman parte del destino de una etiqueta."],concept:"Etiquetas frente a ramas móviles",hints:["¿Qué referencia está pensada como marcador de versión?","¿Que avance una rama implica que avancen todas las referencias?"]},
    "ghf-128": {prompt:"Se quiere encontrar el commit más reciente que cambió cada línea de un archivo. ¿Qué vista es más útil?",choices:["Raw","Preview","La lista de ramas del repositorio","Blame"],explanations:["Raw muestra contenido sin atribución de commits por línea.","Preview renderiza contenido compatible, no muestra el origen del cambio de cada línea.","Los nombres de ramas no asocian líneas con commits.","Blame asocia las líneas con los commits que las modificaron más recientemente."],concept:"Atribución por línea",hints:["¿Se busca solo el contenido o también su procedencia?","¿Qué vista vincula líneas con cambios históricos?"]},
    "ghf-129": {prompt:"Un equipo quiere representar los numerosos commits pequeños de un pull request con un solo commit nuevo en la rama base. ¿Qué método habilitado corresponde?",choices:["Squash and merge","Crear un commit de fusión sin combinar commits","Cerrar sin fusionar","Rebase and merge conservando los commits separados"],explanations:["Squash combina los cambios propuestos en un commit en la base.","Una fusión normal conserva los commits individuales y agrega un commit de fusión.","Cerrar por sí solo no integra cambios.","Rebase and merge reaplica los commits por separado, no los consolida."],concept:"Fusión con squash",hints:["¿Deben conservarse las divisiones entre commits intermedios?","¿Qué método consolida el historial en lugar de solo integrarlo?"]},
    "ghf-130": {prompt:"Un equipo quiere ejecutar pruebas cada vez que se abre o actualiza un pull request. ¿Qué capacidad debe configurar?",choices:["Un tema de repositorio","Un flujo de trabajo de GitHub Actions","Solo una lista estática en README","Una respuesta guardada"],explanations:["Los temas clasifican proyectos sin ejecutar pruebas.","Actions puede automatizar pruebas en respuesta a eventos de pull requests.","Una lista documenta la intención, pero no ejecuta pruebas.","Las respuestas guardadas reutilizan texto; no ejecutan automatizaciones."],concept:"Integración continua",hints:["¿Qué debe responder a eventos del repositorio?","Distingue documentar una tarea de ejecutarla."]},
    "ghf-131": {prompt:"¿Dónde almacena normalmente un repositorio las definiciones de flujos de GitHub Actions?",choices:["Solo en la carpeta local .git/hooks","En LICENSE","Como archivos YAML en .github/workflows/","Como comentarios en una versión publicada"],explanations:["Los hooks locales de Git no definen flujos alojados de Actions.","LICENSE contiene términos legales.","GitHub descubre el YAML de flujos en .github/workflows/.","Los comentarios de versiones no son definiciones de flujos."],concept:"Ubicación de archivos de flujos",hints:["¿Debe GitHub descubrir configuración de automatización versionada?","Separa los hooks locales de los flujos alojados."]},
    "ghf-132": {prompt:"En GitHub Actions, ¿qué es un runner?",choices:["La persona asignada a un issue","Una etiqueta de errores urgentes","Una lista reutilizable de Markdown","La máquina que ejecuta un job"],explanations:["Las personas asignadas a issues no son infraestructura de ejecución.","Una etiqueta de urgencia no ejecuta comandos.","Una lista registra tareas, pero no es infraestructura de ejecución.","Los runners proporcionan el entorno de cómputo de los jobs de un flujo."],concept:"Runners de Actions",hints:["¿Dónde se ejecutan realmente los scripts?","Separa los metadatos del flujo de los recursos de cómputo."]},
    "ghf-133": {prompt:"Un flujo contiene pasos de checkout, instalación de dependencias y pruebas en un job. ¿Qué comparten normalmente esos pasos?",choices:["El entorno del runner del job","Automáticamente el directorio de trabajo de todos los demás jobs","Las credenciales de todos los propietarios de la organización","Los archivos sin confirmar de la laptop del autor"],explanations:["Los pasos de un job se ejecutan en el mismo entorno del runner.","Los jobs separados no comparten automáticamente directorios de trabajo.","Las credenciales de propietarios no se proporcionan implícitamente.","Los runners alojados no reciben automáticamente el estado sin confirmar de una laptop."],concept:"Pasos dentro de un job",hints:["¿Qué límite agrupa trabajo secuencial en un entorno?","No supongas que los datos cruzan automáticamente los límites entre jobs."]},
    "ghf-134": {prompt:"Un job de implementación debe esperar a que un job de pruebas termine correctamente. ¿Qué relación debe configurarse?",choices:["Usar nombres de visualización idénticos","Declarar una dependencia con needs","Listar la implementación después en YAML sin dependencia","Solo ejecutar ambos con la misma etiqueta de sistema operativo"],explanations:["Los nombres no establecen dependencias de ejecución.","Needs expresa la relación de requisito previo entre jobs.","El orden en YAML no vuelve secuenciales a los jobs independientes.","Coincidir en sistema operativo no crea una relación de requisito previo."],concept:"Dependencias entre jobs",hints:["¿Qué expresa un requisito previo, no una etiqueta?","¿Los jobs deben ser independientes?"]},
    "ghf-135": {prompt:"Una biblioteca necesita ejecutar el mismo job de pruebas con varias versiones de un lenguaje. ¿Qué función evita duplicarlo manualmente para cada versión?",choices:["Un fork","Una plantilla de pull request","Una estrategia de matriz","Una regla de propietarios de código"],explanations:["Los forks crean repositorios separados; no parametrizan jobs.","Las plantillas guían descripciones de pull requests.","Una matriz ejecuta un job con distintas combinaciones de variables.","La propiedad del código dirige revisiones, no combinaciones de ejecución."],concept:"Compilaciones de matriz",hints:["¿Qué parte del job varía entre ejecuciones?","Busca combinaciones parametrizadas."]},
    "ghf-136": {prompt:"Un paso de Actions invoca un componente compartido con uses para configurar las herramientas de un lenguaje. ¿Cómo se llama ese componente reutilizable?",choices:["Un runner","Un evento","Una matriz","Una acción"],explanations:["Un runner aporta infraestructura de ejecución, no el componente reutilizable de configuración.","Un evento activa la ejecución de un flujo.","Una matriz define combinaciones de variables de jobs.","Una acción es un componente reutilizable invocado por pasos del flujo."],concept:"Acciones reutilizables",hints:["¿Qué puede invocar un paso en lugar de código de shell propio?","Separa el componente de su máquina de ejecución y su desencadenante."]},
    "ghf-137": {prompt:"Un repositorio quiere automatizar el etiquetado de issues, no compilar software. ¿Es GitHub Actions una opción adecuada?",choices:["Sí; los flujos pueden responder a eventos más allá de compilaciones","No; Actions solo ejecuta comandos de compilador","No; los eventos de issues no pueden activar automatizaciones","Solo si cada issue contiene código ejecutable"],explanations:["Actions puede automatizar tareas del repositorio, como etiquetar issues.","Los flujos pueden ejecutar muchos tipos de comandos y acciones.","Los eventos de issues compatibles pueden activar flujos.","El contenido del issue no tiene que ser ejecutable."],concept:"Automatización más allá de CI",hints:["¿La automatización se limita a compilar?","¿Qué eventos de repositorio podrían iniciar un flujo?"]},
    "ghf-138": {prompt:"Un job requiere hardware especializado en una máquina operada por la empresa. ¿Qué opción de Actions debe evaluar el equipo?",choices:["Un runner estándar alojado en GitHub sin acceso a esa máquina","Un runner autohospedado","Una variable de matriz que solo nombra el hardware","Una descripción de la máquina en el flujo"],explanations:["Un runner alojado estándar no se convierte en el hardware operado por la empresa.","Los runners autohospedados permiten a la empresa proporcionar y administrar sus máquinas de ejecución.","Un valor de matriz por sí solo no proporciona hardware ni conecta un runner.","Documentar una máquina no la registra como entorno de ejecución."],concept:"Runners autohospedados",hints:["¿Quién necesita controlar la infraestructura de ejecución?","Separa seleccionar recursos de solo describirlos."]},
    "ghf-139": {prompt:"Se necesita la salida de error de un paso de pruebas fallido de Actions. ¿Dónde debe examinarse?",choices:["Solo en el mensaje del autor del commit","Solo en el nombre del archivo de flujo","En los registros del job y del paso de la ejecución correspondiente","Solo en una ejecución exitosa de una revisión anterior"],explanations:["Un mensaje de commit no es la salida de ejecución actual.","El nombre del archivo no revela la salida del comando fallido.","Los registros muestran los comandos y los errores del paso fallido.","Una ejecución exitosa anterior no proporciona la salida del fallo actual."],concept:"Diagnóstico de flujos",hints:["¿Dónde se registra la salida de ejecución?","Concéntrate en la ejecución fallida específica."]},
    "ghf-140": {prompt:"Al escribir una función en un editor compatible, una persona quiere sugerencias de código generadas por IA. ¿Qué herramienta está diseñada para eso?",choices:["GitHub Pages","GitHub Sponsors","Solo GitHub Projects","GitHub Copilot"],explanations:["Pages publica sitios estáticos.","Sponsors proporciona apoyo económico.","Projects sigue trabajo; no genera sugerencias en el editor.","Copilot ofrece asistencia de programación con IA en entornos compatibles."],concept:"Sugerencias de Copilot",hints:["¿La tarea es asistencia de programación o seguimiento de trabajo?","¿Qué herramienta se integra con la experiencia de programación del editor?"]},
    "ghf-141": {prompt:"Copilot sugiere una implementación plausible de una función auxiliar de autenticación. ¿Qué debe hacerse antes de aceptarla en producción?",choices:["Revisar su comportamiento y validarlo con pruebas y comprobaciones de seguridad adecuadas","Asumir que el código generado ya superó las pruebas del proyecto","Omitir la revisión porque la instrucción era detallada","Tratar su explicación como certificación de seguridad"],explanations:["Quien desarrolla sigue siendo responsable de evaluar los cambios generados.","Las sugerencias no demuestran que las pruebas del proyecto se ejecutaran correctamente.","El detalle de la instrucción no elimina las obligaciones de revisión.","Una explicación de IA no certifica la seguridad."],concept:"Validación responsable de IA",hints:["¿Quién responde por el código fusionado?","¿Qué evidencia validaría una sugerencia?"]},
    "ghf-142": {prompt:"Una persona de ingeniería pide a Copilot explicar una función desconocida y luego hace preguntas de seguimiento. ¿Qué interacción encaja mejor?",choices:["Solo aceptar una finalización de código en línea","Copilot Chat","Solo examinar un resumen de revisión sin conversación","Solo aplicar un fragmento predefinido del editor"],explanations:["Una finalización en línea sugiere código, pero no proporciona por sí sola el diálogo descrito.","Chat permite preguntas conversacionales y explicaciones de seguimiento.","Un resumen fijo no ofrece el diálogo explicativo continuo solicitado.","Un fragmento predefinido no es asistencia conversacional contextual."],concept:"Copilot Chat",hints:["¿El flujo implica diálogo?","Distingue una explicación interactiva de insertar código."]},
    "ghf-143": {prompt:"Se quiere un flujo de Copilot en el IDE capaz de localizar archivos, editar varios, ejecutar comandos y validar el resultado bajo supervisión. ¿Qué capacidad corresponde?",choices:["Solo una finalización en línea","Una respuesta guardada de issue","Modo agente","Una insignia estática de README"],explanations:["Una finalización en línea no es por sí sola un flujo de varios pasos con herramientas.","Las respuestas guardadas reutilizan texto; no cambian código.","El modo agente puede combinar investigación, ediciones y ejecución de comandos bajo supervisión.","Las insignias muestran información, pero no implementan cambios."],concept:"Modo agente de Copilot",hints:["¿Cuánto de la tarea se delega?","¿Requiere herramientas además de predecir el siguiente fragmento?"]},
    "ghf-144": {prompt:"Se delega un cambio de repositorio al agente en la nube de Copilot. ¿Dónde puede implementar el trabajo?",choices:["Solo en la terminal local abierta de quien mantiene el proyecto","Solo en un editor de navegador sin cómputo","Solo dentro de la vista renderizada de diferencias del pull request","En un entorno efímero de desarrollo en la nube con herramientas de edición y pruebas"],explanations:["El agente en la nube no requiere la terminal local del mantenedor como entorno de ejecución.","Un editor solo de navegador no proporciona el entorno de ejecución en la nube del agente.","La vista de diferencias muestra cambios propuestos; no ejecuta herramientas de implementación.","El agente puede editar y ejecutar herramientas en la nube para revisión posterior."],concept:"Agente de programación en la nube",hints:["¿Qué entorno se necesita para editar y ejecutar pruebas?","Separa la delegación en la nube de un editor ligero de navegador."]},
    "ghf-145": {prompt:"Una organización quiere asignar acceso a Copilot centralmente y controlar políticas para miembros, en lugar de administrar suscripciones individuales por separado. ¿Qué familia de planes corresponde?",choices:["Copilot Business o Copilot Enterprise","Cuentas Copilot Free administradas por cada usuario","Suscripciones individuales Copilot Pro sin licencias de organización","Solo un plan de repositorio de GitHub sin licencias de Copilot"],explanations:["Business y Enterprise proporcionan administración organizativa de Copilot.","Las cuentas Free separadas no ofrecen la administración centralizada solicitada.","Las suscripciones individuales independientes no son el modelo de administración organizativa.","Un plan de repositorio por sí solo no establece licencias organizativas de Copilot."],concept:"Planes organizativos de Copilot",hints:["¿Quién debe administrar el acceso?","Separa el uso personal de una implementación gobernada centralmente."]},
    "ghf-146": {prompt:"¿Cómo distinguir Copilot Enterprise de Copilot Business de forma estable y general?",choices:["Business es solo un cliente Git local","Enterprise amplía Business para empresas que usan GitHub Enterprise Cloud","Enterprise elimina la revisión humana del código","Business no puede tener controles de políticas organizativas"],explanations:["Business es un plan organizativo de Copilot, no un cliente Git.","Enterprise incluye las capacidades de Business y se dirige a clientes de GitHub Enterprise Cloud.","Ningún plan elimina la necesidad de revisar trabajo generado.","Business incluye administración centralizada y controles de políticas."],concept:"Copilot Business frente a Enterprise",hints:["Evita comparar precios o cuotas temporales.","¿Qué plan agrega capacidades empresariales a una base organizativa?"]},
    "ghf-147": {prompt:"Una persona puede elegir entre modelos de chat compatibles de Copilot. ¿Qué afirmación describe mejor esta capacidad?",choices:["Todos los modelos deben habilitarse en todas las cuentas","Elegir modelo garantiza una respuesta correcta","Los modelos disponibles pueden variar según plan, cliente y política organizativa","Cambiar modelo fusiona automáticamente todas las sugerencias"],explanations:["La disponibilidad está sujeta a restricciones de producto y políticas.","La selección de modelo no garantiza corrección.","El plan, la interfaz de uso y la configuración de la organización pueden afectar las opciones.","Seleccionar un modelo no autoriza fusiones."],concept:"Compatibilidad con múltiples modelos",hints:["¿Qué determina las opciones ofrecidas?","Separa la flexibilidad de las garantías de corrección."]},
    "ghf-148": {prompt:"Una persona cambia el modelo seleccionado en Copilot Chat. ¿Qué debe deducir sobre el modelo de sugerencias en línea?",choices:["Debe cambiar al mismo modelo","Las sugerencias en línea se deshabilitan hasta terminar el chat","El ajuste de chat siempre anula la configuración del modelo en línea","Seleccionar el modelo de chat no cambia por sí solo el de sugerencias en línea"],explanations:["Las configuraciones de modelos de chat y en línea son separadas.","Cambiar el modelo de chat no deshabilita intrínsecamente las sugerencias en línea.","El selector de chat no anula la configuración en línea separada.","El cambio documentado del modelo de chat no afecta al modelo de sugerencias en línea."],concept:"Modelos de chat frente a finalización",hints:["¿Chat y sugerencias en línea son la misma interfaz de interacción?","Comprueba el alcance del ajuste que se cambia."]},
    "ghf-149": {prompt:"Una persona pide a Copilot Chat ayuda para escribir pruebas de un analizador desconocido. ¿Qué contexto ayudaría más directamente a sugerir pruebas pertinentes?",choices:["El comportamiento esperado, los casos límite y las convenciones de pruebas del proyecto","Solo el nombre del archivo, sin contenido ni comportamiento","Solo la cantidad de archivos de pruebas existentes","Solo pedir maximizar líneas sin describir resultados esperados"],explanations:["Las expectativas de comportamiento y el contexto del proyecto orientan sugerencias útiles.","Un nombre de archivo rara vez explica el comportamiento esperado.","La cantidad de archivos no describe qué debe hacer el analizador.","El volumen de pruebas no define por sí solo comprobaciones significativas de corrección."],concept:"Contexto para asistencia de IA",hints:["¿Qué información define si el resultado de un analizador es correcto?","Distingue el contexto útil de comportamiento de las métricas de volumen."]},
    "ghf-150": {prompt:"Una persona nueva en el proyecto necesita un entorno de desarrollo en la nube que pueda compilarlo y ejecutarlo. ¿Qué función corresponde?",choices:["Un sitio GitHub Pages","GitHub Codespaces","Un gist secreto","Una lista de estrellas"],explanations:["Pages sirve contenido estático, no un entorno general de desarrollo.","Codespaces proporciona entornos de desarrollo en la nube con cómputo para ejecutar.","Un gist comparte fragmentos.","Las listas de estrellas organizan favoritos."],concept:"Propósito de Codespaces",hints:["¿La tarea requiere cómputo además de edición?","¿Qué opción es un entorno de desarrollo?"]}
    ,"ghf-151": {prompt:"Un equipo quiere que los nuevos codespaces incluyan los mismos entornos de ejecución, extensiones y configuración. ¿Qué debe versionar en el repositorio?",choices:["Solo instrucciones manuales sin configuración del entorno","Solo las preferencias personales de editor de un contribuyente","Una configuración de contenedor de desarrollo","Solo un archivo de GitHub Actions que ejecute pruebas en runners alojados"],explanations:["Las instrucciones ayudan a las personas, pero no configuran automáticamente codespaces nuevos.","Las preferencias personales no definen el entorno común del equipo.","La configuración de contenedor de desarrollo define un entorno de proyecto repetible.","Un flujo de pruebas de Actions no define el entorno de desarrollo de un codespace."],concept:"Entornos de desarrollo repetibles",hints:["¿La configuración puede expresarse como código?","¿Qué debe leer un entorno nuevo al iniciarse?"]},
    "ghf-152": {prompt:"¿Qué archivo suele ser la configuración principal del contenedor de desarrollo de un repositorio?",choices:["package.json","Dockerfile",".github/workflows/build.yml",".devcontainer/devcontainer.json"],explanations:["Package.json describe un paquete y sus scripts, no toda la configuración del contenedor de desarrollo.","Un Dockerfile puede definir la imagen, pero la configuración principal del contenedor lo referencia.","El YAML del flujo define automatización de Actions, no un contenedor de desarrollo.","Devcontainer.json define los ajustes del contenedor de desarrollo en esta ubicación habitual."],concept:"Archivo de configuración del contenedor de desarrollo",hints:["¿Qué configuración puede referirse a una imagen y a ajustes del editor a la vez?","Distingue la definición del entorno de uno de sus componentes."]},
    "ghf-153": {prompt:"Un repositorio no tiene configuración personalizada de contenedor de desarrollo. ¿Qué ocurre al crear desde él un codespace compatible?",choices:["Codespaces usa una configuración predeterminada de contenedor de desarrollo","La creación siempre falla solo por faltar devcontainer.json","El codespace copia todo el sistema operativo local de su creador","Se cambia a github.dev sin entorno de cómputo"],explanations:["Una imagen y configuración predeterminadas permiten empezar sin configuración personalizada.","La configuración personalizada no es obligatoria para crearlo.","Codespaces no clona el sistema operativo local de una persona.","La opción predeterminada sigue proporcionando cómputo, no solo un editor de navegador."],concept:"Entorno predeterminado de Codespaces",hints:["¿La configuración personalizada es obligatoria?","Considera un entorno base para quienes empiezan."]},
    "ghf-154": {prompt:"Se cambia la imagen y la configuración de instalación en devcontainer.json. ¿Qué acción aplica esto al contenedor de un codespace existente?",choices:["Solo actualizar la pestaña del navegador","Reconstruir el contenedor de desarrollo","Solo registrar el archivo en un commit sin recrear el contenedor","Solo volver a conectarse al contenedor en ejecución sin cambios"],explanations:["Actualizar el cliente no recrea el entorno desde su nueva configuración.","Reconstruir aplica los cambios pertinentes de configuración del contenedor.","Un commit registra la configuración, pero no reconstruye por sí mismo el contenedor existente.","Volver a conectarse no aplica una imagen y configuración nuevas."],concept:"Aplicación de configuración del contenedor",hints:["¿Editar la configuración necesariamente recrea un entorno en ejecución?","¿Qué acción del ciclo de vida aplica la nueva configuración?"]},
    "ghf-155": {prompt:"Se quiere un editor de navegador para editar texto rápidamente y crear un commit sin aprovisionar una máquina de desarrollo. ¿Qué opción corresponde?",choices:["Una máquina virtual nueva de Codespaces","Un runner autohospedado de Actions","El editor web github.dev","Un clon local nuevo abierto en un editor de escritorio"],explanations:["Un codespace aprovisiona cómputo más allá de lo requerido para solo editar.","Un runner ejecuta automatización; no proporciona este editor de navegador.","Github.dev ofrece edición ligera en navegador y control de código fuente.","Un clon local no es el flujo de edición solo de navegador solicitado."],concept:"Caso de uso de github.dev",hints:["¿Se necesita cómputo remoto?","Elige la herramienta cuyo alcance corresponde solo a editar."]},
    "ghf-156": {prompt:"Una persona abre github.dev y luego necesita una terminal interactiva para compilar el proyecto. ¿Qué siguiente paso satisface mejor esa necesidad?",choices:["Quedarse en el editor de navegador y esperar que aparezca un runner automáticamente","Abrir otra pestaña de github.dev para obtener cómputo","Solo cambiar el lenguaje de resaltado del editor","Pasar a un entorno con cómputo, como Codespaces"],explanations:["El editor solo de navegador no aprovisiona automáticamente un runner de desarrollo.","Otra pestaña del editor no crea un entorno de cómputo.","El resaltado cambia la presentación; no proporciona un entorno de ejecución.","Codespaces proporciona un entorno de ejecución de desarrollo, a diferencia del editor solo de navegador."],concept:"github.dev frente a Codespaces",hints:["¿Dónde se ejecutaría la compilación?","Distingue un editor de una máquina completa de desarrollo."]},
    "ghf-157": {prompt:"Una persona edita en github.dev y aún no ha creado un commit. ¿Qué consideración de persistencia es importante?",choices:["El trabajo sin confirmar se guarda en el almacenamiento del navegador, por lo que conviene crear commits regularmente","Cada pulsación ya es un commit enviado por push","Las ediciones ya existen en una rama remota oculta","Cerrar sesión necesariamente crea commits de todas las ediciones pendientes"],explanations:["El editor guarda el trabajo localmente hasta que los commits lo preservan en el historial del repositorio.","Editar no equivale a registrar y publicar un commit.","No debe suponerse que el trabajo del navegador sin confirmar existe en el historial remoto.","Cerrar sesión no es una operación de commit."],concept:"Persistencia del editor de navegador",hints:["¿Se creó un commit en el repositorio?","¿Qué podría pasar si se pierden los datos locales del navegador?"]},
    "ghf-158": {prompt:"Un codespace ejecuta una aplicación web que se quiere previsualizar en un navegador. ¿Qué función de desarrollo es pertinente?",choices:["Solo hacer push de su rama de código a GitHub","Reenvío de puertos","Solo abrir el archivo de código de la aplicación en el editor","Solo descargar el repositorio como ZIP"],explanations:["Publicar código no expone el servicio en ejecución del codespace.","Reenviar un puerto hace accesible un servicio del codespace para previsualizarlo.","Ver código no conecta el navegador al proceso activo.","Un archivo comprimido no es un punto de conexión de red del codespace."],concept:"Reenvío de puertos de Codespaces",hints:["¿Cómo puede llegar el navegador al proceso en ejecución?","Separa publicar código de proporcionar un punto de conexión al servicio de desarrollo."]},
    "ghf-159": {prompt:"Una persona quiere preferencias personales de shell en sus codespaces sin imponerlas como configuración del proyecto a todos. ¿Qué debe considerar?",choices:["Agregar todos sus alias a la configuración compartida del proyecto","Usar solo los colores del editor para configurar alias de shell","Un repositorio personal de dotfiles","Configurar el runner de Actions en lugar de sus codespaces"],explanations:["La configuración compartida impondría sus preferencias a otras personas.","Los colores del editor no configuran alias de shell.","Codespaces puede usar dotfiles personales para preferencias de shell y herramientas.","Un runner de Actions es un entorno distinto del codespace."],concept:"Personalización de Codespaces",hints:["¿La preferencia es personal o de todo el proyecto?","¿Cómo puede la configuración de shell acompañar a la persona?"]},
    "ghf-160": {prompt:"Una organización quiere un único espacio de planificación para issues y pull requests de varios repositorios. ¿Qué función corresponde?",choices:["Solo un hito de un repositorio","Solo la lista de etiquetas de un repositorio","El resumen de revisión de un pull request","Un GitHub Project de nivel organizativo"],explanations:["Un hito de repositorio no agrega trabajo de otros repositorios.","Las definiciones de etiquetas de un repositorio no proporcionan planificación entre repositorios.","Un resumen de revisión trata de un solo cambio propuesto.","Projects puede organizar trabajo de varios repositorios a nivel de organización."],concept:"Planificación entre repositorios",hints:["¿El alcance supera un repositorio?","¿Qué función reúne trabajo sin copiar su código?"]},
    "ghf-161": {prompt:"Una persona que planifica quiere examinar muchos elementos y editar valores de campos en filas y columnas. ¿Qué diseño de Project corresponde mejor?",choices:["Table","Board","Roadmap","Las diferencias de un archivo"],explanations:["Table presenta datos de elementos de trabajo en filas y columnas densas.","Board enfatiza tarjetas agrupadas en columnas.","Roadmap enfatiza fechas en una línea de tiempo.","Un diff compara cambios de archivos, no metadatos de proyecto."],concept:"Diseño de tabla de Project",hints:["¿Qué disposición se parece a registros estructurados?","¿La necesidad principal es editar campos o ver una línea de tiempo?"]},
    "ghf-162": {prompt:"Un equipo quiere mover tarjetas entre columnas Todo, In progress y Done. ¿Qué diseño de Project permite mejor ese flujo visual?",choices:["Roadmap","Board","Solo Table","Una página de recursos de versión"],explanations:["Roadmap muestra elementos en una línea de tiempo.","Board presenta tarjetas agrupadas por un campo como Status.","Table sirve para filas y campos, pero no es el diseño de tarjetas solicitado.","Los recursos de versiones distribuyen archivos; no siguen movimientos de tarjetas."],concept:"Diseño de tablero de Project",hints:["¿Cómo deben representarse los grupos de estado?","¿Qué diseño enfatiza tarjetas en lugar de fechas?"]},
    "ghf-163": {prompt:"Una persona responsable de producto quiere visualizar fechas de inicio y objetivo planificadas en una línea de tiempo. ¿Qué diseño debe elegir?",choices:["Board","Table","Roadmap","Un gráfico de conteo por estado en lugar de una línea de tiempo por elemento"],explanations:["Board enfatiza categorías, no intervalos temporales.","Table enumera campos, pero no proporciona el diseño de línea de tiempo.","Roadmap organiza trabajo en una línea de tiempo usando fechas.","Un gráfico por estado agrega elementos; no muestra sus intervalos programados."],concept:"Diseño de hoja de ruta de Project",hints:["¿La dimensión central es la categoría o el tiempo?","¿Qué vista hace visibles los cronogramas superpuestos?"]},
    "ghf-164": {prompt:"Un proyecto necesita un campo Priority limitado a Low, Medium o High. ¿Qué tipo de campo personalizado encaja mejor?",choices:["Texto libre","Un campo de fecha","Un campo numérico","Single select"],explanations:["El texto admite valores arbitrarios; no restringe a las opciones previstas.","Una fecha representa valores del calendario.","Los números no representan directamente esas categorías nombradas.","Los campos de selección única ofrecen un conjunto definido de opciones."],concept:"Campos de selección única",hints:["¿Deben las personas elegir de un vocabulario controlado?","Elige el tipo según la clase de valor."]},
    "ghf-165": {prompt:"Un equipo planifica trabajo en períodos repetidos y quiere un campo de Project que represente esos ciclos, incluidos descansos. ¿Qué tipo está previsto?",choices:["Iteration","Text","Assignee","Label"],explanations:["Los campos de iteración representan períodos repetidos de planificación y pueden incluir descansos.","El texto no modela intrínsecamente ciclos recurrentes.","Las personas asignadas identifican personas.","Las etiquetas clasifican trabajo; no definen períodos de planificación."],concept:"Planificación por iteraciones",hints:["¿El valor representa un período recurrente?","Distingue un elemento de programación temporal de una categoría."]},
    "ghf-166": {prompt:"La vista de clasificación de un proyecto debe mostrar solo elementos urgentes y conservar intacto todo el trabajo pendiente. ¿Qué debe configurar el equipo?",choices:["Eliminar todos los issues no urgentes","Una vista filtrada","Quitar del Project todos los elementos no urgentes","Ordenar por urgencia mostrando todos los elementos"],explanations:["Eliminar trabajo destruye la lista pendiente en lugar de conservarla.","Filtrar una vista cambia qué se muestra sin eliminar trabajo pendiente.","Quitar elementos cambia el trabajo pendiente subyacente del Project.","Ordenar cambia el orden; no limita la vista al trabajo urgente."],concept:"Vistas filtradas de proyectos",hints:["¿Debe eliminarse el trabajo oculto?","¿Cómo cambiar la presentación sin cambiar el conjunto subyacente?"]},
    "ghf-167": {prompt:"Dos partes interesadas quieren distintas disposiciones guardadas de los mismos elementos de Project. ¿Qué deben usar?",choices:["Issues copiados independientes para cada parte","Una vista sobrescrita sin alternativas guardadas","Varias vistas guardadas del proyecto","Credenciales separadas de una sola cuenta compartida"],explanations:["Las copias duplican innecesariamente el seguimiento del trabajo.","Sobrescribir una sola vista no conserva ambas perspectivas.","Las vistas guardadas conservan distintos filtros, diseños y disposiciones de los mismos elementos.","Las credenciales compartidas no son un mecanismo para administrar vistas."],concept:"Vistas guardadas",hints:["¿Hay que duplicar los elementos de trabajo?","Separa los datos de las formas de examinarlos."]},
    "ghf-168": {prompt:"Un issue ya agregado a un Project se asigna a otra persona desde Project. ¿Qué pasa con la persona asignada en el issue vinculado?",choices:["Siempre queda igual porque Projects son copias desconectadas","Se crea automáticamente un issue duplicado para la nueva persona","Cambia solo después de fusionar un pull request","La asignación también se refleja en el issue"],explanations:["Los metadatos del issue vinculado se sincronizan; no son una copia desconectada.","Editar el campo no requiere duplicar.","La sincronización de asignación no depende de una fusión de código.","Projects sincroniza los metadatos compartidos del issue en ambas direcciones."],concept:"Sincronización entre Project e issue",hints:["¿El elemento de Project es una copia desconectada?","¿Qué campos pertenecen al propio issue vinculado?"]},
    "ghf-169": {prompt:"Una idea de planificación pertenece a un Project, pero aún no está lista para ser un issue de repositorio. ¿Qué puede agregar primero el equipo?",choices:["Un issue en borrador en el Project","Un issue que debe asignarse de inmediato a un repositorio","Un pull request en borrador sin cambios propuestos","Un hito usado como si fuera un elemento individual de Project"],explanations:["Los issues en borrador permiten guardar trabajo preliminar en Project antes de convertirlo en issues de repositorio.","Un issue de repositorio exige la decisión de repositorio que se pospone.","Un pull request en borrador propone cambios de código; no representa una idea de planificación sin alcance definido.","Los hitos agrupan issues y pull requests de repositorio; no cumplen esa función de elemento en borrador."],concept:"Issues en borrador de Project",hints:["¿La planificación puede preceder a elegir un repositorio?","¿Qué tipo de elemento está diseñado para trabajo preliminar?"]},
    "ghf-170": {prompt:"Un equipo quiere que Status de un elemento de Project pase a Done al cerrarse su issue vinculado. ¿Cuál es la capacidad integrada pertinente más simple?",choices:["Una vista guardada que solo ordene por Status","Un flujo de automatización de Project","Una etiqueta Done escrita manualmente sin automatización","Una respuesta guardada que pida actualizar Status"],explanations:["Ordenar cambia la presentación; no reacciona a eventos del ciclo de vida.","Los flujos integrados pueden actualizar el estado en respuesta a eventos del ciclo de vida del issue.","Una etiqueta sola no actualiza el campo Status separado del Project.","Una respuesta puede pedir trabajo, pero no automatiza el campo."],concept:"Flujos integrados de Project",hints:["¿Qué evento debe actualizar qué campo?","Busca automatización de elementos de planificación."]},
    "ghf-171": {prompt:"Se quiere agregar automáticamente a un Project los nuevos issues que coincidan con un filtro de repositorio. ¿Qué capacidad debe configurarse?",choices:["Solo un filtro guardado sobre elementos que ya estén en el Project","Solo un flujo que marque Done los elementos existentes al cerrarse","Un flujo de adición automática","Solo un flujo de archivado automático"],explanations:["Un filtro de vista no agrega issues coincidentes ausentes del Project.","Un flujo de finalización maneja el estado existente, no la incorporación.","Los flujos de adición automática agregan al Project elementos de repositorio coincidentes.","El archivado automático quita elementos de la planificación activa; no agrega nuevos."],concept:"Incorporación automática a proyectos",hints:["¿La incorporación debe responder a trabajo futuro coincidente?","Distingue un filtro de visualización de una automatización que agrega elementos."]},
    "ghf-172": {prompt:"Un issue debe tener las categorías bug y accessibility. ¿Qué mecanismo está diseñado para aplicar estas clasificaciones reutilizables?",choices:["Un hito por cada categoría en ese issue","Temas de repositorio aplicados al issue","Una persona asignada por categoría","Etiquetas"],explanations:["Los hitos agrupan entregas; un issue no usa varios hitos como etiquetas de categorías.","Los temas clasifican repositorios, no issues individuales.","Las personas asignadas indican responsables, no categorías.","Las etiquetas clasifican issues y pull requests y pueden combinarse."],concept:"Etiquetas",hints:["¿Son categorías o identidades responsables?","¿Puede un mismo elemento pertenecer a varias clasificaciones?"]},
    "ghf-173": {prompt:"Un repositorio quiere agrupar issues y pull requests de una versión planificada y seguir su avance conjunto hacia una fecha límite. ¿Qué función corresponde?",choices:["Un hito","Un tema del repositorio","Una suscripción Watch","Un comentario individual de revisión"],explanations:["Los hitos agrupan elementos de trabajo y permiten seguir el avance y las fechas límite.","Los temas clasifican todo el repositorio.","Watch controla actualizaciones entregadas a una persona.","Un comentario de revisión no agrupa trabajo de una versión."],concept:"Hitos",hints:["¿El grupo está ligado a un objetivo de entrega?","¿Qué función resume el avance del trabajo relacionado?"]},
    "ghf-174": {prompt:"Una persona de soporte publica repetidamente la misma solicitud de diagnóstico y quiere texto de comentario reutilizable que pueda insertar y adaptar. ¿Qué función está prevista?",choices:["Una regla de rama","Respuestas guardadas","Una etiqueta de commit","Un campo de fecha de proyecto"],explanations:["Las reglas de ramas regulan cambios del repositorio.","Las respuestas guardadas almacenan respuestas de comentarios reutilizables.","Las etiquetas identifican revisiones.","Los campos de fecha guardan fechas de planificación, no plantillas de respuesta."],concept:"Respuestas guardadas",hints:["¿Qué trabajo repetido se reduce?","Separa el texto de conversación reutilizable de la automatización del repositorio."]},
    "ghf-175": {prompt:"Un equipo quiere dejar claro quién es responsable del seguimiento de un issue específico. ¿Qué campo debe usar?",choices:["Solo Labels","Milestone","Assignees","La iteración del Project"],explanations:["Las etiquetas clasifican trabajo, pero no son el campo de responsabilidad personal.","Un hito identifica una agrupación de entrega.","Assignees comunica quién es responsable del trabajo del issue.","Una iteración identifica un período de planificación, no a una persona responsable."],concept:"Responsabilidad de issues",hints:["¿Qué metadatos identifican a responsables del seguimiento?","No confundas responsabilidad con categoría o calendario."]}
    ,"ghf-176": {prompt:"Una persona de gerencia quiere gráficos de la distribución del trabajo de Project por estado, sin tratar conteos brutos de actividad como medida completa del desempeño laboral. ¿Qué función corresponde?",choices:["Estadísticas de tráfico del repositorio","Blame de un solo archivo","Solo el calendario personal de contribuciones","Insights del Project"],explanations:["El tráfico mide visitas, no la distribución de estados del Project.","Blame atribuye líneas de archivos a commits.","Un calendario de contribuciones no grafica los campos de elementos del Project.","Insights del Project visualiza datos de elementos; su interpretación aún necesita contexto."],concept:"Insights del Project",hints:["¿Dónde están organizados los datos de planificación pertinentes?","¿Qué muestra un gráfico y qué no demuestra?"]},
    "ghf-177": {prompt:"Un equipo quiere conservar elementos completados como registros archivados del Project, no activos, sin eliminar sus issues del repositorio. ¿Qué acción corresponde?",choices:["Archivar los elementos del Project","Eliminar los elementos del Project en vez de archivarlos","Solo ocultar la columna Status","Archivar todo el repositorio"],explanations:["Archivar elementos los conserva como registros archivados fuera de las vistas activas.","Eliminarlos no los conserva en el archivo del Project.","Ocultar una columna no cambia el estado de archivado de un elemento.","Archivar el repositorio cambia todo el repositorio, no elementos específicos del Project."],concept:"Archivado de elementos de proyecto",hints:["¿Deben seguir recuperables los registros de planificación?","¿Qué alcance necesita un cambio de ciclo de vida?"]},
    "ghf-178": {prompt:"¿Por qué agregar autenticación de dos factores fortalece una cuenta protegida por contraseña?",choices:["Hace públicos los repositorios de la cuenta","Exige un factor de autenticación adicional a la contraseña","Evita todos los ataques de phishing posibles","Reemplaza todos los permisos del repositorio"],explanations:["La autenticación no determina la visibilidad.","Un factor adicional reduce la dependencia de poseer solo la contraseña.","Algunos métodos de segundo factor aún pueden ser víctimas de phishing.","La autorización sigue siendo independiente de la autenticación."],concept:"Autenticación de dos factores",hints:["¿Qué pasa si alguien conoce la contraseña?","Distingue demostrar identidad de conceder acceso."]},
    "ghf-179": {prompt:"Una persona con 2FA inicia sesión en GitHub con una clave de acceso (passkey) registrada. ¿Qué afirmación es correcta?",choices:["Debe publicar la clave privada en su perfil","Debe deshabilitar 2FA primero","La passkey puede satisfacer tanto la contraseña como los requisitos de 2FA","Las passkeys son solo etiquetas de contraseñas guardadas"],explanations:["Las claves privadas deben permanecer protegidas por el autenticador.","Las passkeys pueden usarse con 2FA habilitada.","Las passkeys de GitHub pueden completar los requisitos de inicio de sesión en un paso.","Usan criptografía de clave pública; no simplemente cambian el nombre a las contraseñas."],concept:"Inicio de sesión con passkey",hints:["¿Cómo trata GitHub una passkey para alguien con 2FA?","Separa una credencial criptográfica de una contraseña almacenada."]},
    "ghf-180": {prompt:"¿Qué hace resistentes a las passkeys frente a páginas comunes de phishing de credenciales?",choices:["La persona debe pegar la clave privada en cada formulario de inicio de sesión","El mismo código reutilizable funciona en todos los dominios","Eliminan la necesidad de verificar el servicio al que se accede","Están vinculadas al dominio del sitio web legítimo"],explanations:["Una passkey no requiere exponer la clave privada en un formulario.","No son códigos universales reutilizables.","La vinculación al dominio es precisamente una protección de identidad del servicio.","Los autenticadores vinculan la credencial al dominio y resisten sitios imitadores."],concept:"Resistencia al phishing de passkeys",hints:["¿Podría un sitio imitador usar el mismo procedimiento de credenciales?","Piensa en la relación entre la credencial y la identidad del servicio."]},
    "ghf-181": {prompt:"Una persona habilita 2FA y quiere reducir el riesgo de perder acceso si pierde su teléfono. ¿Qué debe hacer?",choices:["Guardar los códigos de recuperación de forma segura y configurar alternativas adecuadas","Publicar los códigos en un issue","Confiar solo en recordar la URL del repositorio","Compartir su contraseña con todo el equipo"],explanations:["El material de recuperación protegido y los métodos alternativos facilitan recuperar la cuenta.","Publicar códigos expone la capacidad de recuperar la autenticación.","Una URL no demuestra control de la cuenta.","Compartir una contraseña debilita la seguridad y no sustituye una recuperación bien configurada."],concept:"Preparación para recuperar cuentas",hints:["¿Qué método confiable queda si se pierde el dispositivo principal?","Mantén el material de recuperación separado de la colaboración pública."]},
    "ghf-182": {prompt:"Un equipo necesita un repositorio que cualquiera en internet pueda leer sin invitación. ¿Qué visibilidad corresponde?",choices:["Private","Public","Solo Internal","Visibilidad de gist secreto"],explanations:["Los repositorios privados requieren acceso adecuado.","Los repositorios públicos pueden ser leídos por cualquiera en internet.","La visibilidad interna se limita a una empresa, no a todo internet.","Gist secreto no es una visibilidad de repositorio y significa no listado, no privado por invitación."],concept:"Visibilidad pública",hints:["¿Quién es el público lector previsto?","Distingue acceso empresarial de acceso para todo internet."]},
    "ghf-183": {prompt:"Un equipo quiere archivos confidenciales legibles solo por personas autorizadas, no por toda la empresa ni internet. ¿Qué visibilidad es el mejor punto de partida?",choices:["Public","Internal","Private","Con estrella"],explanations:["Public permite lectura en todo internet.","Internal permite lectura más amplia por miembros de la empresa.","Private restringe el acceso a personas autorizadas, sujeto al acceso administrativo.","La estrella es un estado de favorito, no un límite de visibilidad."],concept:"Visibilidad privada",hints:["¿Qué tan amplio debe ser el público lector?","Elige un límite de acceso, no un favorito personal."]},
    "ghf-184": {prompt:"Una empresa habilita repositorios internos. ¿Cuál es su alcance de visibilidad previsto?",choices:["Todos los visitantes anónimos de internet","Solo quien creó cada repositorio","Solo miembros de un clon Git local","Miembros de la empresa, no el público general"],explanations:["Internal no es visibilidad pública de internet.","Los repositorios internos tienen un alcance mayor que solo el creador.","Los clones locales no definen la visibilidad alojada.","La visibilidad interna permite lectura a nivel empresarial dentro del límite empresarial documentado."],concept:"Visibilidad interna",hints:["¿Qué límite organizativo describe interno?","Separa la membresía empresarial del acceso anónimo."]},
    "ghf-185": {prompt:"¿El permiso de leer un repositorio público permite automáticamente hacer push de commits directamente?",choices:["No; el acceso de escritura es un permiso separado","Sí; público significa modificación sin restricciones","Sí, después de marcarlo con estrella","Sí, después de descargar un ZIP"],explanations:["La visibilidad concede lectura; modificar directamente depende de la autorización.","La lectura pública no concede derechos de escritura directa.","Las estrellas no elevan permisos.","Descargar no cambia la autorización."],concept:"Visibilidad frente a escritura",hints:["¿Leer y modificar son la misma capacidad?","Considera por qué las personas externas usan pull requests."]},
    "ghf-186": {prompt:"Una persona que no contribuye código necesita leer y conversar en un repositorio de organización, sin administrar issues ni hacer push. ¿Qué rol estándar tiene los privilegios mínimos adecuados?",choices:["Admin","Read","Write","Maintain"],explanations:["Admin concede mucha más autoridad de la necesaria.","Read permite ver y conversar sin autoridad de escritura de código.","Write incluye push de código más allá del requisito.","Maintain está pensado para administración más amplia del repositorio."],concept:"Rol Read de repositorio",hints:["¿Cuál es la capacidad mínima necesaria?","Evita conceder administración solo para participar."]},
    "ghf-187": {prompt:"Una persona de soporte debe etiquetar y administrar issues de forma proactiva, pero no hacer push de código. ¿Qué rol estándar encaja mejor?",choices:["Read","Write","Triage","Admin"],explanations:["Read no proporciona el rol de administración proactiva previsto.","Write agrega push de código innecesario.","Triage está pensado para administrar issues y pull requests sin escritura.","Admin concede innecesariamente control sensible del repositorio."],concept:"Rol Triage de repositorio",hints:["¿La tarea requiere modificar código?","¿Qué rol queda entre lectura básica y escritura de código?"]},
    "ghf-188": {prompt:"Una persona de ingeniería necesita hacer push activamente de código, pero no administrar el repositorio. ¿Qué rol estándar ofrece los privilegios mínimos?",choices:["Read","Triage","Admin","Write"],explanations:["Read no concede push de código.","Triage permite administrar elementos de trabajo sin escritura de código.","Admin concede capacidades destructivas y sensibles innecesarias.","Write está pensado para contribuyentes activos de código."],concept:"Rol Write de repositorio",hints:["¿Qué permiso es esencial para el trabajo?","Elige el menor rol estándar que incluya actualizar código."]},
    "ghf-189": {prompt:"Una persona que gestiona proyectos necesita administración cotidiana amplia del repositorio sin poderes sensibles o destructivos de administrador. ¿Qué rol estándar está diseñado para eso?",choices:["Maintain","Read","Triage","Admin"],explanations:["Maintain está orientado a administrar repositorios sin toda la autoridad sensible y destructiva de Admin.","Read es insuficiente para administración amplia.","Triage se centra en issues y pull requests sin escritura de código.","Admin incluye poderes que el requisito evita expresamente."],concept:"Rol Maintain de repositorio",hints:["¿Se necesita más que clasificar issues?","¿Qué rol se queda deliberadamente antes de la administración completa?"]},
    "ghf-190": {prompt:"Entre los roles estándar de repositorios de organización, ¿cuál incluye control completo, con acciones destructivas como eliminar el repositorio?",choices:["Write","Admin","Triage","Read"],explanations:["Write permite contribuir, no administración completa.","Admin proporciona acceso completo, incluidas acciones sensibles y destructivas.","Triage no permite eliminar repositorios.","Read se limita a visualización y participación."],concept:"Rol Admin de repositorio",hints:["¿Qué rol tiene el nivel estándar de privilegio más alto?","Distingue las capacidades de contribución de la administración destructiva."]},
    "ghf-191": {prompt:"Una empresa quiere administrar el acceso a repositorios de un grupo de ingeniería completo, no miembro por miembro. ¿Qué función corresponde?",choices:["Temas de repositorios","Hitos de issues","Equipos","Etiquetas de versiones"],explanations:["Los temas clasifican repositorios sin conceder acceso.","Los hitos agrupan elementos de trabajo.","Los equipos agrupan miembros de organizaciones y pueden recibir permisos de repositorio.","Las etiquetas identifican versiones, no el acceso de personas."],concept:"Permisos basados en equipos",hints:["¿Qué agrupa personas, no tareas?","¿Cómo puede la membresía simplificar cambios repetidos de acceso?"]},
    "ghf-192": {prompt:"Un equipo de ingeniería padre recibe escritura en un repositorio. ¿Qué relación de acceso se aplica a sus equipos hijos anidados?",choices:["Los hijos reciben solo lectura sin importar el permiso del padre","Los permisos del padre nunca afectan a los hijos","El permiso pasa a equipos hermanos no relacionados, pero no a los hijos","Los hijos heredan los permisos de acceso al repositorio del padre"],explanations:["La herencia no se reduce automáticamente a lectura.","Los equipos anidados sí heredan el acceso al repositorio del padre.","La herencia sigue la relación padre-hijo, no equipos hermanos no relacionados.","Los equipos anidados heredan permisos de acceso de sus equipos padres."],concept:"Herencia de equipos anidados",hints:["¿En qué dirección fluye la herencia de permisos?","Distingue una relación jerárquica de la pertenencia a equipos no relacionados."]},
    "ghf-193": {prompt:"Una persona contratista necesita acceso a un repositorio de organización sin unirse a ella. ¿Qué relación está diseñada para eso?",choices:["Colaborador externo","Propietario de organización","Responsable de mantenimiento de equipo padre","Propietario de empresa"],explanations:["Los colaboradores externos pueden recibir acceso a repositorios específicos sin membresía de organización.","La propiedad concede acceso administrativo mucho más amplio y membresía.","La membresía de equipos es para miembros de la organización y el mantenimiento no hace falta.","La propiedad empresarial excede ampliamente el alcance indicado."],concept:"Colaboradores externos",hints:["¿La persona necesita membresía o solo acceso al repositorio?","Limita el acceso al recurso requerido."]},
    "ghf-194": {prompt:"Una persona de finanzas necesita administrar información de pago sin ser propietaria completa de la organización. ¿Qué rol predefinido está pensado para esa responsabilidad?",choices:["Team maintainer","Billing manager","Triage de repositorio","Propietario de código"],explanations:["Quienes mantienen equipos administran sus ajustes, no los pagos de la organización.","Billing manager administra la configuración de facturación de la organización.","Triage de repositorio trata de administrar elementos de trabajo.","La propiedad del código dirige revisiones de archivos."],concept:"Administración de facturación",hints:["¿Qué alcance trata de pagos, no de código?","Evita propiedad completa para una tarea administrativa especializada."]},
    "ghf-195": {prompt:"¿Cuál es un propósito central de Enterprise Managed Users?",choices:["Mantener el aprovisionamiento de cuentas de empleados totalmente separado del IdP de la empresa","Dar al IdP control sobre toda cuenta personal de GitHub no relacionada","Administrar el aprovisionamiento y la autenticación mediante un proveedor de identidad externo","Sincronizar archivos del repositorio con un IdP en lugar de administrar identidades"],explanations:["EMU integra específicamente el ciclo de vida de cuentas con el IdP.","Las identidades administradas son distintas del control irrestricto de cuentas personales ajenas.","Un IdP administra el ciclo de vida y la autenticación de las cuentas administradas por la empresa.","EMU trata de identidad y acceso, no de reemplazar el almacenamiento Git."],concept:"Enterprise Managed Users",hints:["¿Quién debe controlar el ciclo de vida de la identidad del empleado?","Separa la administración de identidades del almacenamiento del repositorio."]},
    "ghf-196": {prompt:"Una persona con cuenta de usuario administrada quiere usarla para contribuir a un proyecto público ajeno a su empresa. ¿Qué limitación debe reconocer?",choices:["Las cuentas administradas se vuelven automáticamente mantenedoras de proyectos públicos","Son identidades personales ordinarias sin restricciones","Marcar el proyecto con estrella habilita la colaboración pública","Las cuentas administradas tienen restringida la colaboración fuera de su empresa"],explanations:["El tipo de cuenta no otorga autoridad de mantenimiento en proyectos públicos.","Las cuentas administradas tienen restricciones específicas de empresa.","Las estrellas no cambian los límites de cuentas administradas.","Las identidades administradas no pueden usarse como cuentas irrestrictas de colaboración externa."],concept:"Límites de cuentas administradas",hints:["¿La cuenta está pensada para trabajo dentro de la empresa?","Comprueba restricciones de identidad, no popularidad del repositorio."]},
    "ghf-197": {prompt:"Una empresa deshabilita explícitamente una función de Copilot por política. ¿Puede un administrador de organización rehabilitarla por su cuenta para el acceso gobernado de esa organización?",choices:["No; la organización no puede anular ese ajuste impuesto por la empresa","Sí; la configuración de organización siempre prevalece","Sí; las preferencias personales de cada miembro anulan la restricción","Sí; un administrador de repositorio puede anularla para un repositorio"],explanations:["Las políticas empresariales obligatorias limitan los ajustes de organización.","Las opciones de organización quedan dentro de las restricciones impuestas por la empresa.","Las preferencias individuales no superan la restricción empresarial del acceso gobernado.","Administrar un repositorio no anula una política empresarial obligatoria de Copilot."],concept:"Prioridad de políticas de Copilot",hints:["¿Qué alcance administrativo estableció la restricción?","Distingue opciones delegadas de políticas obligatorias."]},
    "ghf-198": {prompt:"Una organización quiere controlar las funciones y modelos de Copilot disponibles para miembros con licencias de esa organización. ¿Dónde debe administrarlo alguien autorizado?",choices:["Solo en las preferencias individuales del editor","En las políticas de Copilot de la organización, sujetas a las políticas empresariales","Solo en CODEOWNERS","Solo en la protección de la rama main"],explanations:["Las preferencias personales del editor no establecen políticas de servicio de toda la organización.","Las políticas de Copilot de organización controlan funciones y modelos dentro de las restricciones empresariales.","La propiedad del código define responsabilidad de revisión, no funciones de Copilot.","La protección de ramas regula cambios, no políticas organizativas de modelos de Copilot."],concept:"Gobernanza organizativa de Copilot",hints:["¿Qué alcance administrativo otorga esas licencias?","Separa las políticas de servicio de las reglas de flujo del repositorio."]},
    "ghf-199": {prompt:"Un equipo quiere que main acepte cambios solo con revisión requerida y comprobaciones aprobadas para quienes no pueden omitir reglas. ¿Qué debe configurar?",choices:["Solo un nombre descriptivo de rama","Un pedido en README de tener cuidado","Protección de ramas o un conjunto de reglas adecuado","Un tema de repositorio llamado protected"],explanations:["Los nombres no imponen requisitos de fusión.","Las pautas escritas no implementan barreras técnicas.","Las protecciones y los conjuntos de reglas pueden exigir revisión y comprobaciones.","Los temas son metadatos de descubrimiento, no de aplicación de reglas."],concept:"Requisitos de ramas protegidas",hints:["¿Basta una convención escrita?","¿Qué ajustes pueden bloquear una integración que incumple requisitos?"]},
    "ghf-200": {prompt:"Un administrador puede omitir actualmente una regla clásica de protección de ramas. El equipo quiere aplicarla también a administradores. ¿Qué debe examinar?",choices:["Solo la cantidad de comprobaciones obligatorias","Solo los patrones de rutas de CODEOWNERS","Solo si el nombre de la rama contiene main","Los ajustes de aplicación de la regla relativos a omisiones"],explanations:["Agregar comprobaciones no quita por sí solo la exención administrativa.","Los patrones de propiedad identifican revisores; no determinan omisiones administrativas.","El nombre de una rama no establece por sí solo aplicación a administradores.","La protección clásica puede configurarse para restringir a administradores en lugar de permitir la omisión predeterminada."],concept:"Omisión de protección de ramas",hints:["¿Quién está exento de la regla actual?","Revisa el alcance de aplicación en vez de agregar más requisitos."]}
    ,"ghf-201": {prompt:"Una organización usa reglas clásicas de protección de ramas y varios patrones coinciden con una rama. ¿Qué debe saber quien administra?",choices:["Solo se aplica una regla clásica a la vez; los conjuntos de reglas tienen otro modelo de superposición","Todas las reglas clásicas coincidentes siempre se combinan","El commit más reciente elige una regla al azar","Coincidir con varios patrones deshabilita la protección"],explanations:["La protección clásica usa una regla aplicable, a diferencia de conjuntos de reglas superpuestos.","Las reglas clásicas no se combinan solo por coincidir sus patrones.","La selección de reglas no es aleatoria por commit.","Los patrones superpuestos no deshabilitan intrínsecamente la protección."],concept:"Reglas de ramas frente a conjuntos de reglas",hints:["¿La pregunta trata de reglas clásicas o conjuntos de reglas?","No supongas que sus modelos de combinación son idénticos."]},
    "ghf-202": {prompt:"Un token de acceso válido se incluyó por accidente en un commit público. ¿Cuál debe ser el primer paso de respuesta respecto a la credencial?",choices:["Solo eliminar el archivo en un commit nuevo","Revocar o rotar la credencial expuesta","Renombrar la rama que lo contiene","Agregar el archivo del token a .gitignore y detenerse"],explanations:["Las copias históricas y la exposición existente permanecen después de una eliminación habitual.","Revocar o rotar impide que la credencial expuesta siga siendo útil para acceder.","Renombrar no invalida el token.","Las reglas de exclusión no invalidan credenciales ni borran commits anteriores."],concept:"Credenciales expuestas",hints:["¿Podría alguien haber copiado ya el valor?","¿Qué impide que ese valor autorice solicitudes?"]},
    "ghf-203": {prompt:"Una persona crea un token de acceso personal con permisos amplios. ¿Puede darle poderes de propietario de organización que no posee?",choices:["Sí; conceder un alcance de administración de organización también promueve al propietario","Sí; las credenciales API están exentas de los permisos de repositorio del usuario","No; un token no puede superar el acceso de su propietario","Sí; omitir el vencimiento concede autoridad administrativa"],explanations:["Un alcance no promueve la identidad subyacente a propietaria de organización.","Las credenciales API no omiten los límites de autorización de su propietario.","Un token está limitado por el acceso de su propietario y por sus permisos concedidos.","El vencimiento afecta la duración de la credencial, no eleva su autoridad."],concept:"Límites de autoridad de tokens",hints:["¿La autoridad de quién representa el token?","¿Puede una credencial conceder poderes que la identidad que la respalda no tiene?"]},
    "ghf-204": {prompt:"Una tarea de automatización compatible necesita lectura de un repositorio mediante un token de acceso personal de granularidad fina. ¿Qué configuración sigue el privilegio mínimo?",choices:["Todos los repositorios con todos los permisos","Administración de organización aunque no se use","Escritura en repositorios no relacionados","Solo el repositorio y los permisos de lectura necesarios"],explanations:["El acceso amplio excede la necesidad indicada.","La autoridad administrativa no usada aumenta el riesgo.","La escritura no relacionada es innecesaria.","Restringir el alcance de repositorios y los permisos limita la exposición potencial."],concept:"Alcance de tokens de granularidad fina",hints:["¿Cuál es el conjunto mínimo de recursos requerido?","¿Una tarea de solo lectura debe recibir escritura?"]},
    "ghf-205": {prompt:"Una empresa quiere un nivel predeterminado de permisos de repositorio para los miembros de la organización antes de concesiones adicionales. ¿Qué ajuste lo permite?",choices:["Permisos base de organización","Una concesión directa a un colaborador en un repositorio","Una entrada CODEOWNERS por cada ruta de código","Una cantidad de revisiones obligatorias en la rama predeterminada"],explanations:["Los permisos base definen el acceso predeterminado de los miembros a repositorios de la organización.","Una concesión específica no establece la base para toda la membresía.","Las entradas de propiedad dirigen revisiones; no conceden acceso predeterminado organizativo.","Los conteos de revisión controlan requisitos de integración, no acceso general predeterminado."],concept:"Permisos base de organización",hints:["¿Cuál es la base antes de las concesiones específicas a equipos o personas?","¿Qué alcance administra valores predeterminados de toda la membresía?"]},
    "ghf-206": {prompt:"Un equipo va a hacer público un repositorio confidencial. ¿Qué revisión aborda más directamente el riesgo de divulgar información sensible?",choices:["Revisar solo el README actual y asumir que lo demás está oculto","Revisar los archivos actuales y el historial conservado en busca de información sensible","Solo comprobar si las notificaciones están habilitadas","Solo confirmar que haya un pull request abierto"],explanations:["Otros archivos y revisiones anteriores también pueden divulgar información.","La visibilidad pública puede exponer contenido e historial; hay que evaluar el material sensible.","Las notificaciones no determinan lo que pueden ver lectores públicos.","La existencia de un pull request no demuestra seguridad de divulgación."],concept:"Riesgo al cambiar visibilidad",hints:["¿Qué podría examinar un nuevo lector público?","¿Eliminar un valor de la revisión más reciente borra su pasado?"]},
    "ghf-207": {prompt:"Un repositorio tiene propietarios de código configurados, pero una persona propuesta como propietaria solo tiene Read. ¿Qué debe corregirse para que funcione como propietaria de código?",choices:["Solo necesita suscribirse a todos los pull requests","Read basta si su nombre aparece en CODEOWNERS","Necesita el permiso de escritura requerido en el repositorio","Mover la regla a docs/ elimina el requisito de acceso"],explanations:["Las suscripciones no conceden elegibilidad de propietario de código.","Una entrada de propiedad no concede el permiso requerido.","Los propietarios de código deben tener escritura en el repositorio.","Cambiar la ubicación compatible no exime del requisito de acceso."],concept:"Requisito de acceso de propietarios de código",hints:["¿Asignar responsabilidad reemplaza los requisitos de acceso?","Comprueba el permiso mínimo documentado para propietarios."]},
    "ghf-208": {prompt:"Una organización usa una biblioteca de código abierto y quiere ayudar económicamente a sus mantenedores elegibles mediante GitHub. ¿Qué función debe considerar?",choices:["Un tema de repositorio","Un revisor obligatorio","Una regla de rama","GitHub Sponsors"],explanations:["Los temas ayudan a descubrir; no transfieren apoyo económico.","Las solicitudes de revisión piden comentarios sobre cambios.","Las reglas de ramas imponen flujos del repositorio.","Sponsors facilita apoyo económico a personas y organizaciones elegibles de código abierto."],concept:"GitHub Sponsors",hints:["¿La contribución deseada es dinero o código?","¿Qué servicio apoya la sostenibilidad de quienes mantienen proyectos?"]},
    "ghf-209": {prompt:"Una persona de diseño quiere contribuir a un proyecto de código abierto, pero no programa. ¿Qué contribución sigue siendo valiosa?",choices:["Mejorar la documentación de usabilidad y reportar pasos claros de reproducción","Solo aumentar las estrellas cuenta como contribución","Las contribuciones deben ser archivos de código compilado","Solo los propietarios pueden reportar problemas de usuarios"],explanations:["La documentación, los comentarios de diseño y los problemas bien descritos pueden impulsar el trabajo de código abierto.","Las estrellas expresan interés, pero la participación útil va mucho más allá.","Las contribuciones no se limitan a código compilado.","Los usuarios pueden reportar problemas por los canales admitidos del proyecto."],concept:"Contribuciones sin código",hints:["¿Qué ayuda a usuarios y mantenedores además de implementar?","Considera toda la experiencia del proyecto."]},
    "ghf-210": {prompt:"Una persona nueva busca su primera contribución. ¿Qué señal es más útil para encontrar trabajo que el proyecto pretende que sea accesible a principiantes?",choices:["El issue con más comentarios sin importar el tema","Un issue con la etiqueta good first issue, considerando también su contexto y las pautas","El pull request pendiente más antiguo sin importar el alcance","El repositorio con más estrellas sin importar la dificultad"],explanations:["Muchos comentarios pueden indicar complejidad, no aptitud para principiantes.","Quienes mantienen usan good first issue para destacar trabajo accesible, aunque el contexto importa.","La antigüedad por sí sola no vuelve sencillo el trabajo.","La popularidad no indica si una tarea individual es adecuada."],concept:"Búsqueda de trabajo para principiantes",hints:["¿Qué señal explícita podrían dar quienes mantienen el proyecto?","¿Es útil una etiqueta sin leer la tarea real?"]},
    "ghf-211": {prompt:"Antes de iniciar una contribución importante a un proyecto desconocido, ¿qué debe hacerse?",choices:["Asumir que el flujo habitual propio prevalece sobre las convenciones del proyecto","Cambiar la licencia sin conversar","Leer las pautas y conversar sobre el alcance cuando corresponda","Exigir escritura directa antes de investigar"],explanations:["Los proyectos pueden tener distintos requisitos y convenciones.","Los cambios de licencia requieren autorización cuidadosa; no son una suposición inicial.","Entender expectativas y coordinar el alcance mejora la probabilidad de una contribución útil.","Las contribuciones externas suelen usar forks y pull requests sin escritura directa."],concept:"Respeto de procesos de contribución",hints:["¿Cómo evitar trabajo repetido innecesario?","¿De quién son las convenciones que rigen el proyecto receptor?"]},
    "ghf-212": {prompt:"Una persona no tiene escritura en un proyecto público original, pero quiere proponer un cambio de código. ¿Qué flujo es adecuado?",choices:["Editar un ZIP local y asumir que se actualiza el original","Marcar con estrella para obtener push","Crear una copia de plantilla y asumir que ya está vinculada para contribuir","Crear un fork, registrar cambios en una rama y abrir un pull request al original"],explanations:["Las ediciones de un ZIP no se envían automáticamente al original.","Las estrellas no conceden escritura.","Una plantilla crea un proyecto independiente, no la relación habitual de fork.","Los cambios basados en forks pueden proponerse al original mediante pull requests."],concept:"Contribuciones mediante forks",hints:["¿Dónde puede la persona hacer push de su trabajo?","¿Cómo se pide al proyecto original que lo revise?"]},
    "ghf-213": {prompt:"Un fork quedó atrasado respecto al proyecto original. ¿Qué debe hacer quien lo mantiene antes de trabajar sobre los cambios más recientes del original?",choices:["Sincronizar el fork con los cambios del original","Crear una rama local desde la rama predeterminada antigua sin cambios","Volver a hacer push de la rama sin recuperar commits del original","Descargar un ZIP del original y asumir que cambió el historial alojado del fork"],explanations:["Sincronizar incorpora los cambios actuales del original al historial del fork.","Crear una rama desde historial antiguo no recupera cambios faltantes.","Publicar el mismo historial no incorpora trabajo del original.","Descargar un archivo comprimido no actualiza el historial de un fork alojado."],concept:"Mantener actualizado un fork",hints:["¿Qué repositorio es la fuente del trabajo más reciente?","¿Qué operación vuelve a alinear los historiales?"]},
    "ghf-214": {prompt:"Una persona detecta instrucciones de configuración obsoletas en una plantilla comunitaria y quiere que futuros proyectos generados reciban instrucciones corregidas. ¿Dónde debe proponer el arreglo compartido?",choices:["Solo en el README de un proyecto ya generado","En un pull request al propio repositorio de la plantilla","Solo en una copia local no compartida","Solo renombrando su repositorio generado"],explanations:["Cambiar un proyecto generado no actualiza la plantilla para futuros usuarios.","Actualizar la plantilla original mejora los archivos iniciales de futuros proyectos generados.","Una edición no compartida no mejora la plantilla comunitaria.","El nombre de un repositorio generado no cambia el contenido de la plantilla."],concept:"Contribución a plantillas compartidas",hints:["¿Qué repositorio proporciona el contenido inicial futuro?","¿Editar un proyecto generado actualiza el patrón de origen?"]},
    "ghf-215": {prompt:"Una empresa anima a sus equipos a descubrir y contribuir a los proyectos empresariales privados de otros equipos mediante pull requests y prácticas compartidas de mantenimiento. ¿Cómo se llama este enfoque?",choices:["Dedicación al dominio público","Archivado de repositorios","InnerSource","Duplicación anónima"],explanations:["La dedicación al dominio público trata de derechos legales, no de colaboración interna.","Archivar vuelve inactivos los proyectos.","InnerSource aplica colaboración al estilo del código abierto dentro de una organización o empresa.","Duplicar copia contenido, pero no describe esta cultura de contribución."],concept:"InnerSource",hints:["¿Dónde se aplican las prácticas del código abierto?","¿Colaborar requiere hacer público el código?"]},
    "ghf-216": {prompt:"Un servicio interno reutilizable no sensible es difícil de encontrar para otros equipos de la empresa. ¿Qué cambio apoya más directamente el descubrimiento InnerSource sin hacerlo público?",choices:["Mantenerlo inaccesible para otros y depender del boca a boca","Publicar solo el nombre sin acceso ni documentación","Mover la documentación a un repositorio personal no divulgado","Usar visibilidad interna adecuada, temas útiles y documentación clara"],explanations:["El código inaccesible y el descubrimiento informal dificultan la reutilización entre equipos.","Un nombre solo no permite examinar y entender el servicio.","La documentación personal no divulgada dificulta descubrirlo de forma compartida.","La visibilidad adecuada y documentación fácil de encontrar ayudan a equipos autorizados a descubrir y reutilizar trabajo."],concept:"InnerSource fácil de descubrir",hints:["¿Los empleados pueden encontrar y entender el proyecto?","Separa ampliar el descubrimiento interno de publicar al público."]},
    "ghf-217": {prompt:"Una persona quiere ver la actividad pública de alguien que mantiene proyectos en su experiencia de actividad de GitHub. ¿Qué acción es pertinente?",choices:["Seguir la cuenta de esa persona","Suscribirse a un issue como sustituto de seguirla","Clonar un repositorio como sustituto de seguirla","Fijar su propio repositorio y asumir que se suscribe a esa persona"],explanations:["Seguir personas ayuda a conocer su actividad pública.","Suscribirse a un issue se limita a esa conversación, no a la actividad más amplia de una persona.","Clonar copia historial sin seguir una cuenta.","Fijar un repositorio personaliza un perfil; no sigue a otra persona."],concept:"Seguir personas",hints:["¿El interés está en un hilo o en la actividad más amplia de alguien?","¿Qué relación permite mantenerse informado sin elevar acceso?"]},
    "ghf-218": {prompt:"Una persona sigue a una organización en GitHub. ¿Qué debe esperar?",choices:["Membresía en todos sus equipos privados","Una forma de seguir la actividad pública, no acceso a repositorios privados","Escritura en todos los repositorios de la organización","Una copia de todos sus repositorios en su computadora"],explanations:["Seguir no es pertenecer a un equipo.","Seguir ayuda a mostrar actividad pública sin conceder acceso privado.","La escritura requiere una concesión separada.","Seguir no clona repositorios."],concept:"Seguir organizaciones",hints:["¿El interés implica membresía?","Separa el descubrimiento de actividad de la autorización."]},
    "ghf-219": {prompt:"Un equipo quiere un catálogo de integraciones y automatizaciones reutilizables que amplíen los flujos de GitHub. ¿Qué destino está diseñado para eso?",choices:["Solo el historial de ejecuciones de un repositorio","Solo el selector de plantillas de issues de un proyecto","GitHub Marketplace","Solo el formulario personal de creación de repositorios"],explanations:["El historial registra ejecuciones, no un catálogo de herramientas.","Las plantillas guían la recepción de trabajo, no enumeran integraciones.","Marketplace ayuda a descubrir aplicaciones y Actions.","Las opciones de creación de repositorios no proporcionan el catálogo de integraciones."],concept:"GitHub Marketplace",hints:["¿Se busca un catálogo de herramientas?","¿Qué destino incluye integraciones y componentes de automatización?"]},
    "ghf-220": {prompt:"Un equipo encuentra una aplicación atractiva de terceros en GitHub Marketplace. ¿Qué debe evaluar antes de instalarla en repositorios de trabajo?",choices:["Solo si tiene capturas atractivas","Solo si la usa otro equipo, ignorando el acceso solicitado","Solo si tiene opción gratuita, ignorando editor y permisos","Los permisos solicitados, el editor y la adecuación a las necesidades de la organización"],explanations:["Las capturas por sí solas no establecen confianza ni adecuación.","El uso por otro equipo no reemplaza evaluar el acceso para esta organización.","El precio solo no evalúa riesgos de acceso ni adecuación.","Instalar aplicaciones puede conceder acceso; hay que evaluar permisos y confianza en el proveedor."],concept:"Evaluación de integraciones de Marketplace",hints:["¿Qué autoridad podría conceder instalarla?","¿Poder encontrarla demuestra por sí solo que sea adecuada?"]},
    "ghf-221": {prompt:"Un repositorio público contiene código útil, pero no tiene licencia. ¿Qué no debe asumir quien quiera usarlo?",choices:["Que la visibilidad pública por sí sola concede permiso amplio de reutilización y redistribución","Que el código fuente se puede leer en GitHub","Que el repositorio puede tener issues","Que sus archivos pueden tener historial de commits"],explanations:["La visibilidad pública no sustituye una licencia que conceda derechos de reutilización.","El código público normalmente se puede leer, sujeto a disponibilidad de acceso.","Los repositorios públicos pueden usar issues.","Los archivos Git pueden conservar historial independientemente de la licencia."],concept:"Visibilidad abierta frente a derechos de código abierto",hints:["¿Ver código establece términos legales de reutilización?","Separa la accesibilidad técnica de las licencias."]},
    "ghf-222": {prompt:"¿Qué beneficio realista ofrece participar en un proyecto de código abierto mediante GitHub?",choices:["Aceptación garantizada de todos los cambios propuestos","Aprender de las revisiones y colaborar con personas ajenas al equipo propio","Propiedad automática de todas las dependencias","Eliminar la necesidad de cumplir licencias"],explanations:["Quienes mantienen aún deciden si los cambios encajan en el proyecto.","Contribuir puede desarrollar habilidades y relaciones mediante trabajo compartido y comentarios.","Participar no transfiere la propiedad de dependencias.","Las obligaciones de licencia siguen vigentes."],concept:"Beneficios de participar en código abierto",hints:["¿Qué resultados dependen del aprendizaje compartido y no de garantías?","Distingue una oportunidad de un derecho adquirido."]},
    "ghf-223": {prompt:"Un proyecto de código abierto quiere que se entienda el comportamiento esperado y cómo se maneja la conducta inaceptable. ¿Qué documento está previsto?",choices:["Un archivo de bloqueo de dependencias","Una lista de etiquetas de versiones","Un código de conducta","Solo una convención de nombres de ramas"],explanations:["Los archivos de bloqueo registran la resolución de dependencias.","Las etiquetas identifican versiones.","Un código de conducta establece expectativas de comportamiento y pautas para reportar.","Los nombres de ramas no definen conducta comunitaria ni procesos de reporte."],concept:"Conducta comunitaria",hints:["¿La política trata del comportamiento de personas o de versiones de archivos?","¿Qué ayuda a crear un entorno respetuoso de participación?"]},
    "ghf-224": {prompt:"Una organización de código abierto elegible quiere recibir apoyo económico mediante GitHub Sponsors. ¿Qué afirmación sobre los tipos de cuentas receptoras es correcta?",choices:["Solo pueden recibir personas; las organizaciones solo patrocinan","Las organizaciones solo califican si convierten sus repositorios en personales","Solo pueden recibir apoyo compartiendo el inicio de sesión personal de un mantenedor","Tanto organizaciones como personas elegibles pueden recibir patrocinios"],explanations:["Las organizaciones elegibles pueden ser receptoras y patrocinadoras.","Recibir patrocinios no exige convertir repositorios de organización en personales.","Las credenciales personales compartidas no son el modelo de patrocinio organizativo.","GitHub Sponsors admite personas y organizaciones elegibles."],concept:"Receptores de patrocinios",hints:["¿El mantenimiento puede organizarse colectivamente?","Separa los requisitos de elegibilidad de las suposiciones sobre tipos de cuenta."]},
    "ghf-225": {prompt:"Una persona quiere descubrir repositorios públicos sobre datos climáticos de distintos propietarios. ¿Qué enfoque es el más útil?",choices:["Buscar temas pertinentes de repositorios y explorar los proyectos coincidentes","Examinar solo sus remotos locales","Buscar solo archivos de un repositorio ya clonado","Examinar solo los issues que tiene asignados en un proyecto"],explanations:["Los temas y la búsqueda de repositorios permiten descubrir proyectos por asunto.","Los remotos locales solo describen repositorios ya configurados localmente.","Un repositorio local no proporciona descubrimiento amplio de proyectos.","Los issues asignados son un subconjunto personal acotado, no descubrimiento entre propietarios."],concept:"Descubrimiento de proyectos por temas",hints:["¿Dónde se comparten metadatos de asuntos entre repositorios?","Distingue descubrir proyectos de organizar trabajo ya conocido."]}
  },
  "pt-BR": {
    "ghf-001": {prompt:"Uma equipe de políticas precisa explicar como um documento mudou ao longo de vários meses. O que o controle de versão oferece?",choices:["Um histórico registrado das alterações","A garantia de que todas as alterações estão corretas","Aprovação jurídica automática","Um substituto para a revisão de documentos"],explanations:["O controle de versão registra alterações que podem ser examinadas ao longo do tempo.","Registrar uma alteração não valida sua correção.","A aprovação jurídica exige um processo separado.","A revisão continua necessária mesmo com um histórico registrado."],concept:"Finalidade do controle de versão",hints:["Que evidências explicariam as edições anteriores?","Diferencie registrar o trabalho de aprová-lo."]},
    "ghf-002": {prompt:"Qual afirmação distingue corretamente o Git do GitHub?",choices:["O Git precisa do GitHub para armazenar commits","O Git controla versões; o GitHub hospeda repositórios e viabiliza a colaboração","O GitHub é a área de preparação local","O Git é apenas uma interface gráfica para o GitHub"],explanations:["O Git pode gerenciar repositórios sem o GitHub.","O Git é um software de controle de versão; o GitHub acrescenta hospedagem e colaboração.","A área de preparação pertence a um repositório Git local.","O Git tem suas próprias ferramentas de linha de comando e seu próprio modelo de dados."],concept:"Git versus GitHub",hints:["Qual componente pode funcionar offline?","Separe o acompanhamento de versões da colaboração em uma plataforma de hospedagem."]},
    "ghf-003": {prompt:"Uma pessoa desenvolvedora quer ter os arquivos do projeto e o histórico do Git em um notebook. Qual operação deve usar?",choices:["Marcar o repositório com uma estrela","Baixar um ZIP do código-fonte","Clonar o repositório","Acompanhar o repositório com Watch"],explanations:["Marcar com uma estrela salva o repositório como favorito sem copiar seu histórico.","Um ZIP do código-fonte não inclui o histórico do repositório Git.","Clonar cria um repositório local com o histórico do Git.","Watch configura notificações em vez de criar uma cópia local."],concept:"Clonagem",hints:["O resultado precisa de metadados de versões?","Compare um arquivo compactado com um repositório de trabalho."]},
    "ghf-004": {prompt:"Uma pessoa editou vários arquivos rastreados, mas quer incluir apenas dois no próximo commit. O que deve fazer primeiro?",choices:["Fazer push diretamente da árvore de trabalho","Incluir todas as modificações rastreadas em um commit sem selecioná-las","Fazer fetch do remoto","Preparar as alterações selecionadas"],explanations:["Push transfere commits existentes em vez de selecionar edições da árvore de trabalho.","Incluir todas as modificações incorporaria os arquivos indesejados.","Fetch atualiza as informações de acompanhamento do remoto, não o índice.","A preparação seleciona o conteúdo do próximo commit."],concept:"Área de preparação",hints:["Como o próximo snapshot é montado?","Qual ação ocorre antes de registrar um commit?"]},
    "ghf-005": {prompt:"Qual é a melhor maneira de entender um commit do Git?",choices:["Um snapshot registrado com metadados de identificação","Uma cópia em tempo real de todas as edições atuais ainda não commitadas","Uma solicitação para integrar alterações que ainda não as registrou","Uma conexão de rede que mantém duas pastas sincronizadas"],explanations:["Um commit registra um snapshot e metadados, como autoria e mensagem.","Edições ainda não commitadas não entram automaticamente no histórico registrado.","Um commit registra trabalho; um pull request propõe integrar trabalho já registrado.","Os commits persistem independentemente de uma conexão de rede."],concept:"Commits",hints:["O que permanece depois que o editor é fechado?","Pense em um ponto identificável no histórico."]},
    "ghf-006": {prompt:"Uma pessoa de design quer experimentar sem alterar a branch padrão. Qual conceito do Git permite isso?",choices:["Um marco","Uma branch separada","Um tópico do repositório","Um filtro de notificações"],explanations:["Marcos agrupam itens de trabalho em vez de isolar alterações em arquivos.","Uma branch oferece uma linha de trabalho separada.","Tópicos ajudam a descobrir repositórios.","Filtros de notificações selecionam mensagens, não versões."],concept:"Isolamento com branches",hints:["Onde pode existir uma linha de trabalho alternativa?","Separe o isolamento do trabalho do acompanhamento de tarefas."]},
    "ghf-007": {prompt:"Há um commit local em uma branch de funcionalidade, mas a equipe não consegue vê-lo no GitHub. Qual ação normalmente compartilha esse commit?",choices:["Preparar os arquivos dele novamente","Fazer fetch da branch remota","Fazer push da branch para o remoto","Criar outra branch local nesse commit"],explanations:["Preparar arquivos não transfere commits existentes.","Fetch recupera o histórico remoto em vez de publicar o histórico local.","Push envia commits locais para a branch remota.","Outra referência local não transmite o commit."],concept:"Push",hints:["Em qual direção o histórico precisa viajar?","O commit já está registrado localmente?"]},
    "ghf-008": {prompt:"Você quer recuperar alterações remotas para examiná-las sem integrá-las à branch atual. Qual operação atende a essa necessidade?",choices:["Commit","Push","Merge","Fetch"],explanations:["Commit registra alterações locais preparadas.","Push publica o histórico local.","Merge integra históricos em uma branch.","Fetch recupera o histórico remoto sem mesclá-lo à branch atual."],concept:"Fetch",hints:["Separe a recuperação da integração.","Qual ação mantém sua linha de trabalho atual inalterada?"]},
    "ghf-009": {prompt:"Como git pull difere de git fetch em um fluxo de trabalho comum com branches?",choices:["Pull recupera as alterações e depois as integra","Pull apenas envia commits locais","Pull cria uma conta no GitHub","Pull exclui o histórico remoto"],explanations:["Pull faz fetch e integra as alterações usando merge ou rebase, conforme a configuração.","Enviar commits locais é a função de push.","Criar uma conta não tem relação com Git pull.","Pull não exclui o histórico remoto."],concept:"Pull versus fetch",hints:["Qual operação vai além da recuperação?","Considere que o comportamento de integração é configurável."]},
    "ghf-010": {prompt:"Duas branches editam o mesmo trecho de formas diferentes e o Git não consegue combiná-las automaticamente. O que é necessário?",choices:["Outro fetch sem alterar nenhum dos trechos","Resolver um conflito de mesclagem","Apenas uma nova mensagem de commit para o conflito inalterado","Renomear a branch de origem"],explanations:["Recuperar os mesmos históricos novamente não concilia suas edições.","Uma pessoa precisa conciliar as alterações conflitantes antes que a mesclagem possa terminar.","Alterar apenas a mensagem deixa o conteúdo incompatível sem resolução.","Renomear uma branch não concilia seu conteúdo."],concept:"Conflitos de mesclagem",hints:["O software consegue deduzir a redação pretendida?","Concentre-se nas edições incompatíveis, não nos metadados da branch."]},
    "ghf-011": {prompt:"Uma equipe quer desfazer uma alteração publicada preservando um histórico compartilhado auditável. Qual abordagem é mais adequada?",choices:["Redefinir a branch compartilhada para um commit anterior e fazer force-push","Excluir a branch local que contém a alteração","Criar um commit de reversão","Adicionar os arquivos alterados ao .gitignore"],explanations:["Redefinir a branch e fazer force-push reescreve o histórico compartilhado em vez de registrar uma reversão.","Excluir uma branch local não reverte alterações já integradas remotamente.","Revert registra um novo commit que reverte alterações anteriores.","Regras de exclusão não desfazem alterações rastreadas e já commitadas."],concept:"Reversão de alterações compartilhadas",hints:["O histórico compartilhado existente precisa permanecer intacto?","Considere registrar a reversão como um novo trabalho."]},
    "ghf-012": {prompt:"Qual mensagem descreve melhor um commit isolado que corrige um link quebrado na documentação?",choices:["Alterações","Atualizar coisas","Versão final","Corrigir o link do guia de instalação para as instruções de configuração"],explanations:["Alterações não oferece uma descrição útil da intenção.","Atualizar coisas não identifica o comportamento afetado.","Versão final não explica o que mudou.","A mensagem identifica tanto o material afetado quanto a correção."],concept:"Mensagens de commit descritivas",hints:["O que ajudaria quem mantiver o projeto no futuro?","Prefira uma alteração concreta a um status vago."]},
    "ghf-013": {prompt:"Por que manter uma reformulação de interface e uma correção ortográfica não relacionadas em branches separadas?",choices:["Elas podem ser revisadas e entregues de forma independente","O Git proíbe vários arquivos em uma branch","Cada branch precisa ter sua própria organização","Branches separadas eliminam a necessidade de testes"],explanations:["Branches independentes reduzem o acoplamento entre trabalhos não relacionados.","Branches podem conter alterações em muitos arquivos.","Branches pertencem a um repositório, não a organizações separadas.","Os testes continuam necessários em branches separadas."],concept:"Branches com foco definido",hints:["E se uma das alterações atrasar?","Considere o escopo de quem revisa."]},
    "ghf-014": {prompt:"No GitHub flow, quando o trabalho de uma branch de funcionalidade deve passar a fazer parte da branch padrão?",choices:["Assim que a branch recebe um nome","Quando seu pull request é mesclado após as verificações e a revisão exigidas","Quando a pessoa autora marca o repositório com uma estrela","Sempre que alguém da equipe clona o repositório"],explanations:["Dar um nome à branch não integra seu conteúdo.","A mesclagem integra o trabalho, sujeita aos requisitos do repositório.","Estrelas não mesclam alterações.","Clonar copia o histórico sem modificar a branch de origem."],concept:"Integração no GitHub flow",hints:["Qual ação integra a alteração proposta?","Quais proteções podem bloquear essa ação?"]},
    "ghf-015": {prompt:"Uma pessoa faz push de outro commit para a mesma branch de origem de um pull request aberto. O que acontece?",choices:["O pull request precisa ser recriado para incluí-lo","O novo commit é mesclado automaticamente à base","O pull request inclui o novo commit","O novo commit fica excluído até que o título mude"],explanations:["O pull request existente acompanha sua branch de origem.","Atualizar a proposta não a integra automaticamente.","Novos commits na branch de origem atualizam a proposta existente.","Não é necessário mudar o título para incluir novos commits da branch de origem."],concept:"Iteração em um pull request",hints:["A proposta acompanha um ZIP congelado?","Pense na relação com a branch."]},
    "ghf-016": {prompt:"Após mesclar uma funcionalidade, por que a equipe pode excluir a branch de funcionalidade?",choices:["Para apagar a conversa do pull request","Para excluir automaticamente todas as cópias locais dessa branch","Para remover as alterações mescladas da branch padrão","Para indicar a conclusão e reduzir o acúmulo de branches obsoletas"],explanations:["A conversa do pull request continua disponível.","Excluir uma branch remota não remove automaticamente a branch local de todas as pessoas.","As alterações mescladas permanecem na branch de destino.","Remover a branch concluída ajuda a evitar sua reutilização acidental."],concept:"Limpeza de branches",hints:["O que a mesclagem já preservou?","Diferencie uma referência de branch do conteúdo mesclado."]},
    "ghf-017": {prompt:"Um repositório tem um remoto local chamado origin. O que é origin?",choices:["Um alias convencional para a URL de um repositório remoto","Uma branch protegida exigida pelo Git","Uma função de organização do GitHub","Uma licença aplicada automaticamente ao código"],explanations:["Origin é um nome comum de remoto, não um tipo obrigatório de servidor.","Nomes de remotos e nomes de branches são conceitos diferentes.","Não é uma função de acesso.","Aliases de remotos não determinam o licenciamento."],concept:"Nomes de remotos",hints:["O que git remote descreve?","Esse nome é um alias de localização ou uma versão?"]},
    "ghf-018": {prompt:"Qual propriedade torna o Git um sistema distribuído de controle de versão?",choices:["Toda edição exige uma conexão com a internet","Repositórios locais podem conter histórico e permitir commits locais","Somente um servidor central pode registrar alterações","Cada arquivo precisa pertencer a uma pessoa diferente"],explanations:["Operações locais do Git podem funcionar offline.","Repositórios Git permitem histórico e commits sem contatar o GitHub.","O Git não reserva a criação de commits a um único servidor central.","A propriedade de arquivos não tem relação com o controle de versão distribuído."],concept:"Controle de versão distribuído",hints:["Onde o histórico pode ser registrado?","O trabalho local pararia se o GitHub estivesse inacessível?"]},
    "ghf-019": {prompt:"Qual comando informa quais arquivos foram modificados e se as alterações estão preparadas?",choices:["git push","git clone","git status","git remote add"],explanations:["Push transfere commits.","Clone cria uma cópia de um repositório.","Status resume o estado da árvore de trabalho e da área de preparação.","Remote add configura uma URL remota."],concept:"Estado da árvore de trabalho",hints:["Qual comando observa em vez de transferir?","Procure informações sobre a preparação de alterações."]},
    "ghf-020": {prompt:"Uma pessoa mantenedora quer examinar alterações linha a linha antes de fazer um commit. Qual comando foi projetado para essa comparação?",choices:["git init","git remote","git branch","git diff"],explanations:["Init cria os metadados do repositório.","Remote gerencia as localizações configuradas de repositórios.","Branch gerencia ou lista referências de branches.","Diff exibe diferenças entre versões ou estados de arquivos."],concept:"Inspeção de diferenças",hints:["Que saída revelaria linhas adicionadas e removidas?","Diferencie uma comparação de uma lista de branches."]},
    "ghf-021": {prompt:"Qual ação inicia o rastreamento do Git em uma pasta local existente que ainda não é um repositório?",choices:["Executar git init nessa pasta","Executar git fetch antes de criar qualquer metadado de repositório","Criar um arquivo .gitignore sem inicializar o Git","Apenas renomear a pasta para corresponder a um repositório do GitHub"],explanations:["Git init cria os metadados do repositório Git local.","Fetch opera em um repositório existente em vez de inicializar essa pasta.","Um arquivo de exclusão sozinho não cria um repositório.","O nome da pasta não inicializa o controle de versão."],concept:"Inicialização de repositórios",hints:["Essa ação precisa contatar o GitHub?","Qual ação cria os metadados locais de controle de versão?"]},
    "ghf-022": {prompt:"O que é a árvore de trabalho em um repositório Git local?",choices:["Apenas as alterações selecionadas no índice","Os arquivos obtidos por checkout nos quais se está trabalhando","Apenas as referências de branches de acompanhamento remoto","Todo o grafo de commits sem arquivos obtidos por checkout"],explanations:["O índice armazena o conteúdo selecionado para o próximo commit, não toda a árvore de trabalho.","A árvore de trabalho contém os arquivos obtidos por checkout para edição.","Referências de acompanhamento remoto identificam posições remotas recuperadas, não arquivos editáveis.","O histórico registrado é distinto dos arquivos atuais obtidos por checkout."],concept:"Árvore de trabalho",hints:["Onde ocorrem as edições comuns de arquivos?","Separe os arquivos editáveis do índice e do histórico registrado."]},
    "ghf-023": {prompt:"Uma equipe quer uma referência reconhecível ao commit usado em uma versão publicada. Qual recurso do Git atende a essa necessidade?",choices:["Uma pessoa responsável","Uma reação","Uma tag","Uma resposta salva"],explanations:["Pessoas responsáveis identificam a responsabilidade por itens de trabalho.","Reações comunicam feedback.","Uma tag marca um ponto específico no histórico do repositório.","Respostas salvas reutilizam texto de comentários."],concept:"Tags",hints:["O que identifica uma versão histórica?","Separe os marcadores de versão dos metadados de colaboração."]},
    "ghf-024": {prompt:"Uma pessoa tem um identificador de commit e quer examinar exatamente essa alteração depois. Por que o identificador é útil?",choices:["Ele sempre aponta para o estado mais recente da branch padrão","Ele se refere a todos os commits da mesma pessoa","Ele muda sempre que outra branch avança","Ele identifica um commit específico"],explanations:["Um identificador de commit específico não se move com a branch padrão.","Commits diferentes da mesma pessoa têm identidades distintas.","O avanço de outra branch não altera o identificador de um commit existente.","O identificador permite referenciar uma revisão registrada específica."],concept:"Identificadores de commits",hints:["Trata-se de uma revisão fixa ou de uma branch que se move?","Pense em localizar um ponto preciso no histórico."]},
    "ghf-025": {prompt:"Qual é o principal uso da branch padrão de um repositório?",choices:["A base habitual para novos pull requests e para navegar no repositório","Uma referência fixa para a versão publicada mais recente","Uma branch pessoal de experimentação exclusiva de cada visitante","Uma branch que sempre rejeita commits, independentemente das configurações"],explanations:["A branch padrão é a visualização inicial e a base habitual de pull requests.","A branch padrão pode avançar independentemente das versões publicadas.","A branch padrão é uma configuração do repositório, não uma branch de experimentação por visitante.","Ser a branch padrão não impõe por si só uma regra de proibição de commits."],concept:"Branch padrão",hints:["Qual versão as pessoas normalmente veem primeiro?","Considere o destino inicial de uma alteração proposta."]}
    ,"ghf-026": {prompt:"Uma pessoa que começa a contribuir confunde clonar com criar um fork. Qual distinção está correta?",choices:["Clonar concede acesso de escrita ao repositório original; criar um fork concede apenas leitura","Criar um fork gera um repositório relacionado no GitHub; clonar cria uma cópia local","Criar um fork remove o histórico; clonar mantém apenas os arquivos mais recentes","Clonar cria automaticamente um fork na conta da pessoa"],explanations:["Nenhuma operação concede acesso direto de escrita ao repositório original.","Um fork é um repositório hospedado separado e relacionado; um clone é local.","Forks mantêm o histórico original, e clones comuns incluem o histórico do Git.","Um clone não cria automaticamente um fork hospedado."],concept:"Clone versus fork",hints:["Onde fica cada cópia resultante?","Um namespace hospedado separado faz diferença?"]},
    "ghf-027": {prompt:"Um notebook está offline. Qual atividade normalmente ainda pode ser realizada em um repositório Git local existente?",choices:["Fazer fetch de novos commits do GitHub","Ler issues recém-publicadas no GitHub","Criar um commit local","Fazer push de uma branch para o GitHub"],explanations:["Fazer fetch do GitHub exige acesso à rede.","Novas issues hospedadas não podem ser recuperadas offline.","Commits locais não exigem contato com o GitHub.","Fazer push para o GitHub exige uma conexão de rede."],concept:"Git offline",hints:["Qual operação usa somente dados locais?","Separe as operações do Git da comunicação com o servidor."]},
    "ghf-028": {prompt:"Qual é o principal efeito de mesclar uma branch em outra?",choices:["Apenas baixa alterações sem integrá-las","Troca a branch em checkout sem combinar nenhum trabalho","Sempre descarta todas as alterações exclusivas do destino","Integra as alterações da branch de origem"],explanations:["Recuperar sem integrar descreve fetch.","Trocar de branch seleciona trabalho em vez de mesclá-lo.","Merge combina históricos e não descarta, por natureza, todo o trabalho exclusivo do destino.","Merge combina as linhas de desenvolvimento pertinentes."],concept:"Mesclagem",hints:["Que parte do projeto é combinada?","Separe a recuperação e o checkout da integração."]},
    "ghf-029": {prompt:"Qual tipo de conta do GitHub foi projetado para representar a identidade de uma pessoa?",choices:["Uma conta pessoal","Uma conta de organização usada como login compartilhado","Uma branch de repositório","Uma política empresarial"],explanations:["Uma conta pessoal representa uma pessoa usuária.","Organizações são gerenciadas pelas identidades pessoais de seus membros, não por um login compartilhado da organização.","Uma branch é uma referência de controle de versão.","Políticas são configurações, não identidades individuais."],concept:"Contas pessoais",hints:["Como a atividade individual é atribuída?","Separe uma pessoa de um contêiner de propriedade compartilhada."]},
    "ghf-030": {prompt:"Uma empresa quer propriedade compartilhada de repositórios com equipes e permissões de membros. Qual estrutura é adequada?",choices:["Um gist de um único funcionário","Uma organização do GitHub","Uma tag de commit","Uma lista de tarefas em Markdown"],explanations:["Um gist pessoal não é uma estrutura organizacional de propriedade e equipes.","Organizações permitem propriedade compartilhada e colaboração gerenciada.","Uma tag identifica uma versão.","Uma lista de tarefas não pode administrar o acesso a repositórios."],concept:"Organizações",hints:["Quem deve ser proprietário dos repositórios além de um único funcionário?","Qual estrutura oferece suporte a equipes?"]},
    "ghf-031": {prompt:"O que uma conta empresarial ajuda uma empresa a gerenciar em várias organizações do GitHub?",choices:["Um único histórico do Git combinado para todos os repositórios","Um login compartilhado por todos os funcionários","Políticas compartilhadas e administração centralizada","A mesclagem automática das branches padrão de todas as organizações"],explanations:["Os repositórios mantêm seus próprios históricos em vez de se tornarem um único repositório Git.","Uma conta empresarial não substitui identidades de usuários com atribuição individual.","Contas empresariais fornecem uma camada administrativa para várias organizações.","O agrupamento empresarial não combina automaticamente branches de repositórios."],concept:"Contas empresariais",hints:["Qual camada fica acima das organizações individuais?","Pense na governança entre organizações."]},
    "ghf-032": {prompt:"Qual modelo de implantação corresponde ao GitHub Enterprise Server?",choices:["Apenas uma conta pessoal do GitHub.com com uma cota maior","Apenas uma organização operada pelo GitHub no GitHub.com","Um cliente Git local sem servidor de colaboração","Uma instância do GitHub operada em infraestrutura que você controla"],explanations:["Enterprise Server é uma implantação separada, não uma cota pessoal maior.","Isso descreve uma organização hospedada, não o modelo de implantação do Server.","Enterprise Server fornece um serviço de colaboração, não apenas um cliente local.","Enterprise Server é auto-hospedado em infraestrutura controlada pelo cliente."],concept:"Cloud versus Server",hints:["Quem opera a infraestrutura de hospedagem?","Separe o modelo de implantação da identidade da conta."]},
    "ghf-033": {prompt:"Uma pessoa que contribui prefere operações locais do Git visuais em vez de digitar comandos. Qual ferramenta do GitHub é a mais adequada?",choices:["GitHub Desktop","GitHub Pages","GitHub Sponsors","GitHub Discussions"],explanations:["Desktop oferece uma interface gráfica para fluxos de trabalho com repositórios locais.","Pages publica sites.","Sponsors facilita o apoio financeiro.","Discussions hospeda conversas."],concept:"GitHub Desktop",hints:["A ferramenta gerencia arquivos no computador?","Procure um fluxo de trabalho gráfico do Git."]},
    "ghf-034": {prompt:"Durante um deslocamento, uma pessoa mantenedora quer um aplicativo feito para triar notificações do GitHub e responder a issues pelo celular. Qual ferramenta atende a essa necessidade?",choices:["GitHub Desktop","GitHub Mobile","GitHub CLI","O editor de código-fonte github.dev"],explanations:["Desktop foi projetado para fluxos de trabalho gráficos com repositórios em um computador.","Mobile permite colaborar no GitHub pelo celular.","CLI atende a fluxos de trabalho em terminal, não a um aplicativo de colaboração para celular.","Github.dev é um editor de código-fonte, não o aplicativo móvel de notificações pretendido."],concept:"GitHub Mobile",hints:["Qual dispositivo e quais atividades estão envolvidos?","Qual interface foi projetada para esse formato de dispositivo?"]},
    "ghf-035": {prompt:"Um script de shell precisa criar issues do GitHub usando um cliente de linha de comando compatível. Qual ferramenta é adequada?",choices:["GitHub Pages","Somente GitHub Desktop","GitHub CLI","Um renderizador de Markdown"],explanations:["Pages serve conteúdo de sites estáticos.","Desktop é gráfico, não um cliente do GitHub orientado ao shell.","GitHub CLI disponibiliza fluxos de trabalho do GitHub por comandos como gh issue.","Renderizar Markdown não cria issues hospedadas."],concept:"GitHub CLI",hints:["O fluxo de trabalho exige comandos em um shell?","É uma ação do serviço do GitHub ou apenas controle de versão local?"]},
    "ghf-036": {prompt:"Qual tarefa é um recurso de colaboração do GitHub, e não uma responsabilidade de um comando básico do Git?",choices:["Registrar um commit local","Criar uma branch","Comparar versões de arquivos","Solicitar revisão em um pull request hospedado"],explanations:["O Git registra commits diretamente.","O Git gerencia branches diretamente.","O Git pode comparar versões diretamente.","Solicitações de revisão hospedadas fazem parte da camada de colaboração do GitHub."],concept:"Camada de colaboração do GitHub",hints:["Qual atividade envolve participantes de uma revisão hospedada?","Separe a mecânica do repositório do fluxo de trabalho da plataforma."]},
    "ghf-037": {prompt:"Uma issue precisa de um título Markdown de primeiro nível. Qual texto usa a sintaxe adequada?",choices:["# Deployment notes","[Deployment notes]","@Deployment notes","`Deployment notes`"],explanations:["Uma cerquilha inicial seguida de espaço cria um título.","Colchetes sozinhos não criam um título.","A arroba é usada para menções em contextos apropriados.","Crases formatam código inline."],concept:"Títulos em Markdown",hints:["Qual sintaxe indica a hierarquia do documento?","Diferencie um título de um destaque dentro de uma linha."]},
    "ghf-038": {prompt:"Qual trecho Markdown exibe setup como código inline em uma frase?",choices:["**setup**","`setup`","[setup](https://example.com)","## setup"],explanations:["Asteriscos duplos produzem texto em negrito.","Crases marcam código inline.","Essa sintaxe cria um hiperlink.","Cerquilhas criam um título."],concept:"Formatação de código inline",hints:["Qual formatação é adequada para identificadores e comandos?","O texto deve permanecer dentro da frase."]},
    "ghf-039": {prompt:"Qual Markdown cria um link com o rótulo visível Guide?",choices:["(Guide)[https://docs.github.com]","<Guide>https://docs.github.com","[Guide](https://docs.github.com)","# Guide https://docs.github.com"],explanations:["Os delimitadores do rótulo e da URL estão invertidos.","Isso não usa a sintaxe de link com rótulo.","Colchetes contêm o rótulo e parênteses contêm o destino.","Isso cria um título, não o link com rótulo solicitado."],concept:"Links em Markdown",hints:["Onde ficam o rótulo e o destino?","Procure delimitadores pareados ao redor de cada parte."]},
    "ghf-040": {prompt:"Um relato de bug inclui um rastreamento de pilha com várias linhas. Qual formatação preserva melhor sua disposição de código?",choices:["Um parágrafo comum","Um parágrafo em negrito","Um único trecho de código inline para todo o rastreamento","Um bloco de código cercado por delimitadores"],explanations:["A renderização de parágrafos comuns não preserva a disposição do código como bloco.","Texto em negrito não oferece formatação de código com várias linhas.","Código inline destina-se a textos curtos em uma linha, não a um rastreamento com várias linhas.","Um bloco de código delimitado preserva a apresentação de código com várias linhas."],concept:"Blocos de código",hints:["O que preserva quebras de linha e recuo?","Escolha formatação em bloco, não inline."]},
    "ghf-041": {prompt:"Uma lista de verificação de versão precisa de uma tarefa desmarcada em Markdown. Qual sintaxe é adequada?",choices:["- [ ] Verify migration","[Verify migration](pending)","@Verify migration","# [Verify migration]"],explanations:["Um marcador de lista seguido de uma caixa vazia cria uma tarefa desmarcada.","Isso é sintaxe de link, não uma caixa de seleção.","A arroba não cria um item de tarefa.","Um título não cria uma caixa de tarefa interativa."],concept:"Listas de tarefas em Markdown",hints:["O que combina um item de lista e uma caixa de seleção?","A caixa já deve conter uma marca de conclusão?"]},
    "ghf-042": {prompt:"Um comentário deve notificar alguém da equipe chamado river sobre uma pergunta. Qual texto usa a sintaxe de menção do GitHub?",choices:["#river","@river","!river","`river`"],explanations:["A cerquilha não é o prefixo de menção de usuários.","A arroba seguida de um nome de usuário cria uma menção.","O ponto de exclamação não é sintaxe de menção de usuários.","A formatação de código inline não menciona um usuário."],concept:"Menções",hints:["Qual prefixo identifica uma pessoa em uma conversa?","Formatar um nome não é o mesmo que se dirigir a alguém."]},
    "ghf-043": {prompt:"Em uma issue de um repositório, uma pessoa escreve #84 para referenciar outra issue do mesmo repositório. O que o GitHub normalmente oferece?",choices:["O fechamento automático da issue 84 apenas pela referência","Uma duplicata da issue 84","Uma referência com link para essa issue","Uma referência ao commit 84 em vez da issue"],explanations:["Uma referência isolada não é um fluxo de fechamento de issues por palavras-chave.","Referenciar uma issue não a duplica.","O GitHub transforma automaticamente referências numéricas de issues em links em contextos de conversa compatíveis.","Nesse contexto, a forma cerquilha-número identifica uma issue ou um pull request."],concept:"Referências a issues",hints:["Isso permite navegar ou modifica algo?","Qual contexto fornece o nome do repositório?"]},
    "ghf-044": {prompt:"Uma pessoa revisora quer citar uma frase anterior antes de responder. Qual prefixo Markdown cria uma citação em bloco?",choices:["@","!","- [ ]",">"],explanations:["A arroba é usada para menções.","O ponto de exclamação participa da sintaxe de imagens, não de citações em bloco.","Isso cria uma tarefa desmarcada.","Um prefixo de maior que cria texto citado."],concept:"Citações em bloco",hints:["Como o material citado pode ser separado visualmente?","Escolha a sintaxe de citação, não de acompanhamento de tarefas."]},
    "ghf-045": {prompt:"Um README na raiz precisa de um link para docs/setup.md que acompanhe a branch sendo navegada. Qual é a melhor opção?",choices:["Um link relativo para docs/setup.md","Um link absoluto fixado no setup.md de um commit","Um link absoluto que sempre aponte para o setup.md de main","Um link para a página inicial do repositório em vez do arquivo"],explanations:["O GitHub resolve esse link relativo usando a branch sendo navegada.","Um link fixado em um commit permanece intencionalmente em uma revisão fixa.","Um link fixado em main não acompanha outras branches sendo navegadas.","A página inicial não aponta diretamente para o documento de configuração."],concept:"Links relativos de documentação",hints:["O destino deve acompanhar a branch atual?","Considere como a localização do repositório fornece contexto."]},
    "ghf-046": {prompt:"Qual trecho Markdown exibe a palavra urgent em negrito?",choices:["`urgent`","**urgent**","> urgent","[urgent]"],explanations:["Crases exibem código inline.","Asteriscos duplos aplicam negrito.","Um prefixo de maior que cria uma citação em bloco.","Colchetes sozinhos não aplicam negrito."],concept:"Ênfase de texto",hints:["Qual delimitador envolve o texto destacado?","Descarte a formatação de código e de citação."]},
    "ghf-047": {prompt:"Uma pessoa quer uma lista com marcadores de pré-requisitos sem indicar uma ordem de execução. Qual estrutura Markdown atende a essa necessidade?",choices:["Uma lista numerada","Um bloco de código delimitado","Uma lista não ordenada","Um título para cada palavra"],explanations:["Listas numeradas comunicam uma ordem.","Blocos de código apresentam conteúdo literal em formato de código.","Listas não ordenadas apresentam itens sem uma sequência numerada.","Títulos estabelecem seções em vez de uma lista compacta."],concept:"Listas não ordenadas",hints:["A sequência tem importância aqui?","Escolha uma estrutura de lista, não uma formatação de código."]},
    "ghf-048": {prompt:"Uma pessoa que contribui com a documentação adiciona texto alternativo a uma imagem Markdown. Qual é sua finalidade principal?",choices:["Especificar o caminho de armazenamento do arquivo da imagem","Fornecer apenas um título ao passar o mouse","Definir as dimensões de exibição da imagem","Fornecer uma descrição textual para acessibilidade"],explanations:["A URL ou o caminho da imagem é outra parte da sintaxe de imagens Markdown.","Texto alternativo não é apenas um campo de título ao passar o mouse.","Texto alternativo descreve o conteúdo em vez de especificar largura e altura.","Texto alternativo ajuda a transmitir o significado da imagem quando o conteúdo visual não pode ser percebido."],concept:"Descrições acessíveis de imagens",hints:["Quem pode não conseguir enxergar a imagem?","Separe o conteúdo descritivo do posicionamento da imagem."]},
    "ghf-049": {prompt:"Uma equipe escolhe GitHub flow para um manual sem código. Esse uso é adequado?",choices:["Sim; a revisão baseada em branches também se aplica à documentação","Não; somente programas compilados podem usar branches","Não; Markdown não pode ser commitado","Somente se cada documento se tornar uma issue"],explanations:["GitHub flow permite alterações colaborativas além do código de aplicações.","Branches não se limitam a linguagens compiladas.","Arquivos Markdown podem ser versionados normalmente.","Documentos podem continuar como arquivos enquanto issues acompanham o trabalho relacionado."],concept:"GitHub flow além do código",hints:["O controle de versão depende de compilação?","Que tipos de arquivos se beneficiam de revisão?"]},
    "ghf-050": {prompt:"Antes de abrir um pull request de uma branch, o que a pessoa autora deve incluir para ajudar na compreensão da proposta durante a revisão?",choices:["Somente o nome da branch, sem contexto adicional","Um resumo das alterações e do problema que resolvem","Somente a palavra atualizado como descrição inteira","Somente uma afirmação de que nenhuma revisão é necessária"],explanations:["O nome de uma branch sozinho pode não explicar o motivo e o escopo.","Um resumo conciso e uma justificativa fornecem contexto para a revisão.","Uma palavra genérica de status não descreve o trabalho.","Afirmar que a revisão é desnecessária não fornece evidências para a revisão."],concept:"Comunicação de alterações",hints:["O que a pessoa revisora precisaria saber antes de ler as diferenças?","Explique a intenção e também o conteúdo."]}
    ,"ghf-051": {prompt:"Por que um commit com uma alteração coerente costuma ser mais fácil de manter do que um commit que mistura alterações não relacionadas?",choices:["Ele nunca precisa de revisão","Ele não pode introduzir um bug","Ele pode ser entendido e revertido de forma mais seletiva","Ele torna a proteção de branches desnecessária"],explanations:["Commits focados ainda precisam de revisão.","Coerência não garante correção.","Uma alteração isolada é mais fácil de examinar ou reverter sem afetar trabalho não relacionado.","Proteções de branches têm uma finalidade de governança separada."],concept:"Alterações atômicas",hints:["E se apenas uma parte precisar ser desfeita?","Pense em diagnósticos futuros."]},
    "ghf-052": {prompt:"Para uma tarefa ativa, prefere-se uma branch chamada fix-search-timeout a uma chamada work. Por quê?",choices:["Seu nome exige que os testes passem","Seu nome concede acesso ao repositório","Seu nome fecha todas as issues relacionadas","Seu nome comunica a finalidade do trabalho em andamento"],explanations:["Nomes de branches não impõem testes.","O acesso vem de permissões, não de nomes.","O fechamento de issues exige vínculos e eventos qualificadores separados.","Um nome descritivo de branch ajuda a equipe a reconhecer o trabalho."],concept:"Nomes de branches",hints:["O que alguém da equipe pode deduzir da lista de branches?","Nomes comunicam, mas não impõem comportamentos."]},
    "ghf-053": {prompt:"Uma pessoa executa git add em um arquivo. O que aconteceu nesse momento?",choices:["O conteúdo selecionado do arquivo foi preparado para um commit futuro","O arquivo necessariamente foi enviado ao GitHub","Um novo commit necessariamente foi registrado","Todas as edições posteriores desse arquivo entrarão automaticamente no próximo commit"],explanations:["Git add coloca conteúdo no índice para o próximo commit.","A preparação sozinha não contata o GitHub.","Registrar o snapshot ainda exige uma operação de commit.","Edições feitas após a preparação precisam ser preparadas novamente para atualizar o conteúdo selecionado."],concept:"Preparação versus publicação",hints:["Qual estado local mudou?","O histórico já foi registrado ou transmitido?"]},
    "ghf-054": {prompt:"Uma equipe entende um pull request como uma solicitação para baixar arquivos. Qual é a melhor descrição?",choices:["Uma cópia de backup sem discussão","Uma proposta para mesclar alterações entre branches","Um substituto para um commit do Git","Uma solicitação de permissão de conta"],explanations:["Pull requests incluem revisão e discussão, não apenas conteúdo de backup.","Um pull request propõe alterações entre branches para revisão e integração.","Commits continuam sendo as alterações registradas subjacentes.","O acesso ao repositório é administrado separadamente."],concept:"Fundamentos de pull requests",hints:["O que está sendo proposto à branch receptora?","Considere a revisão antes da integração."]},
    "ghf-055": {prompt:"Uma pessoa altera a URL associada a um remoto local. O que isso muda principalmente?",choices:["O conteúdo de todos os commits anteriores","Qual branch está atualmente em checkout","O destino ao qual as próximas operações remotas se conectam","Quais alterações de arquivos estão preparadas"],explanations:["A configuração do remoto não reescreve o conteúdo dos commits.","Alterar a URL não troca a branch ativa.","A URL remota configurada determina o destino remoto.","O índice é separado da configuração de conexão remota."],concept:"URLs de remotos",hints:["É uma edição do histórico ou uma configuração de conexão?","Qual destino um fetch posterior usará?"]},
    "ghf-056": {prompt:"Duas pessoas usam interfaces compatíveis diferentes: uma usa GitHub Desktop e outra comandos do Git. Elas podem colaborar no mesmo repositório do GitHub?",choices:["Não; cada interface exige um formato de histórico diferente","Não; repositórios do Desktop não podem ter branches","Somente se o repositório não contiver código-fonte","Sim; ambas as interfaces trabalham com repositórios Git"],explanations:["Essas interfaces usam históricos de repositório Git compatíveis.","Desktop oferece suporte a fluxos com branches.","O tipo de conteúdo do repositório não impõe essa limitação.","Pessoas colaboradoras podem usar interfaces diferentes compatíveis com o Git."],concept:"Interoperabilidade de ferramentas",hints:["A interface altera o sistema de controle de versão subjacente?","Separe a escolha pessoal de ferramenta do histórico compartilhado do repositório."]},
    "ghf-057": {prompt:"Qual afirmação sobre a participação em organizações do GitHub está correta?",choices:["As pessoas acessam organizações por suas próprias contas","Todos os membros precisam usar uma senha compartilhada da organização","Entrar em uma organização exclui repositórios pessoais","A participação em uma organização cria uma branch Git local"],explanations:["Contas individuais recebem participação e funções.","Compartilhar credenciais prejudica a identidade individual e não é assim que organizações funcionam.","A participação não exclui repositórios pessoais.","A participação é administração de contas, não criação de branches."],concept:"Identidade individual em organizações",hints:["Como as ações devem continuar atribuíveis?","Separe a participação do compartilhamento de credenciais."]},
    "ghf-058": {prompt:"Por que uma empresa pode escolher GitHub Enterprise Cloud em vez de GitHub Enterprise Server?",choices:["Cloud elimina a necessidade de gerenciar permissões de repositórios","O GitHub opera o serviço hospedado em vez de a empresa operar uma instância de servidor","Cloud impede todos os conflitos de mesclagem","Cloud torna todos os repositórios de código aberto"],explanations:["Permissões continuam importantes em ambos os modelos.","Cloud transfere a hospedagem do serviço ao GitHub em vez de usar infraestrutura de Server operada pelo cliente.","Conflitos de mesclagem decorrem das alterações, não do modelo de implantação.","Repositórios no Cloud podem ter visibilidade restrita."],concept:"Responsabilidade pela implantação empresarial",hints:["Quem mantém a infraestrutura do serviço?","Não confunda hospedagem com garantias do fluxo de trabalho."]},
    "ghf-059": {prompt:"Uma pessoa quer sair da branch atual para outra branch local existente. Qual comando expressa essa ação?",choices:["git fetch","git add","git switch target-branch","git push"],explanations:["Fetch recupera informações remotas.","Add prepara conteúdo.","Switch altera a branch em checkout para o destino indicado.","Push transfere commits para um remoto."],concept:"Troca de branches",hints:["O objetivo é transferir histórico ou mudar o checkout?","Qual ação seleciona outra linha de trabalho?"]},
    "ghf-060": {prompt:"Uma pessoa autora quer que a revisão diferencie as linhas removidas das adicionadas em uma edição proposta. O que deve ser examinado?",choices:["Somente a lista de mensagens de commit","Somente o arquivo atual bruto","Somente a visualização de atribuição por linha do arquivo","O diff da alteração"],explanations:["Mensagens descrevem a intenção, mas não necessariamente mostram edições linha a linha.","O conteúdo bruto não tem a comparação entre antes e depois.","A atribuição por linha identifica alterações anteriores, mas não compara a edição proposta.","Um diff apresenta diferenças, como adições e exclusões."],concept:"Leitura de diffs",hints:["Qual visualização compara antes e depois?","Concentre-se no conteúdo alterado."]},
    "ghf-061": {prompt:"Um documento Markdown inclui o nome de uma linguagem compatível após o delimitador inicial de um bloco de código. Qual benefício isso oferece?",choices:["Permite realce de sintaxe específico da linguagem","Executa o código no GitHub","Valida a correção funcional do código","Instala essa linguagem no ambiente de quem lê"],explanations:["Um identificador de linguagem compatível ajuda o renderizador a realçar o código.","Blocos de código exibem texto em vez de executá-lo.","O realce é apresentação, não validação funcional.","O realce de sintaxe não instala ambientes de execução."],concept:"Realce de sintaxe",hints:["O delimitador serve para apresentação ou execução?","O que um renderizador poderia fazer com a informação da linguagem?"]},
    "ghf-062": {prompt:"Uma lista Markdown mostra - [x] Run tests. O que o x significa na lista de tarefas renderizada?",choices:["O item continua desmarcado","A tarefa está marcada como concluída","O texto está riscado em vez de ser um item de tarefa","A tarefa tem uma verificação de status automatizada com falha"],explanations:["Uma tarefa desmarcada usa um espaço entre colchetes.","Um x na caixa marca a tarefa como concluída.","O tachado usa outros delimitadores Markdown.","Uma caixa de seleção não é um resultado automatizado de teste."],concept:"Tarefas Markdown concluídas",hints:["Como isso difere de uma caixa vazia?","Separe o estado manual de tarefas das verificações automatizadas."]},
    "ghf-063": {prompt:"Um repositório contém código de programa, notas de design e arquivos de configuração. Quais deles o Git pode versionar?",choices:["Somente o código de programa","Somente arquivos já publicados no GitHub","Todos esses tipos de arquivos","Somente documentos Markdown"],explanations:["O Git não se restringe a código de programa.","Arquivos locais podem ser versionados antes de qualquer publicação.","O Git pode rastrear muitos tipos de arquivos em um repositório.","Markdown é compatível, mas não exclusivo."],concept:"Conteúdo de repositórios",hints:["O Git está vinculado a um único formato de documento?","Pense no projeto inteiro, não apenas no código executável."]},
    "ghf-064": {prompt:"Qual afirmação explica melhor por que commit local e push são ações separadas?",choices:["Commit apenas seleciona arquivos; push registra o primeiro snapshot local","Commit baixa o histórico remoto; push o integra localmente","Commit sempre exige rede; push para o GitHub nunca exige","Commit registra o histórico local; push o compartilha com um remoto"],explanations:["A preparação seleciona conteúdo; commit registra um snapshot antes de push.","Fetch recupera histórico e pull integra o trabalho recuperado.","Commits locais podem ser feitos offline; pushes para o GitHub precisam de conectividade.","Registrar e transmitir histórico são operações distintas."],concept:"Histórico local e remoto",hints:["Onde a alteração é registrada primeiro?","Quando quem colabora no remoto pode vê-la?"]},
    "ghf-065": {prompt:"Uma pessoa que visita o projeto pela primeira vez precisa conhecer sua finalidade e as instruções básicas de configuração. Qual arquivo normalmente deve apresentar essas informações?",choices:["README.md","CODEOWNERS","LICENSE","Um arquivo de lock de pacotes"],explanations:["Um README apresenta o projeto e como começar.","CODEOWNERS associa caminhos a responsáveis pela revisão.","LICENSE define permissões e condições legais.","Um arquivo de lock registra a resolução de dependências, não apresenta o projeto."],concept:"Finalidade do README",hints:["O que uma pessoa visitante deve ler primeiro?","Separe a orientação dos metadados legais e de dependências."]},
    "ghf-066": {prompt:"Uma pessoa mantenedora quer declarar os termos legais para reutilizar o código do repositório. Qual arquivo é mais adequado?",choices:["CONTRIBUTING.md","LICENSE","CODEOWNERS","Um template de pull request"],explanations:["Diretrizes de contribuição descrevem como participar.","Uma licença especifica permissões e condições de reutilização.","CODEOWNERS atribui responsabilidades por caminhos.","Um template de pull request estrutura descrições de alterações propostas."],concept:"Licenciamento de repositórios",hints:["É uma permissão legal ou uma instrução de fluxo de trabalho?","Qual documento rege a reutilização?"]},
    "ghf-067": {prompt:"Uma pessoa que contribui precisa conhecer os comandos de teste obrigatórios e o processo de envio de patches. Qual é o melhor arquivo dedicado a essa orientação?",choices:["LICENSE","SECURITY.md","CONTRIBUTING.md","CODEOWNERS"],explanations:["Uma licença define os termos de reutilização.","Uma política de segurança explica o relato de vulnerabilidades e as versões com suporte.","Diretrizes de contribuição explicam o fluxo de participação no projeto.","CODEOWNERS identifica responsáveis pela revisão, não etapas de envio."],concept:"Diretrizes de contribuição",hints:["Quem é o público pretendido?","Diferencie a participação rotineira do relato de vulnerabilidades."]},
    "ghf-068": {prompt:"Um projeto quer que pesquisadores saibam onde relatar vulnerabilidades de forma privada. Qual arquivo dedicado deve conter essa política?",choices:["Um template de pull request","CODE_OF_CONDUCT.md","CODEOWNERS","SECURITY.md"],explanations:["Um template de pull request estrutura alterações propostas, não define a política dedicada de divulgação.","Um código de conduta trata do comportamento da comunidade e do relato de conduta.","CODEOWNERS define a responsabilidade pela revisão, não orientações de divulgação.","SECURITY.md documenta instruções de relato de segurança e informações de suporte."],concept:"Arquivo de política de segurança",hints:["A questão é uma contribuição comum ou uma divulgação sensível?","Procure uma política dedicada ao tratamento de vulnerabilidades."]},
    "ghf-069": {prompt:"Uma equipe quer que pull requests prontos para revisão que alterem /payments/ solicitem revisão de quem mantém pagamentos. Qual mecanismo atende a isso?",choices:["Uma regra de caminhos do CODEOWNERS","Uma estrela de repositório","Uma descrição do repositório","Um ativo de uma versão publicada"],explanations:["CODEOWNERS associa caminhos correspondentes a usuários ou equipes para solicitar revisão.","Marcar com uma estrela não atribui revisores.","Descrições resumem o repositório.","Ativos de versões distribuem arquivos em vez de encaminhar revisões."],concept:"Propriedade do código",hints:["O que associa caminhos de arquivos a pessoas responsáveis?","Separe o encaminhamento por propriedade da descoberta de repositórios."]},
    "ghf-070": {prompt:"Adicionar apenas um arquivo CODEOWNERS exige a aprovação de um proprietário antes da mesclagem?",choices:["Sim, toda alteração correspondente fica impedida de ser mesclada sem ela","Não; um requisito adequado de proteção de branch ou de conjunto de regras também precisa impor a aprovação","Sim, mas somente para arquivos Markdown","Não, porque proprietários de código nunca podem revisar pull requests"],explanations:["Solicitações automáticas de revisão não são, por si só, uma condição obrigatória de mesclagem.","Propriedade e aprovação obrigatória de proprietário são configurações separadas.","O tipo de arquivo não cria um requisito automático de aprovação.","Proprietários de código podem revisar; falta exigir essa aprovação."],concept:"Propriedade versus imposição de requisitos",hints:["Solicitar revisão é o mesmo que exigir aprovação?","Quais configurações controlam o bloqueio da mesclagem?"]},
    "ghf-071": {prompt:"Um pull request tem main como destino, mas altera CODEOWNERS na branch de funcionalidade. Qual versão determina as solicitações automáticas de revisão de proprietários de código?",choices:["O CODEOWNERS mais recente de qualquer fork","O CODEOWNERS local ainda não commitado da pessoa autora","O CODEOWNERS de main, a branch base","Todos os arquivos CODEOWNERS da organização combinados"],explanations:["Outros forks não fornecem as regras de propriedade da branch receptora.","Arquivos locais ainda não commitados não configuram o encaminhamento de revisão hospedado.","Pull requests usam a propriedade de código da branch base.","O GitHub não combina todos os arquivos de propriedade da organização."],concept:"Branch base da propriedade do código",hints:["Qual branch receberá a alteração?","Uma proposta deveria definir sua própria autoridade de revisão existente?"]},
    "ghf-072": {prompt:"Um repositório tem arquivos CODEOWNERS em .github/, na raiz e em docs/. Qual localização tem precedência?",choices:["docs/","A raiz","Os três são combinados",".github/"],explanations:["Docs é procurado depois das outras localizações compatíveis.","A raiz é procurada depois de .github/.","O GitHub usa a primeira localização encontrada em vez de combinar arquivos.","O GitHub procura em .github/ antes da raiz e de docs/."],concept:"Precedência de localização do CODEOWNERS",hints:["O GitHub combina todos os arquivos de propriedade?","Pense na ordem de busca documentada."]},
    "ghf-073": {prompt:"Uma empresa quer que novos serviços independentes comecem com pastas e arquivos iniciais padronizados, sem herdar o histórico de commits do repositório inicial. O que deve usar?",choices:["Um template de repositório","Um fork de cada serviço","Uma assinatura Watch do repositório","Uma revisão de pull request"],explanations:["Um template fornece arquivos a um novo projeto com seu próprio histórico inicial.","Um fork preserva um histórico relacionado e uma relação com o repositório original.","Watch configura notificações.","A revisão avalia alterações propostas em vez de gerar um novo repositório."],concept:"Templates de repositório",hints:["O objetivo é um novo projeto ou uma contribuição ao original?","Os commits históricos do repositório inicial devem ser transferidos?"]},
    "ghf-074": {prompt:"Depois de gerar um repositório a partir de um template, o que acontece quando a pessoa autora do template edita um arquivo inicial?",choices:["O repositório gerado recebe a edição automaticamente","O repositório gerado não é sincronizado automaticamente","O GitHub abre automaticamente um pull request de atualização em cada repositório gerado","A edição aparece no repositório gerado na próxima vez que alguém o clona"],explanations:["Templates não fornecem sincronização automática contínua.","O novo projeto é independente; alterações posteriores precisam ser adotadas separadamente.","Editar o template sozinho não cria pull requests de atualização nos projetos gerados.","Clonar recupera o histórico próprio do projeto gerado, não alterações posteriores do template."],concept:"Independência de templates",hints:["Foi criada uma relação de sincronização ativa?","Separe a geração inicial da manutenção posterior."]},
    "ghf-075": {prompt:"Um template inclui várias branches, e o repositório gerado inclui todas elas. Por que não se deve presumir que pull requests e mesclagens normais do GitHub estejam disponíveis entre essas branches geradas?",choices:["Todas as branches geradas são aliases da mesma referência","Todas as branches geradas são permanentemente somente leitura","Seus históricos gerados não são relacionados","Cada branch mantém uma conexão ativa com os commits originais do template"],explanations:["Branches geradas são distintas, não aliases.","A geração por template não torna as branches inerentemente somente leitura.","Branches geradas por um template têm históricos não relacionados, ao contrário de branches comuns com histórico compartilhado.","Projetos gerados não mantêm uma conexão de sincronização ativa com o template."],concept:"Históricos de branches de templates",hints:["Essas branches compartilham uma ancestralidade comum?","Consulte a diferença entre gerar a partir de um template e criar um fork."]}
    ,"ghf-076": {prompt:"Uma pessoa mantenedora quer alterar um arquivo pela interface web do GitHub mantendo a revisão antes da integração. Qual fluxo atende a isso?",choices:["Editar a descrição do repositório","Enviá-lo apenas como anexo de uma issue","Alterar a visibilidade do repositório","Registrar a edição em uma nova branch e abrir um pull request"],explanations:["Uma descrição não modifica o arquivo versionado.","Um anexo de issue não é uma edição versionada do repositório.","Alterações de visibilidade não editam o conteúdo dos arquivos.","Uma branch e um pull request preservam o fluxo de revisão para edições web."],concept:"Edição de arquivos pela web",hints:["Onde a alteração versionada deve ficar?","Como revisar antes de alterar a branch padrão?"]},
    "ghf-077": {prompt:"O que se deve esperar quando um arquivo rastreado é excluído em um novo commit?",choices:["Ele desaparece dessa revisão, mas pode permanecer no histórico anterior","Todas as cópias históricas são apagadas automaticamente","O mesmo arquivo é removido automaticamente de todas as outras branches","Todos os clones existentes excluem imediatamente sua cópia de trabalho sem fazer fetch"],explanations:["O histórico do Git pode manter versões anteriores à exclusão.","Uma exclusão comum não expurga o conteúdo histórico.","Um commit altera sua linha de histórico, não todas as branches ao mesmo tempo.","Outros repositórios locais não atualizam arquivos de trabalho sem receber e aplicar alterações."],concept:"Exclusão de arquivos e histórico",hints:["Um novo snapshot reescreve todos os anteriores?","Separe o conteúdo atual do histórico preservado."]},
    "ghf-078": {prompt:"Adiciona-se build/ ao .gitignore depois que build/output.log já foi commitado. O que se deve esperar?",choices:["O log rastreado é apagado de todo o histórico","A regra de exclusão sozinha não interrompe o rastreamento do arquivo já rastreado","O log é removido automaticamente do índice","O log é excluído automaticamente do disco local"],explanations:["Regras de exclusão não reescrevem o histórico.",".gitignore aplica-se a arquivos intencionalmente não rastreados; arquivos rastreados exigem uma etapa separada para deixar de sê-lo.","Adicionar uma regra não remove o rastreamento de arquivos já indexados.","Um padrão de exclusão não é um comando para excluir arquivos."],concept:"Exclusão de arquivos rastreados",hints:["O arquivo já estava no controle de versão?","Separe ignorar arquivos novos de remover conteúdo rastreado."]},
    "ghf-079": {prompt:"Uma pessoa quer salvar vários repositórios como favoritos sem assinar todas as conversas. Qual recurso é destinado a isso?",choices:["Revisores obrigatórios","Proteção de branches","Estrelas","Propriedade da organização"],explanations:["Revisores obrigatórios governam a aprovação de alterações.","A proteção de branches impõe regras de branches.","Estrelas ajudam a salvar e descobrir repositórios sem serem uma assinatura Watch.","A propriedade concede responsabilidades, não favoritos."],concept:"Estrelas de repositórios",hints:["O objetivo é salvar um projeto ou receber atualizações?","Separe os favoritos das assinaturas de notificações."]},
    "ghf-080": {prompt:"Uma pessoa quer organizar repositórios com estrela em categorias pessoais. Qual recurso deve considerar?",choices:["Marcos do repositório","Branches protegidas","Tags de commits","Listas de repositórios com estrela"],explanations:["Marcos agrupam issues e pull requests em um repositório.","A proteção de branches governa alterações.","Tags identificam revisões do repositório.","Listas organizam em coleções os repositórios marcados com estrela por uma pessoa."],concept:"Listas de estrelas",hints:["De quem é a coleção sendo organizada?","Diferencie ferramentas pessoais de descoberta do acompanhamento do trabalho do projeto."]},
    "ghf-081": {prompt:"Um projeto quer ser encontrado mais facilmente por quem busca rust e ferramentas de linha de comando. Quais metadados deve adicionar?",choices:["Tópicos relevantes","Somente rótulos de issues","Padrões de proprietários de código","Um marco para cada linguagem de programação"],explanations:["Tópicos categorizam repositórios por finalidade ou tecnologia para facilitar a descoberta.","Rótulos de issues classificam itens de trabalho, não fornecem tópicos ao repositório.","Padrões de propriedade identificam responsáveis pela revisão.","Marcos acompanham entregas, não classificações públicas de tecnologia."],concept:"Tópicos de repositórios",hints:["Quais metadados descrevem o assunto do projeto?","Pense em descoberta, não em imposição de regras."]},
    "ghf-082": {prompt:"Uma biblioteca chega a uma versão pronta para distribuição com notas de versão e binários para download. Qual recurso do GitHub foi projetado para isso?",choices:["Um rótulo de issue","Uma release","Uma regra do CODEOWNERS","Um filtro de Watch"],explanations:["Rótulos classificam itens de trabalho, não distribuições versionadas.","Releases empacotam versões com tags, notas e ativos opcionais.","Regras de propriedade encaminham solicitações de revisão.","Filtros de Watch configuram notificações."],concept:"Releases de repositórios",hints:["O que combina uma versão com informações de distribuição?","Separe a entrega do projeto da classificação de tarefas."]},
    "ghf-083": {prompt:"Um projeto não é mais mantido, mas seu código e suas conversas devem continuar disponíveis como referência somente leitura. O que a administração deve considerar?",choices:["Excluir cada arquivo separadamente","Tornar todos os membros proprietários","Arquivar o repositório","Criar um pull request para cada visitante"],explanations:["Excluir arquivos removeria conteúdo atual útil sem indicar o estado de arquivamento.","Conceder propriedade aumenta o acesso em vez de preservar um estado somente leitura.","Arquivar marca o repositório como inativo e o torna somente leitura.","Pull requests de visitantes não implementam o arquivamento do repositório inteiro."],concept:"Arquivamento de repositórios",hints:["O material deve continuar disponível?","Qual ação comunica inatividade sem exclusão?"]},
    "ghf-084": {prompt:"Qual ação restaura a atividade normal de escrita em um repositório arquivado?",choices:["Adicionar uma estrela","Baixar seu ZIP do código-fonte","Seguir seu proprietário","Desarquivar o repositório"],explanations:["Marcar com estrela não muda o arquivamento.","Baixar apenas copia conteúdo.","Seguir um proprietário não altera as configurações do repositório.","Uma pessoa administradora autorizada pode desarquivá-lo para retomar as atualizações."],concept:"Restauração de trabalho arquivado",hints:["Qual configuração tornou o repositório somente leitura?","Diferencie uma configuração de ciclo de vida de uma ação de visitante."]},
    "ghf-085": {prompt:"Quer-se ver quais pacotes o projeto usa e quais dependências compatíveis têm vulnerabilidades conhecidas. Qual capacidade do repositório é relevante?",choices:["Grafo de dependências","Conquistas do perfil","Listas de estrelas","O título de um pull request"],explanations:["O grafo de dependências resume dependências reconhecidas e metadados relacionados.","Conquistas descrevem a atividade da conta.","Listas de estrelas organizam repositórios salvos como favoritos.","Um título não inventaria a árvore de dependências."],concept:"Grafo de dependências",hints:["Onde os dados de manifestos e arquivos de lock seriam resumidos?","Diferencie relações de software de metadados sociais."]},
    "ghf-086": {prompt:"Como o grafo de dependências do GitHub obtém informações de dependências?",choices:["Somente de nomes de repositórios","De manifestos e arquivos de lock compatíveis, além de dados de dependências enviados","Somente de capturas de tela do README","Da lista de observadores do repositório"],explanations:["O nome de um repositório não descreve os pacotes resolvidos.","Arquivos de dependências reconhecidos e a API de envio fornecem dados ao grafo.","Capturas de tela não são manifestos de dependências.","Observadores são pessoas interessadas na atividade, não dependências de pacotes."],concept:"Entradas do grafo de dependências",hints:["Quais arquivos estruturados declaram relações entre pacotes?","Dependências calculadas externamente também podem ser enviadas?"]},
    "ghf-087": {prompt:"Uma visualização Insights do repositório resume contribuições e atividade. Qual interpretação é responsável?",choices:["Ela comprova o valor de negócio de cada pessoa contribuinte","Ela substitui a revisão do trabalho real","Ela fornece evidências de atividade que precisam de contexto","Ela garante que o código ativo não tem defeitos"],explanations:["Medições de atividade não comprovam diretamente valor de negócio.","A revisão qualitativa continua necessária.","Insights ajuda a investigar a atividade, mas exige interpretação contextual.","Atividade não é garantia de correção."],concept:"Interpretação de Insights do repositório",hints:["Contar atividades mede todos os resultados?","Que contexto um gráfico pode omitir?"]},
    "ghf-088": {prompt:"Quer-se avaliar a atividade recente de pull requests e issues em vez de examinar as alterações de um único arquivo. Qual área do repositório é mais relevante?",choices:["As configurações pessoais de chaves SSH","O arquivo LICENSE","A área de preparação local","Insights do repositório, incluindo Pulse"],explanations:["Configurações SSH tratam de autenticação.","Licenciamento trata de termos de reutilização.","A preparação descreve conteúdo local ainda não commitado.","Insights e Pulse resumem a atividade do repositório entre itens de trabalho."],concept:"Visão geral da atividade",hints:["A pergunta trata de um diff ou de trabalho agregado?","Procure uma visão geral da atividade do repositório."]},
    "ghf-089": {prompt:"Uma pessoa quer experimentar um recurso de interface em versão prévia pública elegível para sua conta. Onde deve procurar?",choices:["Feature preview no menu do perfil","A área de preparação de commits do Git","O arquivo LICENSE do repositório","As faturas da organização"],explanations:["Feature preview lista recursos de versão prévia elegíveis e os controles disponíveis.","A preparação não tem controles de recursos da conta.","Licenciamento não configura versões prévias da interface do GitHub.","Faturas não são a interface de recursos em versão prévia."],concept:"Feature preview",hints:["É um arquivo de repositório ou uma experiência da conta?","Procure acesso opcional a recursos experimentais."]},
    "ghf-090": {prompt:"Por que uma equipe não deve tratar um recurso do GitHub em versão prévia pública como se tivesse os mesmos compromissos de um recurso em disponibilidade geral?",choices:["Recursos em versão prévia não podem ter documentação","A versão prévia pública tem compromissos de suporte e serviço diferentes","Versão prévia significa que o recurso tem licença de código aberto","Recursos em versão prévia não podem receber feedback"],explanations:["Versões prévias públicas podem ser documentadas.","A fase de lançamento afeta os compromissos de suporte e nível de serviço.","A fase de lançamento não estabelece o licenciamento do código-fonte.","Programas de versão prévia costumam solicitar feedback explicitamente."],concept:"Maturidade de versões prévias",hints:["O que uma fase de lançamento comunica?","Diferencie a disponibilidade para testes dos compromissos de produção."]},
    "ghf-091": {prompt:"Uma pessoa quer compartilhar um link de um arquivo exatamente como ele existe hoje, sem ser afetado por edições posteriores da branch. O que deve usar?",choices:["Um link apenas para a página inicial do repositório","Um link do arquivo com o nome mutável da branch","Um link permanente vinculado ao commit do arquivo","Um link relativo que acompanhe a branch sendo navegada"],explanations:["A página inicial não identifica a revisão do arquivo.","Uma branch pode avançar para commits mais recentes.","Um permalink baseado em commit identifica uma revisão imutável do arquivo.","Um link relativo que acompanha a branch não fixa uma revisão histórica."],concept:"Links permanentes de arquivos",hints:["O que muda quando uma branch avança?","Como a URL pode indicar uma revisão fixa?"]},
    "ghf-092": {prompt:"Uma pessoa precisa entender por que um arquivo específico mudou no mês passado. Qual recurso deve examinar primeiro?",choices:["Somente o conteúdo bruto atual do arquivo","Somente a lista atual de branches","Somente o resumo de linguagens do repositório","O histórico de commits do arquivo"],explanations:["O conteúdo atual sozinho omite a sequência registrada e as mensagens.","Nomes de branches sozinhos não explicam uma edição histórica específica.","A composição de linguagens não estabelece a intenção da alteração.","O histórico do arquivo expõe commits, mensagens e alterações relevantes."],concept:"Histórico de arquivos",hints:["Quais registros conectam edições a mensagens e autores?","Concentre-se nas evidências versionadas desse arquivo."]},
    "ghf-093": {prompt:"Antes de excluir um repositório, o que seu proprietário deve entender sobre a ação?",choices:["Ela remove o repositório e os dados associados em vez de apenas marcá-lo como inativo","Ela equivale a fechar uma issue","Ela remove apenas um clone local","Ela apenas cancela a assinatura de notificações do proprietário"],explanations:["Excluir é substancialmente diferente de arquivar e pode remover dados associados ao repositório.","Fechar uma issue mantém o repositório intacto.","Excluir o repositório hospedado não é limpar um clone local.","Preferências de notificação não determinam a existência do repositório."],concept:"Exclusão versus arquivamento",hints:["As pessoas devem continuar podendo consultar o projeto?","Diferencie mudanças destrutivas do ciclo de vida de preferências pessoais."]},
    "ghf-094": {prompt:"Um novo repositório independente precisa de arquivos iniciais sem histórico herdado, enquanto um existente precisa de uma linha isolada para alterações contínuas. Qual combinação atende a isso?",choices:["Um fork para o início e uma release para as edições","Um template para o início e uma branch para as alterações contínuas","Uma branch como repositório independente e uma tag como linha editável","Um ZIP de código-fonte como novo repositório hospedado e um ativo de release como linha editável"],explanations:["Um fork herda histórico e uma release não é uma linha editável de trabalho.","Templates geram projetos novos; branches isolam alterações dentro de um projeto.","Uma branch não é um repositório separado, e uma tag é um marcador de versão.","Baixar um arquivo compactado não cria um repositório hospedado, e ativos não funcionam como branches."],concept:"Templates versus branches",hints:["Essas tarefas criam um projeto ou alteram um?","Associe cada escopo ao mecanismo de versionamento adequado."]},
    "ghf-095": {prompt:"Uma pessoa relata um encerramento inesperado reproduzível que precisa de responsáveis e acompanhamento até a resolução. Qual objeto de colaboração é o melhor ponto de partida?",choices:["Uma release","Um gist","Uma issue","Um tópico de repositório"],explanations:["Releases distribuem versões em vez de acompanhar um defeito pendente.","Um gist compartilha conteúdo sem o fluxo de issues do repositório.","Uma issue acompanha bugs acionáveis com discussão e atribuição.","Tópicos classificam o repositório em vez de registrar um defeito."],concept:"Issues para trabalho acionável",hints:["Há um problema concreto para resolver?","Qual objeto permite acompanhar seu ciclo de vida?"]},
    "ghf-096": {prompt:"Uma comunidade quer uma conversa aberta sobre possíveis rumos de longo prazo, sem uma tarefa de implementação acordada ainda. Qual recurso é mais adequado?",choices:["Uma verificação de status obrigatória","Uma tag de versão","Um commit de mesclagem","GitHub Discussions"],explanations:["Verificações avaliam resultados automatizados, não hospedam planejamento aberto.","Tags identificam versões históricas.","Commits de mesclagem integram alterações.","Discussions permite conversas e ideias abertas da comunidade."],concept:"Discussions versus issues",hints:["O grupo já definiu trabalho acionável?","Onde as ideias podem evoluir antes de assumir uma tarefa?"]},
    "ghf-097": {prompt:"Abre-se um pull request em rascunho para uma refatoração incompleta. O que o estado de rascunho comunica?",choices:["A proposta ainda não está pronta para revisão normal e não pode ser mesclada enquanto for rascunho","A proposta é invisível para todas as outras pessoas","A branch não contém commits","A proposta já passou pela revisão"],explanations:["Rascunhos permitem colaboração antecipada, mas precisam ser marcados como prontos antes da mesclagem.","O estado de rascunho não é um controle de privacidade.","Pull requests em rascunho podem conter commits e alterações.","O rascunho não significa aprovação."],concept:"Pull requests em rascunho",hints:["Inacabado significa privado?","Qual transição é necessária antes de estar pronto para mesclar?"]},
    "ghf-098": {prompt:"Um pull request de fix-export tem main como destino. Qual é a branch base?",choices:["fix-export","main","Ambas igualmente","A branch local de backup da pessoa autora"],explanations:["Fix-export é a branch de origem que fornece alterações.","A base é a branch de destino que receberia a mesclagem.","Origem e base têm funções distintas.","Uma branch local não relacionada não é o destino do pull request."],concept:"Branches de origem e base",hints:["Qual branch recebe a proposta?","Separe a origem das alterações de seu destino."]},
    "ghf-099": {prompt:"Uma pessoa revisora quer comentar uma linha alterada em um pull request. Qual visualização é destinada a isso?",choices:["Somente a aba geral Conversation do pull request","Somente o arquivo bruto da branch padrão","Files changed","Os resultados de busca de issues do repositório"],explanations:["A conversa geral permite comentários amplos, não selecionar uma linha alterada no diff.","O arquivo base atual bruto não fornece o contexto de revisão inline da proposta.","Files changed expõe o diff e permite comentários de revisão inline.","A busca de issues não expõe os controles de diff inline do pull request."],concept:"Revisão inline",hints:["Onde o diff proposto é exibido?","O feedback trata da proposta inteira ou de uma linha específica?"]},
    "ghf-100": {prompt:"Uma pessoa revisora encontra um problema bloqueante e quer que o resultado da revisão indique explicitamente que alterações são necessárias. Qual ação atende a isso?",choices:["Enviar uma revisão de aprovação com uma observação","Enviar uma revisão somente com comentários","Marcar o arquivo afetado como visualizado","Request changes"],explanations:["A aprovação comunica aceitação, não o resultado de solicitação de revisão pretendido.","Uma revisão somente com comentários fornece feedback sem o resultado de alterações solicitadas.","O estado visualizado acompanha a inspeção, não uma decisão de revisão.","Request changes registra um resultado de revisão que indica problemas a resolver."],concept:"Resultados de revisão",hints:["Qual ação comunica formalmente uma solicitação de alteração?","Separe uma decisão de revisão do progresso da inspeção."]}
    ,"ghf-101": {prompt:"Uma pessoa revisora propõe uma substituição exata para um pequeno trecho de código. Qual recurso permite aplicar esse texto pelo fluxo de revisão?",choices:["Uma alteração sugerida em um comentário de revisão","Um comentário de texto sem bloco de alteração sugerida","Apenas marcar o arquivo como visualizado","Apenas resolver a discussão"],explanations:["Alterações sugeridas oferecem uma substituição diretamente aplicável no contexto de revisão.","Feedback em texto pode descrever uma alteração, mas não tem o controle de sugestão diretamente aplicável.","O estado visualizado não codifica texto de substituição.","Resolver uma discussão registra o estado da conversa, não aplica código."],concept:"Alterações sugeridas",hints:["O feedback é uma substituição textual específica?","Qual ferramenta de revisão pode transformar feedback em um commit?"]},
    "ghf-102": {prompt:"Um pull request destinado à branch padrão inclui Fixes #37 na descrição. Quando a issue referenciada normalmente é fechada automaticamente?",choices:["Quando o pull request é aberto","Quando o pull request é mesclado à branch padrão","Quando alguém adiciona uma reação","Quando alguém lê a descrição durante a revisão"],explanations:["Abrir a proposta cria uma relação, mas não conclui a correção.","A mesclagem que atende às condições fecha a issue vinculada.","Reações não acionam o fechamento por palavras-chave.","Ler a descrição não muda o estado da issue."],concept:"Palavras-chave de fechamento",hints:["Qual evento indica que a alteração foi integrada?","Preste atenção à branch de destino."]},
    "ghf-103": {prompt:"Um pull request tem como destino uma branch de lançamento que não é a padrão e sua descrição diz Closes #51. O que a pessoa autora deve esperar dessa palavra-chave sozinha?",choices:["Ela fecha a issue assim que a descrição é salva","Ela cria uma relação de fechamento concluída em qualquer mesclagem de branch","Nesse caso, ela é ignorada para vinculação e fechamento automáticos de issues","Ela fecha a issue na primeira revisão de aprovação"],explanations:["Salvar uma descrição não conclui um fluxo de fechamento de issues.","Palavras-chave de fechamento na descrição não se aplicam a toda branch de destino.","Elas são interpretadas em pull requests destinados à branch padrão.","Uma aprovação não é o evento que atende às condições de fechamento."],concept:"Escopo de palavras-chave na branch padrão",hints:["A palavra-chave especial vale para toda branch de destino?","Verifique o pré-requisito da vinculação automática."]},
    "ghf-104": {prompt:"A descrição de um pull request deve fechar a issue 19 de outro repositório, tools/parser, quando mesclado nas condições adequadas. Qual sintaxe expressa isso?",choices:["Fixes @tools/parser/19","Fixes #tools/parser/19","Fixes tools/parser:19","Fixes tools/parser#19"],explanations:["A arroba indica menções, não essa forma de referência a issues.","O nome do repositório deve vir antes da cerquilha.","Dois-pontos não são o separador documentado para issues de outro repositório.","A forma proprietário/repositório#número qualifica a referência à issue."],concept:"Links de issues entre repositórios",hints:["Como o contexto do repositório é fornecido?","Onde fica o delimitador do número da issue?"]},
    "ghf-105": {prompt:"Um projeto recebe relatos de bugs sem etapas de reprodução. O que pode adicionar para orientar consistentemente quem relata?",choices:["Um template ou formulário de issues","Um ativo de release","Uma tag do Git","Um padrão de proprietários de código"],explanations:["Templates e formulários orientam as informações coletadas em novas issues.","Ativos distribuem downloads versionados.","Tags identificam revisões.","Padrões de propriedade encaminham revisões em vez de estruturar relatos."],concept:"Templates de issues",hints:["Onde as informações de quem relata são coletadas?","Considere uma estrutura repetível de recebimento."]},
    "ghf-106": {prompt:"Uma equipe quer que toda descrição nova de pull request solicite resumo, evidências de testes e issues relacionadas. O que deve configurar?",choices:["Um marco de issues","Um template de pull request","Um slug de equipe da organização","Uma tag de commit"],explanations:["Marcos agrupam trabalho em vez de preencher descrições.","Um template de pull request fornece orientações padronizadas a quem cria a proposta.","Um slug de equipe identifica um grupo.","Uma tag marca um commit, não um formato de envio."],concept:"Templates de pull request",hints:["Qual artefato é criado no momento da proposta?","Diferencie orientação de recebimento de categorização de trabalho."]},
    "ghf-107": {prompt:"Qual busca encontra mais diretamente issues abertas atribuídas à pessoa atual?",choices:["is:pr is:closed author:@me","is:issue is:open mentions:@me","is:issue is:open assignee:@me","is:issue is:closed assignee:@me"],explanations:["Isso seleciona pull requests fechados criados pela pessoa.","Uma menção não é o mesmo que uma atribuição.","Os qualificadores especificam issues abertas atribuídas à pessoa atual.","Isso seleciona issues fechadas, não abertas."],concept:"Filtros de issues",hints:["Ter responsabilidade é o mesmo que receber uma menção?","Confira o tipo de objeto e o estado do ciclo de vida."]},
    "ghf-108": {prompt:"Uma pessoa mantenedora precisa de pull requests abertos que aguardam sua revisão, não apenas dos que criou. Qual qualificador identifica essa relação?",choices:["author:@me","assignee:@me","mentions:@me","review-requested:@me"],explanations:["Author identifica quem criou o item.","Assignee identifica responsabilidade atribuída, não especificamente revisão solicitada.","Mentions inclui referências textuais em vez de solicitações explícitas de revisão.","Review-requested seleciona pull requests que solicitam a revisão da pessoa."],concept:"Filtros de solicitação de revisão",hints:["Qual papel a pessoa mantenedora desempenha?","Escolha uma solicitação explícita em vez de uma relação geral."]},
    "ghf-109": {prompt:"Uma pessoa quer atualizações somente de releases de um repositório ao qual tem acesso. Qual abordagem de notificações é a mais adequada?",choices:["Personalizar a assinatura Watch para releases","Marcar com estrela e presumir que toda release gerará notificações","Acompanhar toda a atividade sem restringir os tipos","Assinar uma issue existente"],explanations:["Configurações personalizadas de Watch permitem assinar tipos selecionados, como releases.","Estrelas não são uma assinatura de notificações de releases.","Acompanhar toda a atividade inclui mais do que as atualizações de releases solicitadas.","Assinar uma issue não assina releases futuras do repositório."],concept:"Assinaturas Watch personalizadas",hints:["Qual recurso controla a entrega de atividade?","Uma assinatura pode ser mais restrita que toda a atividade?"]},
    "ghf-110": {prompt:"Uma pessoa quer atualizações de uma única issue sem acompanhar todas as issues do repositório. O que deve fazer?",choices:["Acompanhar toda a atividade de issues do repositório","Assinar a conversa dessa issue","Usar uma estrela como substituto da assinatura","Apenas marcar como não lida a notificação existente"],explanations:["Atualizações de todas as issues são mais amplas que o solicitado.","Uma assinatura da conversa limita as atualizações a essa issue.","Uma estrela não é uma assinatura dessa conversa.","O estado não lido não estabelece sozinho a assinatura contínua desejada."],concept:"Assinaturas de conversas",hints:["Quão restrito deve ser o escopo das atualizações?","Separe os controles pessoais de entrega do estado da caixa de entrada."]},
    "ghf-111": {prompt:"Uma pessoa marca uma notificação como lida sem mudar sua assinatura. O que deve esperar em geral?",choices:["Todas as atualizações futuras da discussão ficam silenciadas permanentemente","O repositório deixa de ser acompanhado automaticamente","Atividades futuras assinadas ainda podem gerar notificações","Só uma nova assinatura manual pode restaurar as atualizações"],explanations:["Marcar como lida não silencia permanentemente atualizações futuras.","O estado lido não muda a configuração Watch do repositório.","O estado lido e a entrega futura da assinatura são questões separadas.","Marcar uma atualização como lida não removeu a assinatura existente."],concept:"Estado lido versus assinatura",hints:["A pessoa alterou as configurações de entrega?","Diferencie processar uma atualização de interromper as futuras."]},
    "ghf-112": {prompt:"Uma pessoa não precisa mais de atualizações contínuas de uma discussão específica. Qual ação altera essa assinatura?",choices:["Marcar apenas a última notificação como lida","Remover a discussão de um filtro da caixa de entrada","Ocultá-la mudando a busca de issues","Cancelar a assinatura da discussão"],explanations:["O estado lido não cancela uma assinatura contínua.","Um filtro muda o subconjunto exibido, não a assinatura.","A apresentação da busca não altera a entrega futura de notificações.","Cancelar a assinatura interrompe a assinatura existente da atividade contínua da discussão."],concept:"Cancelamento de assinaturas",hints:["A mudança desejada é na apresentação ou na entrega futura?","Qual controle rege a relação contínua?"]},
    "ghf-113": {prompt:"Uma pessoa desenvolvedora quer compartilhar um pequeno script de exemplo versionado sem criar toda a interface de um repositório de projeto. Qual recurso atende a isso?",choices:["Um gist","Um marco","Uma equipe","Uma regra de branch"],explanations:["Gists foram projetados para compartilhar trechos e mantêm o histórico do Git.","Marcos agrupam itens de trabalho.","Equipes agrupam membros de organizações.","Regras de branches impõem requisitos de alterações."],concept:"Gists",hints:["Quanta estrutura de projeto é necessária?","Qual ferramenta de compartilhamento usa Git como base?"]},
    "ghf-114": {prompt:"Alguém propõe armazenar uma credencial confidencial em um gist secreto porque ele não aparece em listas públicas. Qual é a resposta correta?",choices:["É seguro porque somente contas convidadas podem abrir gists secretos","Não é seguro porque qualquer pessoa que obtenha a URL pode visualizá-lo","É seguro porque gists secretos não têm URLs","É seguro se a credencial estiver em um comentário"],explanations:["Gists secretos não são listados; não são armazenamento privado restrito a convites.","Ter a URL pode expor o conteúdo, portanto credenciais não devem ser armazenadas ali.","Gists secretos podem ser compartilhados por URL.","Comentários não estabelecem um limite seguro para credenciais."],concept:"Privacidade de gists secretos",hints:["Não listado significa ter controle de acesso?","O que acontece se a URL for encaminhada?"]},
    "ghf-115": {prompt:"Qual afirmação sobre o versionamento de gists está correta?",choices:["Gists permitem comentários, mas nunca histórico de revisões","Somente gists públicos podem conter código","Gists são repositórios Git que podem ser clonados e receber forks","Editar um gist exige convertê-lo em issue"],explanations:["Gists mantêm o histórico de revisões do Git.","Gists públicos e secretos podem conter código.","O Git sustenta os gists, permitindo histórico, clonagem e forks.","Um gist pode ser editado sem se tornar uma issue."],concept:"Histórico de gists",hints:["Um gist é apenas uma mensagem estática colada?","O que decorre de usar Git como base?"]},
    "ghf-116": {prompt:"Um repositório precisa de uma coleção navegável de páginas de documentação mantidas separadamente dos arquivos principais de código. Qual recurso foi projetado para isso?",choices:["Uma aprovação de pull request","Uma lista de ativos de releases","Um status de commit","Uma wiki do repositório"],explanations:["Uma aprovação é um resultado de revisão, não uma estrutura de documentação.","Ativos de releases distribuem downloads versionados.","Um status de commit informa o estado de uma verificação externa.","Wikis permitem documentação de repositório com várias páginas."],concept:"Wikis de repositórios",hints:["Um único arquivo introdutório é suficiente?","Qual recurso permite uma coleção de documentação?"]},
    "ghf-117": {prompt:"Uma equipe quer publicar um site estático de documentação a partir de arquivos do repositório. Qual recurso é mais adequado?",choices:["GitHub Pages","GitHub Issues","GitHub Sponsors","GitHub Mobile"],explanations:["Pages publica conteúdo de sites estáticos a partir de repositórios.","Issues acompanha trabalho e conversas.","Sponsors permite contribuições financeiras.","Mobile é um cliente de colaboração, não hospedagem estática."],concept:"GitHub Pages",hints:["A equipe precisa de um site publicado?","Separe a hospedagem de conteúdo das discussões do projeto."]},
    "ghf-118": {prompt:"Um site exige um processo Python do lado do servidor continuamente em execução para atender solicitações. O GitHub Pages oferece esse ambiente de execução?",choices:["Sim; usar Python na compilação também fornece um manipulador persistente de solicitações","Não; Pages oferece hospedagem estática, não um ambiente de servidor arbitrário","Sim; enviar código Python inicia automaticamente um serviço web","Sim; um domínio personalizado transforma Pages em hospedagem do lado do servidor"],explanations:["Executar na compilação não cria um backend continuamente ativo.","Pages publica ativos gerados, mas não hospeda processos persistentes arbitrários de servidor.","Publicar código não provisiona um manipulador Python de solicitações.","Um domínio personalizado muda o endereço, não o modelo de execução da hospedagem."],concept:"Limites da hospedagem Pages",hints:["Diferencie a geração na compilação da execução durante solicitações.","O que hospedagem estática significa para um backend?"]},
    "ghf-119": {prompt:"Uma discussão de suporte tem uma solução útil que leitores futuros devem encontrar rapidamente. Em uma categoria que permite respostas aceitas, qual ação a designa explicitamente?",choices:["Assinar a discussão","Adicionar somente uma reação de positivo","Marcar a resposta útil como a resposta aceita","Bloquear a discussão sem selecionar uma resposta"],explanations:["Assinar controla atualizações, não identifica a solução.","Uma reação expressa apreço sem designar a resposta.","Marcar uma resposta destaca a solução em categorias compatíveis.","Bloquear impede novas interações, mas não designa a resposta."],concept:"Respostas em Discussions",hints:["Qual é a diferença entre agradecer e identificar formalmente uma solução?","Qual ação registra o resultado da pergunta resolvida?"]},
    "ghf-120": {prompt:"Uma issue evoluiu para uma conversa ampla de design sem tarefa concreta. Como preservá-la em um formato mais adequado?",choices:["Excluir a issue e seu histórico de conversa","Fechar e bloquear sem indicar um destino para conversar","Abrir um pull request sem alterações propostas para servir de fórum","Converter a issue em discussão onde houver suporte"],explanations:["Excluir sacrifica a conversa em vez de preservá-la.","Bloquear encerra a participação sem movê-la para um formato melhor.","Pull requests destinam-se à revisão de alterações propostas.","A conversão de issue em discussão transfere a conversa aberta à ferramenta apropriada."],concept:"Mudança de tipos de conversa",hints:["A natureza do trabalho mudou?","Qual ferramenta permite melhor um diálogo exploratório?"]},
    "ghf-121": {prompt:"Uma discussão de revisão é marcada como resolvida. O que isso indica por si só?",choices:["Essa conversa é considerada atendida, não que todo o pull request esteja aprovado","Todas as verificações de status obrigatórias passaram","O pull request já foi mesclado","Todas as outras discussões de revisão estão resolvidas"],explanations:["A resolução se limita à conversa; a aprovação é um resultado de revisão separado.","O estado da conversa não informa a execução de testes.","Resolver uma discussão não mescla alterações.","Outras discussões mantêm seus próprios estados."],concept:"Escopo da resolução de discussões",hints:["Qual é o escopo da ação?","Separe o progresso da conversa da autorização para mesclar."]},
    "ghf-122": {prompt:"Uma pessoa quer abandonar uma alteração proposta sem aplicar seus commits à branch base. O que deve fazer?",choices:["Fazer squash e mesclar a proposta","Fechar o pull request sem mesclar","Marcar todos os arquivos como visualizados","Converter a proposta em rascunho e deixá-la aberta"],explanations:["Squash and merge ainda integra as alterações propostas.","Fechar sem mesclar encerra a proposta sem aplicá-la à base.","O estado visualizado apenas acompanha o progresso de revisão.","Um rascunho continua sendo uma proposta aberta, não expressa abandono."],concept:"Fechar versus mesclar",hints:["A branch de destino deve mudar?","Diferencie encerrar uma proposta de aceitá-la."]},
    "ghf-123": {prompt:"Solicita-se a revisão de alguém da equipe em um pull request. Como isso difere de atribuir o pull request a essa pessoa?",choices:["Solicitações de revisão concedem escrita; atribuições não","Atribuições contam como aprovações; solicitações são comentários opcionais","Solicitar revisão pede avaliação explicitamente; atribuir identifica responsabilidade","Ambos os controles sempre registram a mesma relação"],explanations:["Uma solicitação de revisão não concede permissão de escrita.","Uma atribuição não é um resultado de revisão enviado.","Revisão e atribuição expressam relações de colaboração diferentes.","O GitHub oferece controles separados porque os papéis diferem."],concept:"Revisor versus responsável",hints:["Responsabilidade sempre significa avaliar o diff?","Qual relação pede uma revisão formal?"]},
    "ghf-124": {prompt:"Uma pessoa aprova um pull request, mas uma verificação automatizada obrigatória está falhando. O que a pessoa autora deve concluir?",choices:["A aprovação substitui automaticamente todas as verificações","A falha é apenas uma preferência de notificação","A branch já foi mesclada","A aprovação e as verificações obrigatórias são condições de mesclagem separadas"],explanations:["Uma aprovação não ignora automaticamente verificações obrigatórias.","O resultado de uma verificação não é apenas uma configuração de assinatura.","A aprovação sozinha não mescla a branch.","Um repositório pode exigir tanto revisão satisfatória quanto verificações aprovadas."],concept:"Condições de revisão e verificações",hints:["Pode haver mais de uma condição para mesclar?","Separe o julgamento humano dos resultados automatizados."]},
    "ghf-125": {prompt:"Uma pessoa de engenharia precisa de uma visão cronológica dos commits com suas mensagens para investigar quando um comportamento mudou. Qual comando do Git atende a isso?",choices:["git log","git status","git remote -v","git add"],explanations:["Log exibe o histórico de commits registrado.","Status resume a árvore de trabalho e o índice atuais.","Remote -v lista URLs remotas.","Add prepara conteúdo em vez de exibir histórico registrado."],concept:"Inspeção do histórico de commits",hints:["A pergunta trata de edições atuais ou snapshots passados?","Qual saída incluiria mensagens históricas?"]}
    ,"ghf-126": {prompt:"Na terminologia do Git, o que HEAD normalmente identifica no trabalho com branches?",choices:["O commit mais antigo do repositório","A posição atual do checkout, geralmente pela branch atual","A URL remota usada no próximo push","Todas as alterações da área de preparação"],explanations:["HEAD não é uma referência fixa ao commit mais antigo.","HEAD identifica a posição atual do checkout e costuma apontar para a branch ativa.","URLs remotas são configuradas separadamente de HEAD.","O índice contém conteúdo preparado; HEAD identifica uma posição no histórico."],concept:"HEAD",hints:["O que identifica onde você está trabalhando agora?","Essa referência poderia se mover conforme novos commits são criados?"]},
    "ghf-127": {prompt:"Uma branch de funcionalidade tem novos commits após a criação de uma tag em um commit anterior. O que essa tag inalterada ainda identifica?",choices:["O commit mais recente de qualquer branch","O pull request aberto mais recente","O commit anterior marcado com a tag","A árvore de trabalho atual com arquivos não commitados"],explanations:["Tags não avançam automaticamente para os commits globalmente mais recentes.","Tags referem-se a objetos Git, não a listas de pull requests.","Uma tag inalterada continua marcando seu destino original.","Arquivos de trabalho não commitados não fazem parte do destino de uma tag."],concept:"Tags versus branches móveis",hints:["Qual referência é destinada a marcar uma versão?","Uma branch avançar implica que todas as referências avancem?"]},
    "ghf-128": {prompt:"Quer-se encontrar o commit mais recente que alterou cada linha de um arquivo. Qual visualização é mais útil?",choices:["Raw","Preview","A lista de branches do repositório","Blame"],explanations:["Raw mostra conteúdo sem atribuição de commits por linha.","Preview renderiza conteúdo compatível em vez de mostrar a origem da alteração de cada linha.","Nomes de branches não associam linhas a commits.","Blame associa as linhas aos commits que as alteraram mais recentemente."],concept:"Atribuição por linha",hints:["O objetivo é só o conteúdo ou também sua procedência?","Qual visualização liga linhas a alterações históricas?"]},
    "ghf-129": {prompt:"Uma equipe quer representar os muitos commits pequenos de um pull request com um único commit novo na branch base. Qual método habilitado atende a isso?",choices:["Squash and merge","Criar um commit de mesclagem sem squash","Fechar sem mesclar","Rebase and merge preservando commits separados"],explanations:["Squash combina as alterações propostas em um commit na base.","Uma mesclagem comum mantém os commits individuais e acrescenta um commit de mesclagem.","Fechar sozinho não integra alterações.","Rebase and merge reaplica commits separadamente, sem consolidá-los."],concept:"Mesclagem com squash",hints:["As divisões entre commits intermediários devem permanecer?","Qual método consolida o histórico em vez de apenas integrá-lo?"]},
    "ghf-130": {prompt:"Uma equipe quer executar testes sempre que um pull request for aberto ou atualizado. Qual capacidade deve configurar?",choices:["Um tópico de repositório","Um workflow do GitHub Actions","Somente uma lista estática no README","Uma resposta salva"],explanations:["Tópicos categorizam projetos sem executar testes.","Actions pode automatizar testes em resposta a eventos de pull requests.","Uma lista documenta a intenção, mas não executa testes.","Respostas salvas reutilizam texto em vez de executar automações."],concept:"Integração contínua",hints:["O que deve responder aos eventos do repositório?","Diferencie documentar uma tarefa de executá-la."]},
    "ghf-131": {prompt:"Onde um repositório normalmente armazena definições de workflows do GitHub Actions?",choices:["Somente na pasta local .git/hooks","No arquivo LICENSE","Como arquivos YAML em .github/workflows/","Como comentários em uma release"],explanations:["Hooks locais do Git não definem workflows hospedados do Actions.","LICENSE contém termos legais.","O GitHub descobre o YAML dos workflows em .github/workflows/.","Comentários de releases não são definições de workflows."],concept:"Localização de arquivos de workflow",hints:["O GitHub precisa descobrir configurações de automação versionadas?","Separe hooks locais de workflows hospedados."]},
    "ghf-132": {prompt:"No GitHub Actions, o que é um runner?",choices:["A pessoa atribuída a uma issue","Um rótulo para bugs urgentes","Uma lista reutilizável de Markdown","A máquina que executa um job"],explanations:["Pessoas atribuídas a issues não são infraestrutura de execução.","Um rótulo de urgência não executa comandos.","Uma lista registra tarefas, mas não é infraestrutura de execução.","Runners fornecem o ambiente computacional para jobs de workflows."],concept:"Runners do Actions",hints:["Onde os scripts realmente executam?","Separe metadados do workflow de recursos computacionais."]},
    "ghf-133": {prompt:"Um workflow contém etapas de checkout, instalação de dependências e testes em um job. O que essas etapas normalmente compartilham?",choices:["O ambiente do runner do job","Automaticamente o diretório de trabalho de todos os outros jobs","As credenciais de todos os proprietários da organização","Os arquivos não commitados do notebook da pessoa autora"],explanations:["Etapas de um job executam no mesmo ambiente do runner.","Jobs separados não compartilham diretórios de trabalho automaticamente.","Credenciais de proprietários não são fornecidas implicitamente.","Runners hospedados não recebem automaticamente o estado não commitado de um notebook."],concept:"Etapas em um job",hints:["Qual limite agrupa trabalho sequencial em um ambiente?","Não presuma que dados cruzem automaticamente os limites entre jobs."]},
    "ghf-134": {prompt:"Um job de implantação deve esperar um job de testes ser concluído com sucesso. Qual relação deve ser configurada?",choices:["Usar nomes de exibição idênticos","Declarar uma dependência com needs","Listar a implantação depois no YAML sem dependência","Apenas executar ambos com o mesmo rótulo de sistema operacional"],explanations:["Nomes não estabelecem dependências de execução.","Needs expressa a relação de pré-requisito entre jobs.","A ordem no YAML sozinha não torna jobs independentes sequenciais.","Sistemas operacionais iguais não criam uma relação de pré-requisito."],concept:"Dependências entre jobs",hints:["O que expressa um pré-requisito em vez de um rótulo?","Os jobs devem ser independentes?"]},
    "ghf-135": {prompt:"Uma biblioteca precisa executar o mesmo job de testes em várias versões de uma linguagem. Qual recurso evita duplicá-lo manualmente para cada versão?",choices:["Um fork","Um template de pull request","Uma estratégia de matriz","Uma regra de proprietários de código"],explanations:["Forks criam repositórios separados em vez de parametrizar jobs.","Templates orientam descrições de pull requests.","Uma matriz executa um job com diferentes combinações de variáveis.","Propriedade de código encaminha revisões, não combinações de execução."],concept:"Compilações em matriz",hints:["Qual parte do job varia entre execuções?","Procure combinações parametrizadas."]},
    "ghf-136": {prompt:"Uma etapa do Actions invoca um componente compartilhado com uses para configurar as ferramentas de uma linguagem. Como se chama esse componente reutilizável?",choices:["Um runner","Um evento","Uma matriz","Uma ação"],explanations:["Um runner fornece infraestrutura de execução, não o componente reutilizável de configuração.","Um evento aciona a execução de um workflow.","Uma matriz define combinações de variáveis de jobs.","Uma ação é um componente reutilizável invocado por etapas do workflow."],concept:"Ações reutilizáveis",hints:["O que uma etapa pode invocar em vez de código shell próprio?","Separe o componente de sua máquina de execução e do gatilho."]},
    "ghf-137": {prompt:"Um repositório quer automatizar rótulos de issues em vez de compilar software. GitHub Actions é uma opção adequada?",choices:["Sim; workflows podem responder a eventos além de compilações","Não; Actions só executa comandos de compilador","Não; eventos de issues não podem acionar automações","Somente se cada issue contiver código executável"],explanations:["Actions pode automatizar tarefas de repositório, como rotular issues.","Workflows podem executar muitos tipos de comandos e ações.","Eventos de issues compatíveis podem acionar workflows.","O conteúdo das issues não precisa ser executável."],concept:"Automação além de CI",hints:["A automação se limita à compilação?","Quais eventos de repositório podem iniciar um workflow?"]},
    "ghf-138": {prompt:"Um job exige hardware especializado em uma máquina operada pela empresa. Qual opção do Actions a equipe deve avaliar?",choices:["Um runner padrão hospedado pelo GitHub sem acesso àquela máquina","Um runner auto-hospedado","Uma variável de matriz que apenas nomeia o hardware","Uma descrição da máquina no workflow"],explanations:["Um runner hospedado padrão não se torna o hardware operado pela empresa.","Runners auto-hospedados permitem fornecer e gerenciar as próprias máquinas de execução.","Um valor de matriz sozinho não fornece hardware nem conecta um runner.","Documentar uma máquina não a registra como ambiente de execução."],concept:"Runners auto-hospedados",hints:["Quem precisa controlar a infraestrutura de execução?","Separe selecionar recursos de apenas descrevê-los."]},
    "ghf-139": {prompt:"Precisa-se da saída de erro de uma etapa de testes do Actions com falha. Onde ela deve ser examinada?",choices:["Somente na mensagem da pessoa autora do commit","Somente no nome do arquivo do workflow","Nos logs do job e da etapa da execução correspondente","Somente na execução bem-sucedida de uma revisão anterior"],explanations:["Uma mensagem de commit não é a saída atual de execução.","O nome do arquivo não revela a saída do comando que falhou.","Logs de execução expõem os comandos e erros da etapa com falha.","Uma execução anterior bem-sucedida não fornece a saída da falha atual."],concept:"Diagnóstico de workflows",hints:["Onde a saída de execução é registrada?","Concentre-se na execução específica que falhou."]},
    "ghf-140": {prompt:"Ao escrever uma função em um editor compatível, uma pessoa quer sugestões de código geradas por IA. Qual ferramenta foi projetada para isso?",choices:["GitHub Pages","GitHub Sponsors","Somente GitHub Projects","GitHub Copilot"],explanations:["Pages publica sites estáticos.","Sponsors fornece apoio financeiro.","Projects acompanha trabalho, não gera sugestões no editor.","Copilot oferece assistência de programação com IA em ambientes compatíveis."],concept:"Sugestões do Copilot",hints:["A tarefa é assistência de programação ou acompanhamento de trabalho?","Qual ferramenta se integra à experiência de programação do editor?"]},
    "ghf-141": {prompt:"Copilot sugere uma implementação plausível de uma função auxiliar de autenticação. O que fazer antes de aceitá-la em produção?",choices:["Revisar seu comportamento e validá-lo com testes e verificações de segurança adequados","Presumir que o código gerado já passou nos testes do projeto","Pular a revisão porque a instrução era detalhada","Tratar a explicação como certificação de segurança"],explanations:["A pessoa desenvolvedora continua responsável por avaliar alterações geradas.","Sugestões não comprovam que os testes do projeto foram executados com sucesso.","O detalhamento da instrução não elimina obrigações de revisão.","Uma explicação de IA não certifica segurança."],concept:"Validação responsável de IA",hints:["Quem responde pelo código mesclado?","Que evidência validaria uma sugestão?"]},
    "ghf-142": {prompt:"Uma pessoa de engenharia pede ao Copilot que explique uma função desconhecida e depois faz perguntas de acompanhamento. Qual interação é a mais adequada?",choices:["Somente aceitar uma conclusão de código inline","Copilot Chat","Somente examinar um resumo de revisão sem conversa","Somente aplicar um trecho predefinido do editor"],explanations:["Uma conclusão inline sugere código, mas não oferece sozinha o diálogo descrito.","Chat permite perguntas em conversa e explicações de acompanhamento.","Um resumo fixo não fornece o diálogo explicativo contínuo solicitado.","Um trecho predefinido não é assistência conversacional contextual."],concept:"Copilot Chat",hints:["O fluxo envolve diálogo?","Diferencie uma explicação interativa de inserir código."]},
    "ghf-143": {prompt:"Quer-se um fluxo do Copilot no IDE capaz de localizar arquivos, editar vários deles, executar comandos e validar o resultado sob supervisão. Qual capacidade atende a isso?",choices:["Somente uma conclusão inline","Uma resposta salva de issue","Modo agente","Um selo estático no README"],explanations:["Uma conclusão inline sozinha não é um fluxo de várias etapas com ferramentas.","Respostas salvas reutilizam texto em vez de alterar código.","O modo agente pode combinar investigação, edições e execução de comandos sob supervisão.","Selos exibem informações, mas não implementam alterações."],concept:"Modo agente do Copilot",hints:["Quanto da tarefa está sendo delegado?","São necessárias ferramentas além de prever o próximo trecho de código?"]},
    "ghf-144": {prompt:"Delega-se uma alteração de repositório ao agente na nuvem do Copilot. Onde ele pode realizar a implementação?",choices:["Somente no terminal local aberto da pessoa mantenedora","Somente em um editor de navegador sem computação","Somente na visualização renderizada de diff do pull request","Em um ambiente efêmero de desenvolvimento na nuvem com ferramentas de edição e testes"],explanations:["O agente na nuvem não precisa usar o terminal local da pessoa mantenedora como ambiente de execução.","Um editor somente de navegador não fornece o ambiente de execução na nuvem do agente.","O diff renderizado mostra alterações propostas, não executa ferramentas de implementação.","O agente pode editar e executar ferramentas na nuvem para revisão posterior."],concept:"Agente de programação na nuvem",hints:["Qual ambiente é necessário para editar e executar testes?","Separe delegação na nuvem de um editor leve no navegador."]},
    "ghf-145": {prompt:"Uma organização quer atribuir acesso ao Copilot centralmente e controlar políticas para membros em vez de gerenciar assinaturas individuais separadas. Qual família de planos atende a isso?",choices:["Copilot Business ou Copilot Enterprise","Contas Copilot Free gerenciadas separadamente por cada usuário","Assinaturas individuais Copilot Pro sem licenciamento organizacional","Somente um plano de repositório GitHub sem licenciamento do Copilot"],explanations:["Business e Enterprise fornecem gerenciamento organizacional do Copilot.","Contas Free separadas não oferecem a administração centralizada solicitada.","Assinaturas individuais independentes não são o modelo de gerenciamento organizacional.","Um plano de repositório sozinho não estabelece licenciamento organizacional do Copilot."],concept:"Planos organizacionais do Copilot",hints:["Quem precisa administrar o acesso?","Separe uso pessoal de uma implantação com governança centralizada."]},
    "ghf-146": {prompt:"Como distinguir Copilot Enterprise de Copilot Business de forma estável e em alto nível?",choices:["Business é apenas um cliente Git local","Enterprise amplia Business para empresas que usam GitHub Enterprise Cloud","Enterprise elimina a revisão humana de código","Business não pode ter controles de políticas organizacionais"],explanations:["Business é um plano organizacional do Copilot, não um cliente Git.","Enterprise inclui capacidades de Business e destina-se a clientes do GitHub Enterprise Cloud.","Nenhum plano elimina a revisão do trabalho gerado.","Business inclui gerenciamento centralizado e controles de políticas."],concept:"Copilot Business versus Enterprise",hints:["Evite comparar preços ou cotas temporários.","Qual plano adiciona capacidades empresariais a uma base organizacional?"]},
    "ghf-147": {prompt:"Uma pessoa pode escolher entre modelos de chat compatíveis do Copilot. Qual afirmação descreve melhor essa capacidade?",choices:["Todo modelo deve ser habilitado para toda conta","Escolher o modelo garante uma resposta correta","Os modelos disponíveis podem variar por plano, cliente e política organizacional","Mudar o modelo mescla automaticamente todas as sugestões"],explanations:["A disponibilidade depende de restrições do produto e das políticas.","Selecionar um modelo não garante correção.","O plano, a interface de uso e as configurações da organização podem afetar as opções.","Selecionar um modelo não autoriza mesclagens."],concept:"Suporte a múltiplos modelos",hints:["O que determina as opções oferecidas?","Separe flexibilidade de garantias de correção."]},
    "ghf-148": {prompt:"Uma pessoa muda o modelo selecionado no Copilot Chat. O que deve concluir sobre o modelo das sugestões inline?",choices:["Ele deve mudar para o mesmo modelo","As sugestões inline ficam desativadas até o fim do chat","A configuração do chat sempre substitui a configuração do modelo inline","A seleção do chat não altera sozinha o modelo de sugestões inline"],explanations:["As configurações de modelos de chat e inline são separadas.","Trocar o modelo de chat não desativa inerentemente sugestões inline.","O seletor do chat não substitui a configuração inline separada.","A troca documentada do modelo de chat não afeta o modelo de sugestões inline."],concept:"Modelos de chat versus conclusão",hints:["Chat e sugestões inline são a mesma interface de interação?","Verifique o escopo da configuração alterada."]},
    "ghf-149": {prompt:"Uma pessoa pede ajuda ao Copilot Chat para escrever testes de um analisador desconhecido. Qual contexto ajudaria mais diretamente a sugerir testes relevantes?",choices:["O comportamento esperado, os casos extremos e as convenções de testes do projeto","Somente o nome do arquivo, sem conteúdo nem comportamento","Somente a quantidade de arquivos de testes existentes","Somente um pedido para maximizar linhas sem descrever resultados esperados"],explanations:["Expectativas de comportamento e contexto do projeto orientam sugestões úteis.","Um nome de arquivo raramente explica o comportamento esperado.","A contagem de arquivos não descreve o que o analisador deve fazer.","O volume de testes sozinho não define verificações significativas de correção."],concept:"Contexto para assistência de IA",hints:["Qual informação define se o resultado do analisador está correto?","Diferencie contexto útil de comportamento de métricas de volume."]},
    "ghf-150": {prompt:"Uma pessoa nova no projeto precisa de um ambiente de desenvolvimento na nuvem que possa compilá-lo e executá-lo. Qual recurso atende a isso?",choices:["Um site GitHub Pages","GitHub Codespaces","Um gist secreto","Uma lista de estrelas"],explanations:["Pages serve conteúdo estático, não um ambiente geral de desenvolvimento.","Codespaces fornece ambientes de desenvolvimento na nuvem com computação para execução.","Um gist compartilha trechos.","Listas de estrelas organizam favoritos."],concept:"Finalidade do Codespaces",hints:["A tarefa exige computação além de edição?","Qual opção é um ambiente de desenvolvimento?"]}
    ,"ghf-151": {prompt:"Uma equipe quer que novos codespaces incluam os mesmos ambientes de execução, extensões e configuração. O que deve versionar no repositório?",choices:["Somente instruções manuais sem configuração de ambiente","Somente as preferências pessoais de editor de uma pessoa contribuinte","Uma configuração de contêiner de desenvolvimento","Somente um arquivo GitHub Actions que execute testes em runners hospedados"],explanations:["Instruções ajudam pessoas, mas não configuram codespaces novos automaticamente.","Preferências pessoais não definem o ambiente comum da equipe.","A configuração do contêiner de desenvolvimento define um ambiente repetível do projeto.","Um workflow de testes do Actions não define o ambiente de desenvolvimento de um codespace."],concept:"Ambientes de desenvolvimento repetíveis",hints:["A configuração pode ser expressa como código?","O que um ambiente novo deve ler ao iniciar?"]},
    "ghf-152": {prompt:"Qual arquivo costuma ser a configuração principal do contêiner de desenvolvimento de um repositório?",choices:["package.json","Dockerfile",".github/workflows/build.yml",".devcontainer/devcontainer.json"],explanations:["Package.json descreve um pacote e scripts, não toda a configuração do contêiner de desenvolvimento.","Um Dockerfile pode definir a imagem, mas é referenciado pela configuração principal do contêiner.","O YAML de workflow define automação do Actions, não um contêiner de desenvolvimento.","Devcontainer.json define configurações do contêiner de desenvolvimento nessa localização comum."],concept:"Arquivo de configuração do contêiner de desenvolvimento",hints:["Qual configuração pode referenciar uma imagem e ajustes do editor juntos?","Diferencie a definição do ambiente de um de seus componentes."]},
    "ghf-153": {prompt:"Um repositório não tem configuração personalizada de contêiner de desenvolvimento. O que acontece ao criar um codespace compatível a partir dele?",choices:["Codespaces usa uma configuração padrão de contêiner de desenvolvimento","A criação sempre falha apenas pela ausência de devcontainer.json","O codespace copia todo o sistema operacional local de quem o cria","Ele muda para github.dev sem ambiente computacional"],explanations:["Uma imagem e configuração padrão permitem começar sem personalização.","Uma configuração personalizada não é obrigatória para criar o ambiente.","Codespaces não clona o sistema operacional local da pessoa.","O padrão ainda fornece um codespace com computação, não apenas o editor de navegador."],concept:"Ambiente padrão do Codespaces",hints:["A configuração personalizada é obrigatória?","Considere um ambiente básico para quem está começando."]},
    "ghf-154": {prompt:"Altera-se a imagem e a configuração de instalação em devcontainer.json. Qual ação aplica isso ao contêiner de um codespace existente?",choices:["Somente atualizar a aba do navegador","Reconstruir o contêiner de desenvolvimento","Somente commitar o arquivo sem recriar o contêiner","Somente reconectar ao contêiner em execução inalterado"],explanations:["Atualizar o cliente não recria o ambiente com a nova configuração.","Reconstruir aplica as alterações relevantes de configuração do contêiner.","Um commit registra a configuração, mas não reconstrói sozinho o contêiner existente.","Reconectar sozinho não aplica uma nova imagem e configuração."],concept:"Aplicação da configuração de contêiner",hints:["Editar a configuração necessariamente recria um ambiente em execução?","Qual ação do ciclo de vida aplica a nova configuração?"]},
    "ghf-155": {prompt:"Quer-se um editor de navegador para editar texto rapidamente e fazer um commit sem provisionar uma máquina de desenvolvimento. Qual opção atende a isso?",choices:["Uma nova máquina virtual do Codespaces","Um runner auto-hospedado do Actions","O editor web github.dev","Um novo clone local aberto em um editor de desktop"],explanations:["Um codespace provisiona computação além do requisito de apenas editar.","Um runner executa automação, não fornece esse editor de navegador.","Github.dev oferece edição leve no navegador e controle de código-fonte.","Um clone local não é o fluxo de edição apenas no navegador solicitado."],concept:"Caso de uso do github.dev",hints:["Computação remota é necessária?","Escolha a ferramenta cujo escopo corresponda apenas à edição."]},
    "ghf-156": {prompt:"Uma pessoa abre github.dev e depois precisa de um terminal interativo para compilar o projeto. Qual próximo passo atende melhor a isso?",choices:["Continuar no editor de navegador e esperar um runner aparecer automaticamente","Abrir uma segunda aba de github.dev para fornecer computação","Somente mudar a linguagem de realce de sintaxe do editor","Migrar para um ambiente com computação, como Codespaces"],explanations:["O editor somente de navegador não provisiona automaticamente um runner de desenvolvimento.","Outra aba do editor não cria um ambiente computacional.","O realce muda a apresentação, não fornece um ambiente de execução.","Codespaces fornece um ambiente de execução de desenvolvimento, ao contrário do editor somente de navegador."],concept:"github.dev versus Codespaces",hints:["Onde a compilação executaria?","Diferencie um editor de uma máquina completa de desenvolvimento."]},
    "ghf-157": {prompt:"Uma pessoa edita no github.dev e ainda não fez commit. Qual consideração de persistência é importante?",choices:["O trabalho não commitado fica no armazenamento do navegador, por isso é importante fazer commits regularmente","Cada tecla já é um commit enviado por push","As edições já existem em uma branch remota oculta","Sair da conta necessariamente faz commit de todas as edições pendentes"],explanations:["O editor guarda o trabalho localmente até os commits preservarem-no no histórico do repositório.","Editar não equivale a registrar e publicar um commit.","Não se deve presumir que trabalho não commitado no navegador exista no histórico remoto.","Sair da conta não é uma operação de commit."],concept:"Persistência do editor de navegador",hints:["Foi criado um commit no repositório?","O que pode acontecer se os dados locais do navegador forem perdidos?"]},
    "ghf-158": {prompt:"Um codespace executa uma aplicação web que se quer visualizar no navegador. Qual recurso de desenvolvimento é relevante?",choices:["Somente fazer push da branch de código ao GitHub","Encaminhamento de portas","Somente abrir o arquivo de código da aplicação no editor","Somente baixar o repositório como ZIP"],explanations:["Publicar código não expõe o serviço em execução do codespace.","Encaminhar uma porta torna um serviço do codespace acessível para visualização.","Ver código não conecta o navegador ao processo em execução.","Um arquivo compactado não é um endpoint de rede do codespace."],concept:"Encaminhamento de portas do Codespaces",hints:["Como o navegador pode alcançar o processo em execução?","Separe publicação de código de um endpoint de serviço de desenvolvimento."]},
    "ghf-159": {prompt:"Uma pessoa quer preferências pessoais de shell em seus codespaces sem torná-las configurações obrigatórias para todo o projeto. O que deve considerar?",choices:["Adicionar todos os aliases pessoais à configuração compartilhada","Usar somente as cores do editor para configurar aliases de shell","Um repositório pessoal de dotfiles","Configurar o runner do Actions em vez de seus codespaces"],explanations:["A configuração compartilhada imporia preferências pessoais a outras pessoas.","Cores do editor não configuram aliases de shell.","Codespaces pode usar dotfiles pessoais para preferências de shell e ferramentas.","Um runner do Actions é um ambiente diferente do codespace da pessoa."],concept:"Personalização do Codespaces",hints:["A preferência é pessoal ou do projeto inteiro?","Como a configuração de shell pode acompanhar a pessoa?"]},
    "ghf-160": {prompt:"Uma organização quer um único espaço de planejamento para issues e pull requests de vários repositórios. Qual recurso atende a isso?",choices:["Somente um marco de um repositório","Somente a lista de rótulos de um repositório","O resumo de revisão de um pull request","Um GitHub Project no nível da organização"],explanations:["Um marco de repositório não agrega itens de outros repositórios.","Definições de rótulos de um repositório não fornecem planejamento entre repositórios.","Um resumo de revisão trata de uma única alteração proposta.","Projects pode organizar trabalho de vários repositórios no nível da organização."],concept:"Planejamento entre repositórios",hints:["O escopo é maior que um repositório?","Qual recurso reúne trabalho sem copiar seu código?"]},
    "ghf-161": {prompt:"Uma pessoa planejadora quer examinar muitos itens e editar valores de campos em linhas e colunas. Qual layout de Project é mais adequado?",choices:["Table","Board","Roadmap","O diff de um arquivo"],explanations:["Table apresenta dados de itens de trabalho em linhas e colunas densas.","Board enfatiza cartões agrupados em colunas.","Roadmap enfatiza datas em uma linha do tempo.","Um diff compara alterações de arquivos, não metadados de projeto."],concept:"Layout de tabela do Project",hints:["Qual disposição se parece com registros estruturados?","A necessidade principal é editar campos ou ver uma linha do tempo?"]},
    "ghf-162": {prompt:"Uma equipe quer mover cartões entre as colunas Todo, In progress e Done. Qual layout de Project permite melhor esse fluxo visual?",choices:["Roadmap","Board","Somente Table","Uma página de ativos de release"],explanations:["Roadmap exibe itens em uma linha do tempo.","Board apresenta cartões agrupados por um campo como Status.","Table serve para linhas e campos, mas não é o layout de cartões solicitado.","Ativos de releases distribuem arquivos, não acompanham o movimento de cartões."],concept:"Layout de quadro do Project",hints:["Como os grupos de status devem ser representados?","Qual layout enfatiza cartões em vez de datas?"]},
    "ghf-163": {prompt:"Uma pessoa líder de produto quer visualizar datas planejadas de início e de entrega em uma linha do tempo. Qual layout deve escolher?",choices:["Board","Table","Roadmap","Um gráfico de contagem por status em vez de uma linha do tempo por item"],explanations:["Board enfatiza categorias, não intervalos de tempo.","Table lista campos, mas não oferece o layout de linha do tempo.","Roadmap organiza trabalho em uma linha do tempo usando datas.","Um gráfico por status agrega itens em vez de exibir seus intervalos programados."],concept:"Layout de roteiro do Project",hints:["A dimensão central é categoria ou tempo?","Qual visualização torna cronogramas sobrepostos visíveis?"]},
    "ghf-164": {prompt:"Um projeto precisa de um campo Priority restrito a Low, Medium ou High. Qual tipo de campo personalizado é mais adequado?",choices:["Texto livre","Um campo de data","Um campo numérico","Single select"],explanations:["Texto permite valores arbitrários em vez de impor as opções pretendidas.","Uma data representa valores de calendário.","Números não representam diretamente essas categorias nomeadas.","Campos de seleção única fornecem um conjunto definido de opções."],concept:"Campos de seleção única",hints:["As pessoas devem escolher de um vocabulário controlado?","Escolha o tipo de campo conforme a espécie de valor."]},
    "ghf-165": {prompt:"Uma equipe planeja trabalho em períodos repetidos e quer um campo de Project que represente esses ciclos, incluindo pausas. Qual tipo é destinado a isso?",choices:["Iteration","Text","Assignee","Label"],explanations:["Campos de iteração representam períodos repetidos de planejamento e podem incluir pausas.","Texto não modela inerentemente ciclos recorrentes.","Responsáveis identificam pessoas.","Rótulos categorizam trabalho, não definem períodos de planejamento."],concept:"Planejamento por iterações",hints:["O valor representa um período recorrente?","Diferencie uma estrutura de programação temporal de uma categoria."]},
    "ghf-166": {prompt:"A visualização de triagem deve mostrar apenas itens urgentes, preservando todo o backlog. O que a equipe deve configurar?",choices:["Excluir todas as issues não urgentes","Uma visualização filtrada","Remover do Project todos os itens não urgentes","Ordenar por urgência exibindo todos os itens"],explanations:["Excluir trabalho destrói o backlog em vez de preservá-lo.","Filtrar muda os itens exibidos sem excluir o backlog.","Remover itens altera o backlog subjacente do Project.","Ordenar muda a ordem, não limita a visualização ao trabalho urgente."],concept:"Visualizações filtradas de projetos",hints:["O trabalho oculto deve ser excluído?","Como mudar a apresentação sem mudar o conjunto subjacente?"]},
    "ghf-167": {prompt:"Duas partes interessadas querem disposições salvas diferentes dos mesmos itens de Project. O que devem usar?",choices:["Issues copiadas independentes para cada parte","Uma visualização sobrescrita sem alternativas salvas","Várias visualizações salvas do projeto","Credenciais separadas de uma única conta compartilhada"],explanations:["Cópias duplicam desnecessariamente o acompanhamento do trabalho.","Sobrescrever uma única visualização não preserva ambas as perspectivas.","Visualizações salvas mantêm filtros, layouts e disposições diferentes dos mesmos itens.","Credenciais compartilhadas não são um mecanismo de gerenciamento de visualizações."],concept:"Visualizações salvas",hints:["Os itens de trabalho precisam ser duplicados?","Separe os dados das formas de examiná-los."]},
    "ghf-168": {prompt:"Uma issue já adicionada a um Project é atribuída a outra pessoa pela interface do Project. O que acontece com a atribuição da issue vinculada?",choices:["Ela sempre permanece igual porque Projects são cópias desconectadas","Uma issue duplicada é criada automaticamente para a nova pessoa","Ela muda somente após a mesclagem de um pull request","A atribuição também se reflete na issue"],explanations:["Metadados de issues vinculadas são sincronizados, não cópias desconectadas.","Editar o campo não exige duplicação.","A sincronização de atribuição não depende de uma mesclagem de código.","Projects sincroniza metadados compartilhados da issue nos dois sentidos."],concept:"Sincronização entre Project e issue",hints:["O item do Project é uma cópia desconectada?","Quais campos pertencem à própria issue vinculada?"]},
    "ghf-169": {prompt:"Uma ideia de planejamento pertence a um Project, mas ainda não está pronta para ser uma issue de repositório. O que a equipe pode adicionar inicialmente?",choices:["Uma issue em rascunho no Project","Uma issue que deve ser imediatamente atribuída a um repositório","Um pull request em rascunho sem alterações propostas","Um marco usado como se fosse um item individual de Project"],explanations:["Issues em rascunho permitem guardar trabalho preliminar no Project antes de convertê-lo em issues de repositório.","Uma issue de repositório exige a escolha de repositório que está sendo adiada.","Um pull request em rascunho propõe alterações de código, não representa uma ideia de planejamento sem escopo definido.","Marcos agrupam issues e pull requests de repositório, não cumprem essa função de item em rascunho."],concept:"Issues em rascunho do Project",hints:["O planejamento pode preceder a escolha de um repositório?","Qual tipo de item foi projetado para trabalho preliminar?"]},
    "ghf-170": {prompt:"Uma equipe quer que Status de um item do Project mude para Done quando sua issue vinculada fechar. Qual capacidade integrada relevante é a mais simples?",choices:["Uma visualização salva que apenas ordene por Status","Um workflow de automação do Project","Um rótulo Done criado manualmente sem automação","Uma resposta salva pedindo a atualização de Status"],explanations:["Ordenar muda a apresentação, não reage a eventos do ciclo de vida.","Workflows integrados podem atualizar o status em resposta a eventos do ciclo de vida de issues.","Um rótulo sozinho não atualiza o campo Status separado do Project.","Uma resposta pode pedir trabalho, mas não automatiza a atualização do campo."],concept:"Workflows integrados do Project",hints:["Qual evento deve atualizar qual campo?","Procure automação voltada a itens de planejamento."]},
    "ghf-171": {prompt:"Quer-se que novas issues correspondentes a um filtro de repositório entrem automaticamente em um Project. Qual capacidade deve ser configurada?",choices:["Somente um filtro salvo de itens já no Project","Somente um workflow que marque Done itens existentes ao fechar","Um workflow de adição automática","Somente um workflow de arquivamento automático"],explanations:["Um filtro de visualização não adiciona issues correspondentes ausentes do Project.","Um workflow de conclusão trata do status existente, não da entrada de itens.","Workflows de adição automática adicionam ao Project itens correspondentes de repositórios.","O arquivamento automático remove itens do planejamento ativo em vez de adicionar novos."],concept:"Entrada automática em projetos",hints:["A entrada precisa responder a trabalho futuro correspondente?","Diferencie um filtro de exibição de uma automação que adiciona itens."]},
    "ghf-172": {prompt:"Uma issue deve ter as categorias bug e accessibility. Qual mecanismo foi projetado para aplicar essas classificações reutilizáveis?",choices:["Um marco para cada categoria nessa issue","Tópicos de repositório aplicados à issue","Uma pessoa responsável para cada categoria","Rótulos"],explanations:["Marcos agrupam entregas; uma issue não usa vários marcos como etiquetas de categorias.","Tópicos classificam repositórios, não issues individuais.","Responsáveis identificam pessoas, não categorias.","Rótulos categorizam issues e pull requests e podem ser combinados."],concept:"Rótulos",hints:["São categorias ou identidades responsáveis?","O mesmo item pode pertencer a várias classificações?"]},
    "ghf-173": {prompt:"Um repositório quer agrupar issues e pull requests de uma versão planejada e acompanhar o progresso coletivo até uma data limite. Qual recurso atende a isso?",choices:["Um marco","Um tópico de repositório","Uma assinatura Watch","Um comentário individual de revisão"],explanations:["Marcos agrupam itens de trabalho e permitem acompanhar progresso e datas limite.","Tópicos classificam o repositório inteiro.","Watch controla atualizações entregues a uma pessoa.","Um comentário de revisão não agrupa trabalho de uma versão."],concept:"Marcos",hints:["O grupo está ligado a um objetivo de entrega?","Qual recurso resume o progresso do trabalho relacionado?"]},
    "ghf-174": {prompt:"Uma pessoa de suporte publica repetidamente a mesma solicitação de diagnóstico e quer texto reutilizável para inserir e adaptar. Qual recurso é destinado a isso?",choices:["Uma regra de branch","Respostas salvas","Uma tag de commit","Um campo de data de projeto"],explanations:["Regras de branches governam alterações no repositório.","Respostas salvas armazenam respostas de comentários reutilizáveis.","Tags identificam revisões.","Campos de data guardam datas de planejamento, não templates de resposta."],concept:"Respostas salvas",hints:["Qual trabalho repetido está sendo reduzido?","Separe texto reutilizável de conversa de automação do repositório."]},
    "ghf-175": {prompt:"Uma equipe quer deixar claro quem é responsável pelo acompanhamento de uma issue específica. Qual campo deve usar?",choices:["Somente Labels","Milestone","Assignees","A iteração do Project"],explanations:["Rótulos classificam trabalho, mas não são o campo de responsabilidade pessoal.","Um marco identifica um agrupamento de entrega.","Assignees comunica quem é responsável pelo trabalho na issue.","Uma iteração identifica um período de planejamento, não uma pessoa responsável."],concept:"Responsabilidade por issues",hints:["Quais metadados identificam responsáveis pelo acompanhamento?","Não confunda responsabilidade com categoria ou cronograma."]}
    ,"ghf-176": {prompt:"Uma pessoa gerente quer gráficos da distribuição do trabalho do Project por status, sem tratar contagens brutas de atividade como medida completa do desempenho de funcionários. Qual recurso atende a isso?",choices:["Estatísticas de tráfego do repositório","Blame de um único arquivo","Somente o calendário pessoal de contribuições","Insights do Project"],explanations:["Tráfego mede visitas, não a distribuição de status do Project.","Blame atribui linhas de arquivos a commits.","Um calendário de contribuições não representa os campos dos itens do Project.","Insights do Project visualiza dados de itens; a interpretação ainda precisa de contexto."],concept:"Insights do Project",hints:["Onde os dados relevantes de planejamento já estão organizados?","O que um gráfico mostra e o que não comprova?"]},
    "ghf-177": {prompt:"Uma equipe quer manter itens concluídos como registros arquivados do Project, não ativos, sem excluir suas issues do repositório. Qual ação atende a isso?",choices:["Arquivar os itens do Project","Excluir os itens do Project em vez de arquivar","Apenas ocultar a coluna Status","Arquivar todo o repositório"],explanations:["Arquivar itens preserva-os como registros arquivados fora das visualizações ativas.","Excluir não os mantém como registros de arquivo do Project.","Ocultar uma coluna não altera o estado de arquivamento do item.","Arquivar o repositório muda todo o repositório, não itens específicos do Project."],concept:"Arquivamento de itens de projeto",hints:["Os registros de planejamento devem continuar recuperáveis?","Qual escopo precisa de uma mudança de ciclo de vida?"]},
    "ghf-178": {prompt:"Por que adicionar autenticação de dois fatores fortalece uma conta protegida por senha?",choices:["Isso torna públicos os repositórios da conta","Isso exige um fator de autenticação adicional à senha","Isso impede todos os ataques possíveis de phishing","Isso substitui todas as permissões de repositório"],explanations:["Autenticação não determina visibilidade de repositório.","Um fator adicional reduz a dependência de possuir apenas a senha.","Alguns métodos de segundo fator ainda podem sofrer phishing.","Autorização continua separada da autenticação."],concept:"Autenticação de dois fatores",hints:["E se alguém descobrir a senha?","Diferencie comprovar identidade de conceder acesso."]},
    "ghf-179": {prompt:"Uma pessoa com 2FA entra no GitHub usando uma chave de acesso (passkey) registrada. Qual afirmação está correta?",choices:["Ela deve publicar a chave privada no perfil","Ela deve desativar a 2FA primeiro","A passkey pode atender tanto ao requisito de senha quanto ao de 2FA","Passkeys são apenas rótulos de senhas salvas"],explanations:["Chaves privadas devem permanecer protegidas pelo autenticador.","Passkeys podem ser usadas com 2FA habilitada.","Passkeys do GitHub podem concluir os requisitos de entrada em uma etapa.","Elas usam criptografia de chave pública, não apenas renomeiam senhas."],concept:"Entrada com passkey",hints:["Como o GitHub trata uma passkey para alguém com 2FA?","Separe uma credencial criptográfica de uma senha armazenada."]},
    "ghf-180": {prompt:"O que torna passkeys resistentes a páginas comuns de phishing de credenciais?",choices:["A pessoa deve colar a chave privada em cada formulário de entrada","O mesmo código reutilizável funciona em todos os domínios","Elas eliminam a necessidade de verificar o serviço acessado","Elas são vinculadas ao domínio do site legítimo"],explanations:["Uma passkey não exige expor a chave privada em um formulário.","Passkeys não são códigos universais reutilizáveis.","A vinculação ao domínio é justamente uma proteção de identidade do serviço.","Autenticadores vinculam a credencial ao domínio, resistindo a sites imitadores."],concept:"Resistência de passkeys a phishing",hints:["Um site imitador poderia usar o mesmo procedimento de credenciais?","Pense na relação entre credencial e identidade do serviço."]},
    "ghf-181": {prompt:"Uma pessoa habilita 2FA e quer reduzir o risco de perder acesso se perder o celular. O que deve fazer?",choices:["Guardar códigos de recuperação com segurança e configurar alternativas adequadas","Publicar códigos de recuperação em uma issue","Confiar apenas em lembrar a URL do repositório","Compartilhar a senha com toda a equipe"],explanations:["Material de recuperação protegido e métodos alternativos permitem recuperar a conta.","Publicar códigos expõe a capacidade de recuperação da autenticação.","Uma URL não comprova controle da conta.","Compartilhar senha enfraquece a segurança e não substitui uma recuperação bem configurada."],concept:"Preparação para recuperar contas",hints:["Qual método confiável resta se o dispositivo principal for perdido?","Mantenha material de recuperação separado da colaboração pública."]},
    "ghf-182": {prompt:"Uma equipe precisa de um repositório que qualquer pessoa na internet possa ler sem convite. Qual visibilidade atende a isso?",choices:["Private","Public","Somente Internal","Visibilidade de gist secreto"],explanations:["Repositórios privados exigem acesso adequado.","Repositórios públicos podem ser lidos por qualquer pessoa na internet.","A visibilidade interna se limita a uma empresa, não à internet inteira.","Gist secreto não é uma visibilidade de repositório e significa não listado, não privado por convite."],concept:"Visibilidade pública",hints:["Quem é o público leitor pretendido?","Diferencie acesso empresarial de acesso para toda a internet."]},
    "ghf-183": {prompt:"Uma equipe quer arquivos confidenciais legíveis somente por pessoas autorizadas, não por toda a empresa ou internet. Qual visibilidade é o melhor ponto de partida?",choices:["Public","Internal","Private","Com estrela"],explanations:["Public permite leitura em toda a internet.","Internal permite leitura mais ampla por membros da empresa.","Private restringe o acesso a pessoas autorizadas, sujeito ao acesso administrativo.","Estrela é um estado de favorito, não um limite de visibilidade."],concept:"Visibilidade privada",hints:["Quão amplo deve ser o público leitor?","Escolha um limite de acesso, não um favorito pessoal."]},
    "ghf-184": {prompt:"Uma empresa habilita repositórios internos. Qual é o escopo de visibilidade pretendido?",choices:["Todos os visitantes anônimos da internet","Somente quem criou cada repositório","Somente membros de um clone Git local","Membros da empresa, não o público geral"],explanations:["Internal não é visibilidade pública na internet.","Repositórios internos têm alcance maior que apenas a pessoa criadora.","Clones locais não definem a visibilidade hospedada.","A visibilidade interna permite leitura empresarial dentro do limite empresarial documentado."],concept:"Visibilidade interna",hints:["Qual limite organizacional interno descreve?","Separe a participação na empresa do acesso anônimo."]},
    "ghf-185": {prompt:"A permissão de ler um repositório público permite automaticamente fazer push de commits diretamente nele?",choices:["Não; o acesso de escrita é uma permissão separada","Sim; público significa modificação irrestrita","Sim, após marcar com estrela","Sim, após baixar um ZIP"],explanations:["A visibilidade concede leitura; modificar diretamente depende de autorização.","Leitura pública não concede direitos de escrita direta.","Estrelas não elevam permissões.","Baixar não altera a autorização."],concept:"Visibilidade versus escrita",hints:["Ler e modificar são a mesma capacidade?","Considere por que pessoas externas usam pull requests."]},
    "ghf-186": {prompt:"Uma pessoa que não contribui com código precisa ler e conversar em um repositório de organização, sem gerenciar issues nem fazer push. Qual função padrão tem os menores privilégios adequados?",choices:["Admin","Read","Write","Maintain"],explanations:["Admin concede muito mais autoridade que o necessário.","Read permite visualizar e conversar sem autoridade de escrita de código.","Write inclui push de código além do requisito.","Maintain destina-se a gerenciamento mais amplo do repositório."],concept:"Função Read de repositório",hints:["Qual é a capacidade mínima necessária?","Evite conceder administração apenas para participar."]},
    "ghf-187": {prompt:"Uma pessoa de suporte deve rotular e gerenciar issues proativamente, mas não fazer push de código. Qual função padrão é a mais adequada?",choices:["Read","Write","Triage","Admin"],explanations:["Read não fornece a função de gerenciamento proativo pretendida.","Write adiciona push de código além da necessidade.","Triage destina-se a gerenciar issues e pull requests sem escrita.","Admin concede desnecessariamente controle sensível do repositório."],concept:"Função Triage de repositório",hints:["A tarefa exige modificar código?","Qual função fica entre leitura básica e escrita de código?"]},
    "ghf-188": {prompt:"Uma pessoa de engenharia precisa fazer push ativo de código, mas não precisa administrar o repositório. Qual função padrão oferece os menores privilégios adequados?",choices:["Read","Triage","Admin","Write"],explanations:["Read não concede push de código.","Triage permite gerenciar itens de trabalho sem escrita de código.","Admin concede capacidades destrutivas e sensíveis desnecessárias.","Write destina-se a contribuintes ativos de código."],concept:"Função Write de repositório",hints:["Qual permissão é essencial ao trabalho?","Escolha a menor função padrão que inclua atualizar código."]},
    "ghf-189": {prompt:"Uma pessoa gerente de projeto precisa de amplo gerenciamento cotidiano do repositório sem poderes sensíveis ou destrutivos de administrador. Qual função padrão foi projetada para isso?",choices:["Maintain","Read","Triage","Admin"],explanations:["Maintain destina-se ao gerenciamento sem toda a autoridade sensível e destrutiva de Admin.","Read é insuficiente para gerenciamento amplo.","Triage atende principalmente a issues e pull requests sem escrita de código.","Admin inclui poderes que o requisito explicitamente evita."],concept:"Função Maintain de repositório",hints:["A necessidade vai além da triagem de issues?","Qual função deliberadamente fica aquém da administração completa?"]},
    "ghf-190": {prompt:"Entre as funções padrão de repositórios de organização, qual inclui controle completo, com ações destrutivas como excluir o repositório?",choices:["Write","Admin","Triage","Read"],explanations:["Write permite contribuição, não administração completa.","Admin fornece acesso completo, incluindo ações sensíveis e destrutivas.","Triage não concede autoridade para excluir repositórios.","Read limita-se a visualização e participação."],concept:"Função Admin de repositório",hints:["Qual função tem o maior nível padrão de privilégio?","Diferencie capacidades de contribuição de administração destrutiva."]},
    "ghf-191": {prompt:"Uma empresa quer gerenciar acesso a repositórios para todo um grupo de engenharia, não membro a membro. Qual recurso atende a isso?",choices:["Tópicos de repositórios","Marcos de issues","Equipes","Tags de releases"],explanations:["Tópicos categorizam repositórios sem conceder acesso.","Marcos agrupam itens de trabalho.","Equipes agrupam membros de organizações e podem receber permissões de repositório.","Tags identificam versões, não o acesso das pessoas."],concept:"Permissões baseadas em equipes",hints:["O que agrupa pessoas em vez de tarefas?","Como a participação pode simplificar mudanças repetidas de acesso?"]},
    "ghf-192": {prompt:"Uma equipe de engenharia pai recebe escrita em um repositório. Qual relação de acesso vale para suas equipes filhas aninhadas?",choices:["As filhas recebem somente leitura independentemente da concessão ao pai","Permissões do pai nunca afetam as filhas","A concessão alcança equipes irmãs não relacionadas, mas não filhas","As filhas herdam as permissões de acesso ao repositório do pai"],explanations:["A herança não é automaticamente reduzida a leitura.","Equipes aninhadas herdam acesso ao repositório do pai.","A herança segue a relação pai-filho, não equipes irmãs não relacionadas.","Equipes aninhadas herdam permissões de acesso de suas equipes pai."],concept:"Herança de equipes aninhadas",hints:["Em qual direção flui a herança de permissões?","Diferencie uma relação hierárquica da participação em equipes não relacionadas."]},
    "ghf-193": {prompt:"Uma pessoa contratada precisa de acesso a um repositório de organização sem entrar na organização. Qual relação foi projetada para isso?",choices:["Colaborador externo","Proprietário da organização","Mantenedor de equipe pai","Proprietário da empresa"],explanations:["Colaboradores externos podem receber acesso a repositórios específicos sem participação na organização.","A propriedade concede acesso administrativo muito mais amplo e participação.","A participação em equipes é para membros da organização, e a manutenção é desnecessária.","A propriedade empresarial excede muito o escopo indicado."],concept:"Colaboradores externos",hints:["A pessoa precisa de participação ou apenas de acesso ao repositório?","Limite o acesso ao recurso necessário."]},
    "ghf-194": {prompt:"Uma pessoa de finanças precisa gerenciar informações de pagamento sem propriedade completa da organização. Qual função predefinida atende a essa responsabilidade?",choices:["Team maintainer","Billing manager","Triage de repositório","Proprietário de código"],explanations:["Mantenedores de equipe administram configurações da equipe, não pagamentos da organização.","Billing manager gerencia as configurações de cobrança da organização.","Triage de repositório trata do gerenciamento de itens de trabalho.","Propriedade de código encaminha revisões de arquivos."],concept:"Administração de cobrança",hints:["Qual escopo trata de pagamento, não de código?","Evite propriedade completa para uma tarefa administrativa especializada."]},
    "ghf-195": {prompt:"Qual é uma finalidade central do Enterprise Managed Users?",choices:["Manter o provisionamento de contas de funcionários totalmente independente do IdP da empresa","Dar ao IdP controle sobre toda conta pessoal do GitHub não relacionada","Gerenciar provisionamento e autenticação por um provedor de identidade externo","Sincronizar arquivos do repositório com um IdP em vez de gerenciar identidades"],explanations:["EMU integra especificamente o ciclo de vida das contas com o IdP.","Identidades gerenciadas são distintas de controle irrestrito sobre contas pessoais não relacionadas.","Um IdP gerencia o ciclo de vida e a autenticação das contas gerenciadas pela empresa.","EMU trata de identidade e acesso, não de substituir o armazenamento Git."],concept:"Enterprise Managed Users",hints:["Quem deve controlar o ciclo de vida da identidade de funcionários?","Separe gerenciamento de identidade de armazenamento de repositório."]},
    "ghf-196": {prompt:"Uma pessoa com conta de usuário gerenciada quer usá-la para contribuir com um projeto público fora da empresa e sem relação com ela. Qual limitação deve reconhecer?",choices:["Contas gerenciadas tornam-se automaticamente mantenedoras de projetos públicos","Contas gerenciadas são identidades pessoais comuns irrestritas","Marcar o projeto com estrela habilita a colaboração pública","Contas gerenciadas têm restrições de colaboração fora da empresa"],explanations:["O tipo de conta não concede autoridade de manutenção de projetos públicos.","Contas gerenciadas têm restrições específicas da empresa.","Estrelas não alteram os limites das contas gerenciadas.","Identidades gerenciadas não podem ser usadas como contas irrestritas de colaboração externa."],concept:"Limites de contas gerenciadas",hints:["A conta é destinada ao trabalho no escopo da empresa?","Confira restrições de identidade, não popularidade do repositório."]},
    "ghf-197": {prompt:"Uma empresa desativa explicitamente um recurso do Copilot por política. Uma pessoa administradora de organização pode reativá-lo por conta própria para o acesso governado dessa organização?",choices:["Não; a organização não pode substituir essa configuração imposta pela empresa","Sim; configurações da organização sempre prevalecem","Sim; preferências pessoais de membros substituem a restrição empresarial","Sim; uma pessoa administradora de repositório pode substituí-la em um repositório"],explanations:["Políticas empresariais obrigatórias limitam configurações da organização.","As opções da organização ficam dentro das restrições impostas pela empresa.","Preferências individuais não superam a restrição empresarial do acesso governado.","Administrar repositórios não substitui uma política empresarial obrigatória de recursos do Copilot."],concept:"Precedência de políticas do Copilot",hints:["Qual escopo administrativo definiu a restrição?","Diferencie escolhas delegadas de políticas impostas."]},
    "ghf-198": {prompt:"Uma organização quer controlar os recursos e modelos do Copilot disponíveis a membros licenciados por ela. Onde uma pessoa administradora autorizada deve gerenciar isso?",choices:["Somente nas preferências individuais do editor","Nas políticas do Copilot da organização, sujeitas à política empresarial","Somente em CODEOWNERS","Somente na proteção da branch main"],explanations:["Preferências pessoais do editor não estabelecem política de serviço para toda a organização.","Políticas organizacionais do Copilot controlam recursos e modelos dentro das restrições empresariais.","Propriedade de código define responsabilidade de revisão, não recursos do Copilot.","Proteção de branches governa alterações, não políticas organizacionais de modelos do Copilot."],concept:"Governança organizacional do Copilot",hints:["Qual escopo administrativo concede essas licenças?","Separe políticas de serviço de regras de fluxo do repositório."]},
    "ghf-199": {prompt:"Uma equipe quer que main aceite alterações somente após revisão exigida e verificações aprovadas para quem não pode ignorar regras. O que deve configurar?",choices:["Somente um nome descritivo de branch","Um pedido de cuidado no README","Proteção de branches ou um conjunto de regras adequado","Um tópico chamado protected"],explanations:["Nomes não impõem requisitos de mesclagem.","Orientações escritas não implementam barreiras técnicas.","Proteções e conjuntos de regras podem exigir revisão e verificações.","Tópicos são metadados de descoberta, não de imposição de regras."],concept:"Requisitos de branches protegidas",hints:["Uma convenção escrita é suficiente?","Quais configurações podem bloquear uma integração que descumpre requisitos?"]},
    "ghf-200": {prompt:"Uma pessoa administradora pode ignorar uma regra clássica de proteção de branches. A equipe quer aplicá-la também a administradores. O que deve examinar?",choices:["Somente a quantidade de verificações obrigatórias","Somente os padrões de caminhos do CODEOWNERS","Somente se o nome da branch contém main","As configurações de aplicação da regra relacionadas a exceções"],explanations:["Adicionar verificações sozinho não remove a isenção administrativa.","Padrões de propriedade identificam revisores, não determinam exceções administrativas.","Um nome de branch sozinho não impõe restrições a administradores.","A proteção clássica pode ser configurada para restringir administradores em vez de permitir a exceção padrão."],concept:"Exceções à proteção de branches",hints:["Quem está isento da regra atual?","Revise o escopo de aplicação em vez de adicionar requisitos."]}
    ,"ghf-201": {prompt:"Uma organização usa regras clássicas de proteção de branches e vários padrões correspondem a uma branch. O que a administração deve saber?",choices:["Só uma regra clássica se aplica por vez; conjuntos de regras têm outro modelo de sobreposição","Todas as regras clássicas correspondentes sempre são combinadas","O commit mais recente escolhe uma regra aleatoriamente","A correspondência a vários padrões desativa a proteção"],explanations:["A proteção clássica usa uma regra aplicável, ao contrário de conjuntos de regras sobrepostos.","Regras clássicas não se combinam só porque os padrões correspondem.","A seleção de regra não é aleatória por commit.","Padrões sobrepostos não desativam a proteção inerentemente."],concept:"Regras de branches versus conjuntos de regras",hints:["A pergunta trata de regras clássicas ou conjuntos de regras?","Não presuma que os modelos de combinação sejam idênticos."]},
    "ghf-202": {prompt:"Um token de acesso válido foi commitado acidentalmente em um repositório público. Qual deve ser a primeira resposta em relação à credencial?",choices:["Somente excluir o arquivo em um novo commit","Revogar ou rotacionar a credencial exposta","Renomear a branch que a contém","Adicionar o arquivo do token ao .gitignore e parar"],explanations:["Cópias históricas e a exposição existente permanecem após uma exclusão comum.","Revogar ou rotacionar retira a utilidade da credencial exposta para acesso.","Renomear não invalida o token.","Regras de exclusão não invalidam credenciais nem apagam commits anteriores."],concept:"Credenciais expostas",hints:["Alguém já pode ter copiado o valor?","O que impede esse valor de autorizar solicitações?"]},
    "ghf-203": {prompt:"Uma pessoa cria um token de acesso pessoal com permissões amplas. Ele pode dar poderes de proprietário de organização que a pessoa não possui?",choices:["Sim; conceder um escopo de administração também promove seu proprietário","Sim; credenciais de API são isentas das permissões de repositório do usuário","Não; um token não pode exceder o acesso de seu proprietário","Sim; omitir a expiração concede autoridade administrativa"],explanations:["Um escopo não promove a identidade subjacente a proprietária da organização.","Credenciais de API não ignoram os limites de autorização do proprietário.","Um token é limitado pelo acesso do proprietário e pelas permissões concedidas.","A expiração afeta a duração da credencial, não eleva a autoridade."],concept:"Limites de autoridade de tokens",hints:["O token representa a autoridade de quem?","Uma credencial pode conceder poderes ausentes da identidade por trás dela?"]},
    "ghf-204": {prompt:"Uma tarefa de automação compatível precisa ler um repositório por um token de acesso pessoal refinado. Qual configuração segue o privilégio mínimo?",choices:["Todos os repositórios com todas as permissões","Administração da organização mesmo sem uso","Escrita em repositórios não relacionados","Somente o repositório e as permissões de leitura necessários"],explanations:["Acesso amplo excede a necessidade indicada.","Autoridade administrativa não usada aumenta o risco.","Escrita não relacionada é desnecessária.","Restringir o escopo de repositórios e as permissões limita a exposição potencial."],concept:"Escopo de tokens refinados",hints:["Qual é o menor conjunto de recursos necessário?","Uma tarefa somente de leitura deve receber escrita?"]},
    "ghf-205": {prompt:"Uma empresa quer um nível padrão de permissões de repositório para membros da organização antes de concessões adicionais. Qual configuração atende a isso?",choices:["Permissões base da organização","Uma concessão direta a um colaborador em um repositório","Uma entrada CODEOWNERS para cada caminho de código","Uma quantidade de revisões obrigatórias na branch padrão"],explanations:["Permissões base definem o acesso padrão de membros a repositórios da organização.","Uma concessão específica não estabelece a base para todos os membros.","Entradas de propriedade encaminham revisões, não concedem acesso padrão organizacional.","Contagens de revisão controlam requisitos de integração, não padrões gerais de acesso."],concept:"Permissões base da organização",hints:["Qual é a base antes de concessões específicas a equipes ou pessoas?","Qual escopo gerencia padrões para todos os membros?"]},
    "ghf-206": {prompt:"Uma equipe está prestes a tornar público um repositório confidencial. Qual revisão trata mais diretamente do risco de divulgar informações sensíveis?",choices:["Verificar só o README atual e presumir que o resto está oculto","Verificar arquivos atuais e histórico preservado em busca de informações sensíveis","Somente verificar se notificações estão habilitadas","Somente confirmar que existe um pull request aberto"],explanations:["Outros arquivos e revisões anteriores também podem divulgar informações.","A visibilidade pública pode expor conteúdo e histórico; materiais sensíveis precisam ser avaliados.","Notificações não determinam o que leitores públicos podem acessar.","A existência de pull request não comprova segurança de divulgação."],concept:"Risco de mudar visibilidade",hints:["O que um novo leitor público poderia examinar?","Excluir um valor da revisão mais recente apaga seu passado?"]},
    "ghf-207": {prompt:"Um repositório tem proprietários de código configurados, mas uma pessoa proposta como proprietária tem somente Read. O que deve ser corrigido para ela atuar como proprietária de código?",choices:["Ela só precisa assinar todos os pull requests","Read basta quando seu nome aparece em CODEOWNERS","Ela precisa da permissão de escrita exigida no repositório","Mover a regra para docs/ elimina o requisito de acesso"],explanations:["Assinaturas não concedem elegibilidade como proprietário de código.","Uma entrada de propriedade não concede a permissão necessária.","Proprietários de código devem ter escrita no repositório.","Mudar a localização compatível não dispensa o requisito de acesso."],concept:"Requisito de acesso de proprietários de código",hints:["Encaminhar responsabilidade substitui requisitos de acesso?","Confira a permissão mínima documentada para proprietários."]},
    "ghf-208": {prompt:"Uma organização usa uma biblioteca de código aberto e quer apoiar financeiramente seus mantenedores elegíveis pelo GitHub. Qual recurso deve considerar?",choices:["Um tópico de repositório","Um revisor obrigatório","Uma regra de branch","GitHub Sponsors"],explanations:["Tópicos ajudam a descobrir, não transferem apoio financeiro.","Solicitações de revisão pedem feedback sobre alterações.","Regras de branches impõem fluxos de repositório.","Sponsors facilita apoio financeiro a pessoas e organizações elegíveis de código aberto."],concept:"GitHub Sponsors",hints:["A contribuição desejada é dinheiro ou código?","Qual serviço apoia a sustentabilidade de quem mantém projetos?"]},
    "ghf-209": {prompt:"Uma pessoa de design quer contribuir com um projeto de código aberto, mas não programa. Qual contribuição ainda é valiosa?",choices:["Melhorar a documentação de usabilidade e relatar etapas claras de reprodução","Só aumentar as estrelas do repositório conta como contribuição","Contribuições devem ser arquivos de código compilado","Somente proprietários podem relatar problemas de usuários"],explanations:["Documentação, feedback de design e problemas bem descritos podem impulsionar o trabalho de código aberto.","Estrelas expressam interesse, mas a participação útil vai muito além.","Contribuições não se limitam a código compilado.","Usuários podem relatar problemas pelos canais aceitos pelo projeto."],concept:"Contribuições sem código",hints:["O que ajuda usuários e mantenedores além da implementação?","Considere a experiência inteira do projeto."]},
    "ghf-210": {prompt:"Uma pessoa iniciante escolhe sua primeira contribuição. Qual sinal é mais útil para encontrar trabalho que o projeto pretende tornar acessível a iniciantes?",choices:["A issue com mais comentários, independentemente do assunto","Uma issue com o rótulo good first issue, considerando também o contexto e as diretrizes","O pull request pendente mais antigo, independentemente do escopo","O repositório com mais estrelas, independentemente da dificuldade"],explanations:["Muitos comentários podem indicar complexidade, não adequação a iniciantes.","Mantenedores usam good first issue para destacar trabalho acessível, mas o contexto ainda importa.","A idade sozinha não torna o trabalho adequado a iniciantes.","Popularidade não indica se uma tarefa individual é adequada."],concept:"Busca de trabalho para iniciantes",hints:["Qual sinal explícito os mantenedores podem fornecer?","Um rótulo é útil sem ler a tarefa real?"]},
    "ghf-211": {prompt:"Antes de iniciar uma contribuição substancial a um projeto desconhecido, o que a pessoa deve fazer?",choices:["Presumir que seu fluxo habitual prevalece sobre as convenções do projeto","Mudar a licença sem discussão","Ler as diretrizes e discutir o escopo quando adequado","Exigir escrita direta antes de investigar"],explanations:["Projetos podem ter requisitos e convenções diferentes.","Mudar licenças exige autorização cuidadosa; não é uma suposição inicial.","Entender expectativas e coordenar escopo aumenta a chance de uma contribuição útil.","Contribuições externas costumam usar forks e pull requests sem escrita direta."],concept:"Respeito aos processos de contribuição",hints:["Como evitar retrabalho desnecessário?","De quem são as convenções que regem o projeto receptor?"]},
    "ghf-212": {prompt:"Uma pessoa não tem escrita em um projeto público original, mas quer propor uma alteração de código. Qual fluxo é adequado?",choices:["Editar um ZIP local e presumir que o original será atualizado","Marcar com estrela para ganhar push","Criar uma cópia de template e presumir que já está vinculada para contribuição","Criar um fork, commitar alterações em uma branch e abrir um pull request ao original"],explanations:["Edições de ZIP não são enviadas automaticamente ao original.","Estrelas não concedem escrita.","Um template cria um projeto independente, não a relação normal de fork.","Alterações baseadas em forks podem ser propostas ao original por pull requests."],concept:"Contribuições por forks",hints:["Onde a pessoa pode fazer push do próprio trabalho?","Como se pede ao projeto original que o revise?"]},
    "ghf-213": {prompt:"Um fork ficou atrasado em relação ao projeto original. O que fazer antes de trabalhar sobre as alterações mais recentes do original?",choices:["Sincronizar o fork com as alterações do original","Criar uma branch local a partir da branch padrão antiga e inalterada","Fazer push novamente sem recuperar commits do original","Baixar um ZIP do original e presumir que o histórico hospedado do fork mudou"],explanations:["Sincronizar incorpora as alterações atuais do original ao histórico do fork.","Criar uma branch a partir de histórico antigo não recupera alterações ausentes.","Publicar o mesmo histórico não incorpora trabalho do original.","Baixar um arquivo compactado não atualiza o histórico de um fork hospedado."],concept:"Manter um fork atualizado",hints:["Qual repositório é a fonte do trabalho mais recente?","Qual operação volta a alinhar os dois históricos?"]},
    "ghf-214": {prompt:"Uma pessoa nota instruções de configuração desatualizadas em um template comunitário e quer que futuros projetos gerados recebam instruções corrigidas. Onde deve propor a correção compartilhada?",choices:["Somente no README de um projeto já gerado","Em um pull request ao próprio repositório do template","Somente em uma cópia local não compartilhada","Somente renomeando seu repositório gerado"],explanations:["Mudar um projeto gerado não atualiza o template para futuros usuários.","Atualizar o template original melhora os arquivos iniciais de futuros projetos gerados.","Uma edição não compartilhada não melhora o template comunitário.","O nome de um repositório gerado não altera o conteúdo do template."],concept:"Contribuição com templates compartilhados",hints:["Qual repositório fornece o conteúdo inicial futuro?","Editar um projeto gerado atualiza o padrão de origem?"]},
    "ghf-215": {prompt:"Uma empresa incentiva equipes a descobrir e contribuir com os projetos empresariais privados umas das outras usando pull requests e práticas compartilhadas de manutenção. Como se chama essa abordagem?",choices:["Dedicação ao domínio público","Arquivamento de repositórios","InnerSource","Espelhamento anônimo"],explanations:["Dedicação ao domínio público trata de direitos legais, não de práticas de colaboração interna.","Arquivar torna projetos inativos.","InnerSource aplica colaboração ao estilo do código aberto dentro de uma organização ou empresa.","Espelhar copia conteúdo, mas não descreve essa cultura de contribuição."],concept:"InnerSource",hints:["Onde as práticas do código aberto estão sendo aplicadas?","Colaborar exige tornar o código público?"]},
    "ghf-216": {prompt:"Um serviço interno reutilizável e não sensível é difícil de encontrar por outras equipes da empresa. Qual mudança apoia mais diretamente a descoberta InnerSource sem torná-lo público?",choices:["Mantê-lo inacessível a outras equipes e depender do boca a boca","Publicar só o nome sem acesso nem documentação","Mover a documentação para um repositório pessoal não divulgado","Usar visibilidade interna adequada, tópicos úteis e documentação clara"],explanations:["Código inacessível e descoberta informal dificultam a reutilização entre equipes.","Um nome sozinho não permite examinar e entender o serviço.","Documentação pessoal não divulgada dificulta a descoberta compartilhada.","Visibilidade adequada e documentação encontrável ajudam equipes autorizadas a descobrir e reutilizar trabalho."],concept:"InnerSource fácil de descobrir",hints:["Funcionários podem encontrar e entender o projeto?","Separe descoberta interna mais ampla de publicação pública."]},
    "ghf-217": {prompt:"Uma pessoa quer ver a atividade pública de alguém que mantém projetos em sua experiência de atividade do GitHub. Qual ação é relevante?",choices:["Seguir a conta dessa pessoa","Assinar uma issue como substituto de segui-la","Clonar um repositório como substituto de segui-la","Fixar o próprio repositório e presumir que isso assina a pessoa"],explanations:["Seguir pessoas ajuda a acompanhar sua atividade pública.","Uma assinatura de issue se limita à conversa, não à atividade mais ampla de uma pessoa.","Clonar copia histórico sem seguir uma conta.","Fixar um repositório personaliza um perfil, não segue outra pessoa."],concept:"Seguir pessoas",hints:["O interesse está em uma discussão ou na atividade mais ampla de alguém?","Qual relação permite acompanhar sem elevar o acesso?"]},
    "ghf-218": {prompt:"Uma pessoa segue uma organização no GitHub. O que deve esperar dessa ação?",choices:["Participação em todas as equipes privadas","Uma forma de acompanhar atividade pública, não acesso a repositórios privados","Escrita em todos os repositórios da organização","Uma cópia de todos os repositórios no computador"],explanations:["Seguir não é participar de equipes.","Seguir ajuda a mostrar atividade pública sem conceder acesso privado.","Escrita exige uma concessão separada.","Seguir não clona repositórios."],concept:"Seguir organizações",hints:["Interesse implica participação?","Separe descoberta de atividade de autorização."]},
    "ghf-219": {prompt:"Uma equipe quer um catálogo de integrações e automações reutilizáveis que ampliem os fluxos do GitHub. Qual destino foi projetado para isso?",choices:["Somente o histórico de execuções de um repositório","Somente o seletor de templates de issues de um projeto","GitHub Marketplace","Somente o formulário pessoal de criação de repositórios"],explanations:["O histórico registra execuções, não um catálogo de ferramentas.","Templates de issues orientam o recebimento de trabalho, não listam integrações.","Marketplace ajuda a descobrir aplicativos e Actions.","Opções de criação de repositórios não fornecem o catálogo de integrações."],concept:"GitHub Marketplace",hints:["O objetivo é um catálogo de ferramentas?","Qual destino inclui integrações e componentes de automação?"]},
    "ghf-220": {prompt:"Uma equipe encontra um aplicativo atraente de terceiros no GitHub Marketplace. O que deve avaliar antes de instalá-lo em repositórios de trabalho?",choices:["Somente se as capturas de tela são atraentes","Somente se outra equipe usa, ignorando o acesso solicitado","Somente se tem opção gratuita, ignorando fornecedor e permissões","As permissões solicitadas, o fornecedor e a adequação às necessidades da organização"],explanations:["Capturas de tela sozinhas não estabelecem confiança nem adequação.","O uso por outra equipe não substitui a avaliação de acesso para esta organização.","Preço sozinho não avalia riscos de acesso nem adequação.","Instalar aplicativos pode conceder acesso; permissões e confiança no fornecedor precisam ser avaliadas."],concept:"Avaliação de integrações do Marketplace",hints:["Qual autoridade a instalação pode conceder?","Ser encontrável comprova adequação por si só?"]},
    "ghf-221": {prompt:"Um repositório público contém código útil, mas não tem licença. O que uma pessoa interessada em usá-lo não deve presumir?",choices:["Que a visibilidade pública sozinha concede ampla permissão de reutilização e redistribuição","Que o código-fonte pode ser lido no GitHub","Que o repositório pode ter issues","Que seus arquivos podem ter histórico de commits"],explanations:["Visibilidade pública não substitui uma licença que conceda direitos de reutilização.","Código público normalmente pode ser lido, sujeito à disponibilidade de acesso.","Repositórios públicos podem usar issues.","Arquivos Git podem manter histórico independentemente do licenciamento."],concept:"Visibilidade aberta versus direitos de código aberto",hints:["Ver código estabelece termos legais de reutilização?","Separe acessibilidade técnica de licenciamento."]},
    "ghf-222": {prompt:"Qual é um benefício realista de participar de um projeto de código aberto pelo GitHub?",choices:["Aceitação garantida de toda alteração proposta","Aprender com revisões e colaborar com pessoas além da própria equipe","Propriedade automática de todas as dependências","Eliminar a necessidade de cumprir licenças"],explanations:["Mantenedores ainda decidem se as alterações se encaixam no projeto.","Contribuir pode desenvolver habilidades e relações pelo trabalho compartilhado e feedback.","Participar não transfere a propriedade das dependências.","Obrigações de licença continuam válidas."],concept:"Benefícios de participar de código aberto",hints:["Quais resultados dependem de aprendizado compartilhado, não de garantias?","Diferencie oportunidade de direito adquirido."]},
    "ghf-223": {prompt:"Um projeto de código aberto quer que contribuintes entendam o comportamento esperado e o tratamento de condutas inaceitáveis. Qual documento é destinado a isso?",choices:["Um arquivo de lock de dependências","Uma lista de tags de versões","Um código de conduta","Somente uma convenção de nomes de branches"],explanations:["Arquivos de lock registram a resolução de dependências.","Tags identificam versões.","Um código de conduta define expectativas de comportamento e orientações de relato.","Nomes de branches não definem conduta comunitária nem processos de relato."],concept:"Conduta comunitária",hints:["A política trata do comportamento de pessoas ou de versões de arquivos?","O que ajuda a criar um ambiente respeitoso de participação?"]},
    "ghf-224": {prompt:"Uma organização elegível de código aberto quer receber apoio financeiro pelo GitHub Sponsors. Qual afirmação sobre os tipos de contas receptoras está correta?",choices:["Só indivíduos recebem; organizações só patrocinam","Organizações só se qualificam se converterem repositórios em pessoais","Organizações só recebem compartilhando o login pessoal de um mantenedor","Tanto organizações quanto indivíduos elegíveis podem receber patrocínios"],explanations:["Organizações elegíveis podem participar como receptoras e patrocinadoras.","Receber patrocínios não exige converter repositórios de organização em pessoais.","Credenciais pessoais compartilhadas não são o modelo de patrocínio organizacional.","GitHub Sponsors aceita pessoas e organizações elegíveis."],concept:"Receptores de patrocínios",hints:["A manutenção pode ser organizada coletivamente?","Separe requisitos de elegibilidade de suposições sobre tipos de conta."]},
    "ghf-225": {prompt:"Uma pessoa quer descobrir repositórios públicos sobre dados climáticos de vários proprietários. Qual abordagem é mais útil?",choices:["Buscar tópicos relevantes de repositórios e explorar projetos correspondentes","Examinar somente seus remotos locais","Buscar somente arquivos de um repositório já clonado","Examinar somente issues atribuídas a ela em um projeto"],explanations:["Tópicos e busca de repositórios permitem descobrir projetos por assunto.","Remotos locais descrevem apenas repositórios já configurados localmente.","Um único repositório local não fornece descoberta ampla de projetos.","Issues atribuídas são um subconjunto pessoal restrito, não descoberta entre proprietários."],concept:"Descoberta de projetos por tópicos",hints:["Onde metadados de assuntos são compartilhados entre repositórios?","Diferencie descobrir projetos de organizar trabalho já conhecido."]}
  }
};
